import { useEffect, useState } from "react";
import AdminLoginPage from "./pages/AdminLoginPage";
import AdminPage from "./pages/AdminPage";
import { useAppStore } from "./store/appStore";
import { LogOut, Building2, Scale } from "lucide-react";

function getHashPath() {
  const raw = window.location.hash.replace(/^#/, "") || "/admin";
  return raw.split("?")[0] || "/admin";
}

export default function AdminApp() {
  const { getCurrentUser, logout } = useAppStore();
  const [path, setPath] = useState(getHashPath());

  useEffect(() => {
    const handler = () => setPath(getHashPath());
    window.addEventListener("hashchange", handler);
    return () => window.removeEventListener("hashchange", handler);
  }, []);

  if (!path.startsWith("/admin")) return null;

  const currentUser = getCurrentUser();

  if (!currentUser || currentUser.role !== "super_admin") {
    return <AdminLoginPage onLogin={() => {}} />;
  }

  return (
    <div className="flex flex-col min-h-screen" style={{ background: "linear-gradient(160deg,#0a0e1e 0%,#12204a 55%,#0f2a5f 100%)" }}>
      <div className="flex items-center justify-between px-6 py-3 border-b border-white/10" style={{ background: "rgba(0,0,0,0.25)" }}>
        <div className="flex items-center gap-3">
          <div
            className="w-9 h-9 rounded-lg flex items-center justify-center shadow-lg"
            style={{ background: "linear-gradient(135deg,#1a2d5a,#2d4e8f)", border: "1px solid rgba(212,175,55,0.4)" }}
          >
            <Scale className="w-4.5 h-4.5 text-gold-400" />
          </div>
          <div>
            <div className="text-sm font-bold text-white">AI 律师 · 后台管理系统</div>
            <div className="text-[10px] text-white/45">仅超级管理员可访问</div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <a
            href="#/"
            className="inline-flex items-center gap-1.5 text-[11px] px-3 py-1.5 rounded-md text-white/70 hover:text-white hover:bg-white/10 transition-all"
          >
            <Building2 className="w-3.5 h-3.5" />
            返回用户端
          </a>
          <button
            onClick={() => { logout(); location.reload(); }}
            className="inline-flex items-center gap-1.5 text-[11px] px-3 py-1.5 rounded-md text-white/70 hover:text-red-300 hover:bg-red-500/10 transition-all"
          >
            <LogOut className="w-3.5 h-3.5" />
            退出
          </button>
        </div>
      </div>

      <div className="flex-1">
        <AdminPage />
      </div>
    </div>
  );
}
