export function mdToHtml(md: string): string {
  if (!md) return "";
  const lines = md.split("\n");
  const html: string[] = [];
  let listType: null | "ul" | "ol" = null;
  let inCode = false;
  let inQuote = false;

  const flushList = () => {
    if (listType) {
      html.push(`</${listType}>`);
      listType = null;
    }
  };

  const inline = (s: string) => {
    let out = s;
    out = out.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    out = out.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    out = out.replace(/`([^`]+)`/g, "<code>$1</code>");
    return out;
  };

  for (let i = 0; i < lines.length; i++) {
    let l = lines[i];

    if (inCode) {
      if (l.trim() === "```") {
        html.push("</pre>");
        inCode = false;
      } else {
        html.push(l);
      }
      continue;
    }

    if (l.trim().startsWith("```")) {
      flushList();
      html.push("<pre>");
      inCode = true;
      continue;
    }

    if (l.startsWith("### ")) {
      flushList();
      html.push(`<h3>${inline(l.slice(4).trim())}</h3>`);
      continue;
    }
    if (l.startsWith("## ")) {
      flushList();
      html.push(`<h2>${inline(l.slice(3).trim())}</h2>`);
      continue;
    }
    if (l.startsWith("# ")) {
      flushList();
      html.push(`<h1>${inline(l.slice(2).trim())}</h1>`);
      continue;
    }

    if (l.startsWith("> ")) {
      flushList();
      if (!inQuote) {
        html.push("<blockquote>");
        inQuote = true;
      }
      html.push(`<div>${inline(l.slice(2))}</div>`);
      continue;
    } else if (inQuote) {
      html.push("</blockquote>");
      inQuote = false;
    }

    const ulMatch = l.match(/^\s*[-*]\s+(.*)$/);
    const olMatch = l.match(/^\s*\d+\.\s+(.*)$/);
    if (ulMatch) {
      if (listType !== "ul") { flushList(); html.push("<ul>"); listType = "ul"; }
      html.push(`<li>${inline(ulMatch[1])}</li>`);
      continue;
    }
    if (olMatch) {
      if (listType !== "ol") { flushList(); html.push("<ol>"); listType = "ol"; }
      html.push(`<li>${inline(olMatch[1])}</li>`);
      continue;
    }

    if (!l.trim()) {
      flushList();
      if (inQuote) { html.push("</blockquote>"); inQuote = false; }
      html.push("");
      continue;
    }

    flushList();
    if (inQuote) { html.push("</blockquote>"); inQuote = false; }
    html.push(`<p>${inline(l)}</p>`);
  }

  flushList();
  if (inQuote) html.push("</blockquote>");
  if (inCode) html.push("</pre>");

  return html.join("\n");
}
