import { AlertTriangle, ArrowRight, Bell, FileUp, X } from "lucide-react";
import { useMemo, useState } from "react";
import { useAppStore } from "../store/appStore";
import { useCaseStore } from "../store/caseStore";
import { getMissingMaterials } from "../lib/materialGuide";

export default function MissingMaterialsBubble({ activeTab }: { activeTab: string }) {
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const { getCasesByUser, getEvidences } = useCaseStore();
  const [closed, setClosed] = useState(false);

  const target = useMemo(() => {
    if (!currentUser || activeTab === "evidence") return null;
    const cases = getCasesByUser(currentUser.id).sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
    for (const c of cases) {
      const missing = getMissingMaterials(c, getEvidences(c.id));
      if (missing.length > 0) return { caseObj: c, missing };
    }
    return null;
  }, [currentUser, activeTab, getCasesByUser, getEvidences]);

  if (closed || !target) return null;

  const openEvidence = () => {
    window.location.hash = `#/?tab=evidence&caseId=${target.caseObj.id}&showMissing=1`;
  };

  return (
    <div className="fixed right-6 bottom-6 z-50 w-[360px] rounded-2xl overflow-hidden shadow-[0_18px_60px_rgba(0,0,0,0.55)]" style={{ background: "linear-gradient(180deg,#111a3c,#0a0f24)", border: "1px solid rgba(245,158,11,0.38)", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <div className="absolute -right-8 -top-8 w-28 h-28 rounded-full bg-amber-400/20 blur-2xl" />
      <div className="relative p-4">
        <div className="flex items-start gap-3">
          <div className="w-11 h-11 rounded-2xl flex items-center justify-center shrink-0 bg-gradient-to-br from-amber-500 to-orange-600 text-white shadow-lg shadow-amber-900/30">
            <Bell className="w-5 h-5" />
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-start justify-between gap-2">
              <div>
                <div className="text-white font-bold text-[14px] flex items-center gap-1.5"><AlertTriangle className="w-3.5 h-3.5 text-amber-300" />发现材料缺失</div>
                <div className="text-[11px] text-slate-400 mt-0.5 truncate">{target.caseObj.title}</div>
              </div>
              <button onClick={() => setClosed(true)} className="p-1 rounded-lg text-slate-500 hover:text-white hover:bg-white/5"><X className="w-3.5 h-3.5" /></button>
            </div>
            <div className="mt-3 flex flex-wrap gap-1.5">
              {target.missing.slice(0, 4).map((m) => <span key={m} className="px-2 py-1 rounded-lg text-[10px] text-amber-100 bg-amber-500/12 border border-amber-500/22">{m}</span>)}
              {target.missing.length > 4 && <span className="px-2 py-1 rounded-lg text-[10px] text-slate-300 bg-white/5 border border-white/10">+{target.missing.length - 4}</span>}
            </div>
            <button onClick={openEvidence} className="mt-3 w-full inline-flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-amber-600 to-orange-600 hover:from-amber-500 hover:to-orange-500 transition-all">
              <FileUp className="w-4 h-4" /> 去上传/补充材料 <ArrowRight className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
