import { lawLibrary } from "./lawLibrary";
import { getSimilarCases, formatNow } from "./templates";
import type { Case, EvidenceItem, AnalysisResult, DefenseMaterial, ApplicableLaw, Risk } from "../store/caseStore";

interface DetectedKeywords {
  type: string;
  keywords: string[];
  patternLabel: string;
}

function detectKeywords(facts: string): DetectedKeywords {
  const t = facts || "";
  const contains = (ks: string[]) => ks.some((k) => t.includes(k));

  if (contains(["辞退", "解除", "解雇", "不续签", "赶人", "违法解除"])) {
    return { type: "劳动争议", keywords: ["辞退", "解除", "劳动合同"], patternLabel: "劳动争议-违法解除" };
  }
  if (contains(["工伤", "上班受伤", "工作中受伤"])) {
    return { type: "劳动争议", keywords: ["工伤"], patternLabel: "劳动争议-工伤认定" };
  }
  if (contains(["工资", "欠薪", "拖欠", "不发工资", "加班"])) {
    return { type: "劳动争议", keywords: ["工资", "拖欠"], patternLabel: "劳动争议-欠薪/加班费" };
  }
  if (contains(["合同", "购房", "买房", "卖房", "定金", "违约"])) {
    return { type: "合同纠纷", keywords: ["合同"], patternLabel: "合同纠纷-买卖/定金" };
  }
  if (contains(["租房", "房租", "租赁"])) {
    return { type: "合同纠纷", keywords: ["租赁"], patternLabel: "合同纠纷-房屋租赁" };
  }
  if (contains(["撞", "车祸", "事故", "撞车", "电动车", "交警", "保险", "酒驾"])) {
    return { type: "道路交通", keywords: ["交通事故"], patternLabel: "交通事故-人身损害" };
  }
  if (contains(["受伤", "打", "推搡", "医疗", "医院", "骨折", "摔倒"])) {
    return { type: "侵权责任", keywords: ["人身损害"], patternLabel: "侵权-人身损害" };
  }
  if (contains(["诈骗", "欺诈", "假货", "退款", "商家", "平台", "网购", "刷单"])) {
    return { type: "消费者权益", keywords: ["欺诈"], patternLabel: "消费者-欺诈/假货" };
  }
  if (contains(["离婚", "出轨", "家暴", "抚养权", "夫妻", "离婚协议"])) {
    return { type: "婚姻家庭", keywords: ["离婚"], patternLabel: "婚姻家庭" };
  }
  return { type: "其他", keywords: [], patternLabel: "其他" };
}

function pickLawsForType(type: string, facts: string): ApplicableLaw[] {
  const all: ApplicableLaw[] = [];
  const contains = (k: string) => facts.includes(k);
  const hits = lawLibrary.filter((l) =>
    facts.includes(l.title) || facts.includes(l.article.replace("第", "").replace("条", "").slice(0, 6))
  );
  hits.forEach((l) =>
    all.push({ lawId: l.id, law: `${l.title} ${l.article}`, article: l.article, summary: l.summary, reason: "案件事实涉及" + l.title })
  );

  if (type === "劳动争议") {
    all.push({ lawId: "law-002", law: "劳动合同法 第八十七条", article: "第八十七条", summary: "违法解除需支付双倍经济补偿", reason: "单位单方解除，首先判断是否违法" });
    all.push({ lawId: "law-001", law: "劳动合同法 第四十七条", article: "第四十七条", summary: "经济补偿按工作年限，每满一年一个月工资", reason: "计算经济补偿基数和年限" });
    all.push({ lawId: "law-021", law: "劳动争议司法解释一 第四十四条", article: "第四十四条", summary: "单位作出解除决定的，单位负举证责任", reason: "非常关键——解雇事由由单位举证是否成立" });
    all.push({ lawId: "law-019", law: "劳动争议调解仲裁法 第二十七条", article: "第二十七条", summary: "劳动仲裁时效一年", reason: "确认是否在仲裁时效内" });
    if (contains("未签") || contains("没签") || contains("没有合同")) {
      all.push({ lawId: "law-003", law: "劳动合同法 第十条 / 第八十二条", article: "第十条", summary: "建立劳动关系应当订立书面合同，未签应支付双倍工资", reason: "未签合同可主张双倍工资" });
    }
  } else if (type === "合同纠纷") {
    all.push({ lawId: "law-005", law: "民法典 第五百七十七条", article: "第五百七十七条", summary: "违约责任：继续履行/补救/赔偿", reason: "违约的一般规定" });
    if (contains("定金") || contains("订金")) {
      all.push({ lawId: "law-006", law: "民法典 第五百八十六条", article: "第五百八十六条", summary: "定金罚则：违约方无权要回或双倍返还", reason: "定金罚则适用" });
    }
    all.push({ lawId: "law-004", law: "民法典 第四百九十条", article: "第四百九十条", summary: "合同成立要件", reason: "判断合同是否成立" });
  } else if (type === "道路交通" || type === "侵权责任") {
    all.push({ lawId: "law-007", law: "民法典 第一千一百六十五条", article: "第一千一百六十五条", summary: "过错责任原则", reason: "判断侵权责任的基础" });
    all.push({ lawId: "law-008", law: "民法典 第一千一百七十九条", article: "第一千一百七十九条", summary: "人身损害赔偿项目", reason: "明确赔偿项目范围" });
    all.push({ lawId: "law-022", law: "人身损害司法解释 第六条", article: "第六条", summary: "医疗费凭收款凭证", reason: "各项赔偿项目的具体计算标准" });
    if (type === "道路交通") {
      all.push({ lawId: "law-009", law: "道路交通安全法 第七十六条", article: "第七十六条", summary: "交强险先行，不足按责任分担", reason: "交强险 + 责任比例" });
    }
  } else if (type === "消费者权益") {
    all.push({ lawId: "law-010", law: "消费者权益保护法 第五十五条", article: "第五十五条", summary: "欺诈三倍赔偿，不足五百按五百", reason: "退一赔三的核心依据" });
  }

  return all.length ? all.slice(0, 6) : [
    { lawId: "law-005", law: "民法典 第五百七十七条", article: "第五百七十七条", summary: "违约责任一般规定", reason: "任何合同类纠纷均可能适用" },
    { lawId: "law-015", law: "民事诉讼法 第六十七条", article: "第六十七条", summary: "谁主张谁举证", reason: "证据准备是关键" },
  ];
}

function pickRisks(type: string, facts: string): Risk[] {
  const list: Risk[] = [];
  if (type === "劳动争议") {
    if (facts.includes("口头") || facts.includes("微信") || !facts.includes("书面")) {
      list.push({ level: "high", text: "没有书面解除通知书 —— 单位可能主张 '你是自己走的'" });
    }
    list.push({ level: "mid", text: "工资构成中绩效部分可能被压低，经济补偿基数有争议空间" });
    list.push({ level: "mid", text: "仲裁时效一年 —— 从知道被辞退之日起算，别拖" });
    list.push({ level: "low", text: "需提供劳动关系证据（工牌、打卡记录、同事证言、群聊截图等补强）" });
  } else if (type === "合同纠纷") {
    if (facts.includes("定金")) {
      list.push({ level: "high", text: "定金 vs 订金 —— 写'订'不适用双倍罚则！看合同写的是哪个字" });
    }
    list.push({ level: "mid", text: "违约金条款 —— 合同里有约定吗？超过实际损失 30% 的部分可以请求调低" });
    list.push({ level: "low", text: "继续履行 vs 解除合同：二选一，明确你的诉求" });
  } else if (type === "道路交通" || type === "侵权责任") {
    list.push({ level: "high", text: "对方只有交强险没商业险 —— 超出 20 万部分很难执行，要尽快保全" });
    list.push({ level: "mid", text: "伤残鉴定：骨折打钢板一般能评 10 级伤残，尽早做司法鉴定" });
    list.push({ level: "low", text: "误工费按实际误工天数 * 日工资计算，误工时间需医院证明" });
  } else if (type === "消费者权益") {
    list.push({ level: "mid", text: "平台内部规则 vs 消保法：不要被商家只同意退货就打发了，坚持退一赔三" });
    list.push({ level: "mid", text: "欺诈的举证：商家是否明知是假货？这一点需要举证（如商家承认、平台介入记录）" });
  } else {
    list.push({ level: "mid", text: "证据链尚不完整 —— 建议先补充更多事实细节再重新分析" });
  }
  return list;
}

function calcWinProb(patternLabel: string, evidences: EvidenceItem[], facts: string): { value: number; reason: string } {
  let base = 55;
  let parts: string[] = [];

  if (evidences.length >= 2) { base += 12; parts.push("已有多份佐证证据 (+12)"); }
  else if (evidences.length >= 1) { base += 5; parts.push("有一份核心证据 (+5)"); }
  else { base -= 5; parts.push("暂未上传任何证据 (-5)"); }

  if (patternLabel === "劳动争议-违法解除") {
    base += 8;
    parts.push("解雇事由由单位举证，劳动者通常占利 (+8)");
    if (facts.includes("书面")) { base += 5; parts.push("有书面文件 (+5)"); }
    if (facts.includes("口头") && !facts.includes("书面")) { base -= 3; parts.push("口头解除举证困难 (-3)"); }
  } else if (patternLabel === "合同纠纷-买卖/定金") {
    base += 5;
    parts.push("定金罚则法律明确 (+5)");
  } else if (patternLabel === "交通事故-人身损害") {
    base += 10;
    parts.push("交警已判对方全责，责任清楚 (+10)");
  } else if (patternLabel === "消费者-欺诈/假货") {
    base += 8;
    parts.push("消保法第五十五条保护明确 (+8)");
  }

  const value = Math.max(15, Math.min(92, base));
  return { value, reason: parts.join("，") };
}

function genRecommendations(type: string, risks: Risk[]): string[] {
  const out: string[] = [];
  const highRisks = risks.filter((r) => r.level === "high");
  if (highRisks.length) out.push("立即处理风险点：" + highRisks.map((r) => r.text.split("——")[0]).join("；"));
  out.push("整理证据清单 → 写书面质证意见 → 去对应仲裁委/法院立案");

  if (type === "劳动争议") {
    out.push("先走劳动仲裁（必须前置），向当地劳动人事争议仲裁委员会提交申请");
    out.push("仲裁请求建议包含：违法解除赔偿金(2N) + 未提前通知代通知金(N+0？或者N+1？看具体情况)");
  } else if (type === "合同纠纷") {
    out.push("写《律师函》给对方，留痕 + 增加对方压力");
    out.push("如对方无财产，可申请诉前保全（冻结对方账户）");
  } else if (type === "道路交通" || type === "侵权责任") {
    out.push("3 个月后到司法鉴定机构做伤残等级鉴定（伤残决定赔偿金数额）");
    out.push("保存医院所有发票、病历、CT 片 —— 原件拍照留档，原件自己保管");
  } else if (type === "消费者权益") {
    out.push("向平台投诉（内部机制）+ 向 12315 市场监管投诉（行政机制）+ 向法院起诉（司法机制）三路并行");
  }
  return out;
}

export async function analyzeCase(caseObj: Case, evidences: EvidenceItem[]): Promise<AnalysisResult> {
  await sleep(450 + Math.random() * 350);
  const facts = caseObj.facts || "";
  const detected = detectKeywords(facts);
  const type = detected.type !== "其他" ? detected.type : caseObj.type;

  const laws = pickLawsForType(type, facts);
  const risks = pickRisks(type, facts);
  const { value, reason } = calcWinProb(detected.patternLabel, evidences, facts);
  const similarCases = getSimilarCases(type, 3);
  const recs = genRecommendations(type, risks);

  return {
    caseId: caseObj.id,
    winProbability: value,
    winProbabilityReason: `综合评估约 ${value}%。${reason}`,
    risks,
    applicableLaws: laws,
    similarCases,
    recommendations: recs,
    updatedAt: formatNow(),
  };
}

