function genCourtQuestions(type: string): string[] {
  if (type === "劳动争议") {
    return [
      "法官：你单位说王某绩效差，有绩效管理制度吗？有王某签字认可吗？",
      "法官：解除通知书给劳动者了吗？怎么送达的？",
      "法官：'业务调整'具体调整了什么？财务报表、董事会决议有吗？",
      "对方律师：你之前有没有违反过公司规章制度？",
      "对方律师：工资里的绩效部分不稳定，凭什么按 8500 算平均工资？",
    ];
  }
  if (type === "道路交通") {
    return [
      "法官：误工费按 6 个月算有医嘱吗？医嘱具体内容是什么？",
      "法官：你主张的 156000 元具体构成和金额每项列一下",
      "对方律师：右胫腓骨骨折一般建议休 3 个月，你主张 6 个月是否有过度休养嫌疑？",
    ];
  }
  if (type === "消费者权益") {
    return [
      "法官：手机确实是你收到的那台吗？有没有调包的可能？",
      "法官：你购买时有没有看到下方小字的免责条款？",
      "对方律师：我们销售的是'展示机',详情页有小字注明。",
    ];
  }
  return ["法官：请原告补充 XXX 证据。", "对方律师：我方认为 XXX。"];
}

function genMyQuestions(type: string): string[] {
  if (type === "劳动争议") {
    return [
      "问对方单位：绩效差的证据是什么？有没有考核标准经我同意？",
      "问对方单位：解除通知是什么时候发的？我收到了吗？",
      "问己方证人：你是否也被无故辞退了？",
      "问法官：用人单位解除决定的举证责任在对方，对方没证据，应当支持我方主张。",
    ];
  }
  if (type === "道路交通") {
    return [
      "问对方：你明知只有交强险没有商业险，为什么不提前通知我？",
      "问法官：伤残鉴定结论 XXX，赔偿系数 10%，伤残赔偿金计算方式是 XXX，请支持。",
    ];
  }
  if (type === "消费者权益") {
    return [
      "问对方：你在详情页写了 '全新正品国行'，而实际是翻新机，这是不是欺诈？",
      "问平台：商家入驻时平台是否审核了资质？平台是否有连带责任？",
    ];
  }
  return ["请对方出示 XXX 证据。"];
}

function genWitnesses(type: string): { name: string; relation: string; willSay: string }[] {
  if (type === "劳动争议") {
    return [
      { name: "赵 XX", relation: "同一部门被一起辞退的同事", willSay: "我也在同一天被口头通知走人，没有补偿。" },
      { name: "银行卡", relation: "书证（银行盖章流水）", willSay: "2021 至今连续 3 年 2 个月工资入账，平均 8500/月。" },
    ];
  }
  if (type === "道路交通") {
    return [
      { name: "李 XX", relation: "事发时一同等红灯的路人", willSay: "我亲眼看到他从右转弯道没打灯直接撞上来。" },
    ];
  }
  if (type === "消费者权益") {
    return [
      { name: "序列号查询结果", relation: "书证", willSay: "官网显示序列号不存在或已激活。" },
      { name: "手机内照片", relation: "物证", willSay: "存在与我无关的人物照片。" },
    ];
  }
  return [];
}

export async function draftDefense(caseObj: Case, analysis: AnalysisResult): Promise<DefenseMaterial> {
  await sleep(380 + Math.random() * 320);
  const facts = caseObj.facts || "";
  const detected = detectKeywords(facts);
  const type = detected.type !== "其他" ? detected.type : caseObj.type;

  return {
    caseId: caseObj.id,
    strategy: genDefenseStrategy(type, facts),
    defenseText: genDefenseText(type, facts),
    courtQuestions: genCourtQuestions(type),
    myQuestions: genMyQuestions(type),
    witnesses: genWitnesses(type),
    updatedAt: formatNow(),
  };
}

