import { useState } from "react";
import { ArrowLeft, FileText, Gavel, Scale, Search, BookOpen } from "lucide-react";
import TabPanel from "../components/TabPanel";
import OverviewTab from "./tabs/OverviewTab";
import EvidenceTab from "./tabs/EvidenceTab";
import AnalysisTab from "./tabs/AnalysisTab";
import DefenseTab from "./tabs/DefenseTab";
import CitationTab from "./tabs/CitationTab";
import { useCaseStore } from "../store/caseStore";

interface Props {
  caseId: string;
  onBack: () => void;
}

export default function CaseDetailPage({ caseId, onBack }: Props) {
  const [tab, setTab] = useState("overview");
  const c = useCaseStore((s) => s.getCase(caseId));

  const tabs = [
    { key: "overview", label: "概览", icon: <FileText className="w-3.5 h-3.5" /> },
    { key: "evidence", label: "证据", icon: <BookOpen className="w-3.5 h-3.5" /> },
    { key: "analysis", label: "AI 分析", icon: <Scale className="w-3.5 h-3.5" /> },
    { key: "defense", label: "辩护", icon: <Gavel className="w-3.5 h-3.5" /> },
    { key: "laws", label: "法条", icon: <Search className="w-3.5 h-3.5" /> },
  ];

  return (
    <div className="h-full flex flex-col" style={{ background: "#0a0f24" }}>
      <div className="px-5 py-3 shrink-0 flex items-center gap-3" style={{ background: "linear-gradient(180deg, #0a1430 0%, #0a0f24 100%)", borderBottom: "1px solid rgba(99,102,241,0.15)" }}>
        <button onClick={onBack} className="w-9 h-9 rounded-xl flex items-center justify-center transition-colors text-slate-300 hover:bg-white/5 hover:text-white" title="返回案件列表">
          <ArrowLeft className="w-4 h-4" />
        </button>
        <div className="min-w-0">
          <div className="text-[15px] font-bold text-white truncate">{c?.title || "案件"}</div>
          <div className="text-[10px] text-slate-400 truncate">{c?.type}{c?.parties ? " · " + c.parties : ""}</div>
        </div>
      </div>
      <div className="flex-1 overflow-hidden">
        <TabPanel
          tabs={tabs.map((t) => ({
            key: t.key,
            label: t.label,
            icon: t.icon,
            content: (
              <div className="h-full overflow-y-auto" style={{ background: "#0a0f24" }}>
                {t.key === "overview" && <OverviewTab caseId={caseId} onSelectTab={setTab} />}
                {t.key === "evidence" && <EvidenceTab caseId={caseId} />}
                {t.key === "analysis" && <AnalysisTab caseId={caseId} onSelectTab={setTab} />}
                {t.key === "defense" && <DefenseTab caseId={caseId} />}
                {t.key === "laws" && <CitationTab caseId={caseId} />}
              </div>
            ),
          }))}
          activeKey={tab}
          onChange={setTab}
        />
      </div>
    </div>
  );
}
