import { Send, Paperclip, Mic, FileText, Video, ChevronDown, Zap } from "lucide-react";
import { useState, useRef, useEffect, useMemo } from "react";
import { useCaseStore } from "../store/caseStore";
import { useAppStore } from "../store/appStore";
import { chatReply } from "../lib/aiSimulator";
import { mdToHtml } from "../lib/md";
import { useTypewriter } from "../hooks/useTypewriter";

interface Props {
  caseId?: string;
  onChooseCase?: () => void;
}

export default function ChatPage({ caseId: initialCaseId, onChooseCase }: Props) {
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const { getCasesByUser, getChatMessages, addChatMessage, updateChatMessage, getCase } = useCaseStore();
  const userId = currentUser?.id || "user-001";
  const myCases = useMemo(() => getCasesByUser(userId).filter((c) => c.id.startsWith("CASE-")), [getCasesByUser, userId]);

  const [caseId, setCaseId] = useState<string | undefined>(initialCaseId || myCases[0]?.id || undefined);
  const [input, setInput] = useState("");
  const scrollRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const [reply, setReply] = useState("");
  const [typing, setTyping] = useState(false);
  const [pendingId, setPendingId] = useState<string | null>(null);
  const { display: displayReply, done: typeDone, skip } = useTypewriter(reply, typing && !!reply);

  useEffect(() => { setCaseId(initialCaseId || myCases[0]?.id || undefined); }, [initialCaseId, myCases]);

  const messages = useMemo(() => getChatMessages(caseId), [getChatMessages, caseId]);
  const activeCase = useMemo(() => (caseId ? getCase(caseId) : undefined), [getCase, caseId]);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, displayReply, typing]);

  useEffect(() => {
    if (typing && typeDone && reply) {
      const id = pendingId;
      if (id) updateChatMessage(id, { isTyping: false, content: reply });
      setTyping(false);
      setReply("");
      setPendingId(null);
    }
  }, [typeDone, typing]);

  const sendMessage = async () => {
    if (!input.trim() || typing) return;
    const now = new Date();
    const hm = `${now.getHours().toString().padStart(2, "0")}:${now.getMinutes().toString().padStart(2, "0")}`;
    const userMsg = addChatMessage({ role: "user", content: input, time: hm, caseId });
    const userText = input;
    setInput("");

    const pending = addChatMessage({ role: "assistant", content: "", time: hm, caseId, isTyping: true });
    setPendingId(pending.id);
    setTyping(true);

    const history = messages.filter((m) => !m.isTyping).slice(-8);
    try {
      const aiText = await chatReply(history, userText);
      setReply(aiText);
    } catch (e: any) {
      setReply("抱歉，刚才出了一点小问题，请再发一次试试。");
    }
  };

  return (
    <div className="flex flex-col h-full" style={{ background: "linear-gradient(180deg, #080c20 0%, #0a1230 100%)" }}>
      {(onChooseCase || myCases.length > 0) && (
        <div className="px-6 py-3 shrink-0 flex items-center gap-3 flex-wrap" style={{ background: "rgba(8,12,32,0.6)", borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
          <span className="text-xs font-bold text-white/60">当前案件：</span>
          <div className="relative">
            <select
              value={caseId || ""}
              onChange={(e) => setCaseId(e.target.value || undefined)}
              className="appearance-none pr-8 pl-3 py-2 rounded-xl text-sm font-medium text-white cursor-pointer"
              style={{
                background: "rgba(255,255,255,0.05)",
                border: "1px solid rgba(255,255,255,0.12)",
                fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
              }}
            >
              {myCases.length === 0 && <option value="" className="bg-slate-900">(暂无案件, AI 仅基于当前对话)</option>}
              {myCases.map((c) => (
                <option key={c.id} value={c.id} className="bg-slate-900">
                  {c.title} · {c.status === "defending" ? "辩护中" : c.status === "ready" ? "已分析" : c.status === "analyzing" ? "分析中" : "草稿"}
                </option>
              ))}
            </select>
            <ChevronDown className="absolute right-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-white/50 pointer-events-none" />
          </div>
          {activeCase?.facts && (
            <span className="text-xs text-white/45 line-clamp-1 max-w-[360px]">📋 {activeCase.facts.slice(0, 60)}…</span>
          )}
          {onChooseCase && (
            <button onClick={onChooseCase} className="ml-auto text-xs font-bold text-white px-3 py-1.5 rounded-lg transition-colors" style={{ background: "rgba(212,175,55,0.18)", border: "1px solid rgba(212,175,55,0.35)", color: "#fde68a" }}>
              查看案件详情
            </button>
          )}
        </div>
      )}

      <div className="flex-1 overflow-y-auto px-6 py-5 space-y-3" ref={scrollRef}>
        {messages.length === 0 && !typing && (
          <div className="flex flex-col items-center justify-center h-full text-center py-16">
            <div className="w-20 h-20 rounded-2xl flex items-center justify-center mb-4 shadow-lg" style={{ background: "linear-gradient(135deg, #0c1528 0%, #243e73 50%, #d4af37 140%)", boxShadow: "0 0 40px rgba(61,100,176,0.4), inset 0 0 20px rgba(212,175,55,0.2)", border: "1px solid rgba(212,175,55,0.3)" }}>
              <span className="text-3xl" style={{ background: "linear-gradient(135deg, #f5e4a6, #d4af37)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>⚖️</span>
            </div>
            <h3 className="font-bold text-white text-lg mb-2" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
              您好，我是您的 AI 律师
            </h3>
            <p className="text-sm text-white/50 max-w-[520px] leading-relaxed">
              描述您遇到的案件（什么时候、什么事、对方是谁、手上有哪些证据），我会帮您：分析法律依据 → 匹配法条 → 列出风险点 → 给出下一步清单。
            </p>
            <div className="mt-4 flex gap-2 flex-wrap justify-center">
              {["辞退赔偿", "交通事故", "合同纠纷", "假货欺诈"].map((t) => (
                <button
                  key={t}
                  onClick={() => setInput(t + "相关的法律问题怎么处理？")}
                  className="px-3 py-1.5 rounded-full text-xs text-white/95 border border-white/15 hover:border-gold-500/40 transition-all"
                  style={{ background: "rgba(255,255,255,0.06)" }}
                >
                  {t} →
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((msg) => {
          if (msg.isTyping && !msg.content) return null;
          const isAI = msg.role === "assistant";
          const showContent = msg.isTyping ? displayReply : msg.content;
          if (msg.isTyping && !reply && !displayReply) {
            return (
              <div key={msg.id} className="flex gap-3">
                <div className="w-9 h-9 rounded-xl shrink-0 flex items-center justify-center text-[12px] font-bold" style={{ background: "linear-gradient(135deg, #243e73, #3d64b0)", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
                  <Zap className="w-4 h-4 text-gold-300" />
                </div>
                <div className="px-4 py-3 rounded-2xl rounded-tl-md" style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)" }}>
                  <div className="flex gap-1.5 items-center">
                    <span className="w-2 h-2 rounded-full animate-bounce" style={{ background: "#d4af37", animationDelay: "0ms" }} />
                    <span className="w-2 h-2 rounded-full animate-bounce" style={{ background: "#3d64b0", animationDelay: "150ms" }} />
                    <span className="w-2 h-2 rounded-full animate-bounce" style={{ background: "#d4af37", animationDelay: "300ms" }} />
                    <span className="ml-2 text-xs text-white/55">AI 正在分析案情…</span>
                  </div>
                </div>
              </div>
            );
          }
          return (
            <div key={msg.id} className={`flex gap-3 ${isAI ? "" : "flex-row-reverse"}`}>
              <div className={`w-9 h-9 rounded-xl shrink-0 flex items-center justify-center text-[12px] font-bold shadow-md ${isAI ? "" : "text-primary-950"}`} style={{
                background: isAI
                  ? "linear-gradient(135deg, #243e73, #3d64b0)"
                  : "linear-gradient(135deg, #d4af37, #f5e4a6)",
                fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
              }}>
                {isAI ? "AI" : "我"}
              </div>
              <div className={`max-w-[720px] ${isAI ? "" : "items-end"}`}>
                {isAI ? (
                  <div
                    className="px-4 py-3 rounded-2xl text-[14px] leading-relaxed rounded-tl-md max-w-none"
                    style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)", color: "#e6e9f2" }}
                    dangerouslySetInnerHTML={{ __html: mdToHtml(showContent) }}
                  />
                ) : (
                  <div className="px-4 py-3 rounded-2xl text-[14px] leading-relaxed whitespace-pre-wrap rounded-tr-md shadow-md" style={{
                    background: "linear-gradient(135deg, #2d4e8f 0%, #5f82c8 60%, #d4af37 140%)",
                    fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
                  }}>
                    {showContent}
                  </div>
                )}
                <div className={`mt-1 text-[10px] text-white/35 ${isAI ? "" : "text-right"}`}>
                  {msg.time}
                  {msg.isTyping && !typeDone && (
                    <button onClick={skip} className="ml-2 text-gold-300 hover:underline">跳过</button>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="px-6 pb-4 pt-2 shrink-0" style={{ background: "rgba(8,12,32,0.6)", borderTop: "1px solid rgba(255,255,255,0.08)" }}>
        <div className="flex items-end gap-2 rounded-2xl border focus-within:ring-2 focus-within:border-primary-400 focus-within:ring-primary-500/30 transition-all" style={{
          background: "rgba(255,255,255,0.05)",
          borderColor: "rgba(255,255,255,0.12)",
        }}>
          <div className="flex items-center gap-1 pl-3 py-2.5">
            <button className="p-1.5 rounded-lg text-white/50 hover:text-white hover:bg-white/10 transition-colors" title="上传证据">
              <Paperclip className="w-4 h-4" />
            </button>
            <button className="p-1.5 rounded-lg text-white/50 hover:text-white hover:bg-white/10 transition-colors" title="录音">
              <Mic className="w-4 h-4" />
            </button>
          </div>
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } }}
            rows={1}
            placeholder={caseId ? "描述案情、提出问题...（按当前案件上下文分析）" : "描述案情、提出问题...（未关联案件，仅基于对话历史）"}
            className="flex-1 bg-transparent border-0 outline-none py-2.5 text-[14px] text-white placeholder:text-white/40 resize-none max-h-40 min-h-[42px]"
            style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}
            disabled={typing}
          />
          <div className="pr-3 py-2.5">
            <button
              onClick={sendMessage}
              disabled={!input.trim() || typing}
              className="p-2 rounded-xl disabled:opacity-40 transition-all shadow-md"
              style={{
                background: "linear-gradient(135deg, #3d64b0 0%, #d4af37 120%)",
                boxShadow: "0 3px 14px rgba(61,100,176,0.5)",
              }}
            >
              <Send className="w-4 h-4 text-white" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
