import { create } from "zustand";
import { formatNow, nextCaseId, nextEvidenceId, nextChatMsgId } from "../lib/templates";

export type CaseStatus = "draft" | "analyzing" | "ready" | "defending" | "closed";

export interface Case {
  id: string;
  title: string;
  type: string;
  parties: string;
  facts: string;
  status: CaseStatus;
  progress: number;
  userId: string;
  createdAt: string;
  updatedAt: string;
}

export interface EvidenceItem {
  id: string;
  caseId: string;
  name: string;
  type: "document" | "image" | "audio" | "video";
  uploadedAt: string;
  aiSummary: string;
  aiIssues: string[];
}

export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
  time: string;
  caseId?: string;
  isTyping?: boolean;
}

export interface Risk {
  level: "high" | "mid" | "low";
  text: string;
}

export interface ApplicableLaw {
  lawId: string;
  law: string;
  article: string;
  summary: string;
  reason: string;
}

export interface AnalysisResult {
  caseId: string;
  winProbability: number;
  winProbabilityReason: string;
  risks: Risk[];
  applicableLaws: ApplicableLaw[];
  similarCases: { court: string; year: number; title: string; result: string; amount?: string }[];
  recommendations: string[];
  updatedAt: string;
}

export interface Witness {
  name: string;
  relation: string;
  willSay: string;
}

export interface DefenseMaterial {
  caseId: string;
  strategy: string;
  defenseText: string;
  courtQuestions: string[];
  myQuestions: string[];
  witnesses: Witness[];
  updatedAt: string;
}

export type DocCategory =
  | "id_front"
  | "id_back"
  | "business_license"
  | "property"
  | "death_cert"
  | "transfer"
  | "will"
  | "marriage"
  | "divorce"
  | "contract"
  | "bank_statement"
  | "medical"
  | "other";

export interface UserDoc {
  id: string;
  userId: string;
  category: DocCategory;
  name: string;
  fileName: string;
  type: "document" | "image" | "audio" | "video";
  verified: boolean;
  verifiedAt?: string;
  info?: { label: string; value: string }[];
  summary: string;
  uploadedAt: string;
}

export interface IdentityVerify {
  userId: string;
  realName?: string;
  idNumber?: string;
  verified: boolean;
  verifiedAt?: string;
}

