interface CaseState {
  cases: Case[];
  evidences: EvidenceItem[];
  chats: ChatMessage[];
  analyses: Record<string, AnalysisResult>;
  defenses: Record<string, DefenseMaterial>;
  userDocs: UserDoc[];
  identities: Record<string, IdentityVerify>;

  createCase: (data: { title: string; type: string; parties: string; facts: string; userId: string }) => Case;
  deleteCase: (caseId: string) => void;
  updateCase: (caseId: string, patch: Partial<Case>) => void;
  getCasesByUser: (userId: string) => Case[];
  getCase: (caseId: string) => Case | undefined;

  addEvidence: (caseId: string, ev: Omit<EvidenceItem, "id" | "caseId" | "uploadedAt">) => EvidenceItem;
  updateEvidence: (evidenceId: string, patch: Partial<Omit<EvidenceItem, "id" | "caseId" | "uploadedAt">>) => void;
  removeEvidence: (evidenceId: string) => void;
  getEvidences: (caseId: string) => EvidenceItem[];

  addChatMessage: (msg: Omit<ChatMessage, "id" | "time"> & { time?: string }) => ChatMessage;
  updateChatMessage: (msgId: string, patch: Partial<ChatMessage>) => void;
  getChatMessages: (caseId?: string) => ChatMessage[];
  clearChat: (caseId: string) => void;

  setAnalysis: (caseId: string, a: AnalysisResult) => void;
  getAnalysis: (caseId: string) => AnalysisResult | undefined;

  setDefense: (caseId: string, d: DefenseMaterial) => void;
  getDefense: (caseId: string) => DefenseMaterial | undefined;
  updateDefenseText: (caseId: string, text: string) => void;

  addUserDoc: (doc: Omit<UserDoc, "id" | "uploadedAt">) => UserDoc;
  removeUserDoc: (docId: string) => void;
  getUserDocs: (userId: string) => UserDoc[];
  getUserDocById: (docId: string) => UserDoc | undefined;
  getIdentity: (userId: string) => IdentityVerify | undefined;
  setIdentity: (userId: string, patch: Partial<IdentityVerify>) => void;
  verifyDoc: (docId: string, info?: { label: string; value: string }[]) => void;
  linkDocToCase: (docId: string, caseId: string) => EvidenceItem;

  resetAll: () => void;
}

