import { Gavel, RotateCcw, Edit3, CheckCircle, MessageSquare, UserRound, Save, Mic, MicOff, Volume2, VolumeX, FileUp, Plus, Trash2, FileText, UserCheck, FileQuestion, ArrowRight, Sparkles, Send, CirclePause, CircleDot } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useCaseStore, DOC_CATEGORY_META, DocCategory } from "../../store/caseStore";
import { useAppStore } from "../../store/appStore";
import { analyzeCase, draftDefense } from "../../lib/aiSimulator";

interface Props { caseId: string }

const MOTION_TEMPLATES: { key: string; label: string; icon: string; body: string }[] = [
  { key: "witness", label: "请求证人出庭", icon: "👤",
    body: "审判长：我方申请传唤证人 [证人姓名] 出庭作证，证明 [将要证明的事实]。依据民事诉讼法第 75 条，请法庭准许。" },
  { key: "new_evidence", label: "当庭提交新证据", icon: "📄",
    body: "审判长：我方当庭提交新证据一份（[证据名称]），用以证明 [证明目的]。该证据系 [取得时间或来源]，请法庭予以接收并组织质证。" },
  { key: "expert", label: "申请专家辅助人", icon: "🔬",
    body: "审判长：本案涉及 [专门性问题，如伤残等级或笔迹真伪或电子数据]，我方依据民事诉讼法第 82 条申请专家辅助人 [姓名/资质] 出庭，就该专门性问题发表意见。" },
  { key: "transfer", label: "管辖权异议", icon: "📍",
    body: "审判长：我方认为本院对本案不具有管辖权，理由如下：[具体理由]。恳请法庭依法审查。" },
  { key: "adjourn", label: "申请延期开庭", icon: "📅",
    body: "审判长：因 [具体理由：如新证据待核实/关键证人无法出庭/突发疾病等]，我方依据民事诉讼法第 146 条申请延期开庭 [X] 日，恳请法庭准许。" },
  { key: "interpret", label: "申请法庭调取证据", icon: "🔎",
    body: "审判长：我方申请法庭调取存于 [单位名称，如银行/公安/档案] 的 [证据名称/文号]，理由：[该证据由对方掌握或我方无法自行取得]。依据民事诉讼法第 67 条。" },
];

type Scene = "strategy" | "court" | "requests";

export default function DefenseTab({ caseId }: Props) {
  const {
    getCase, getAnalysis, getDefense, setDefense, updateDefenseText, getEvidences,
    getUserDocs, linkDocToCase, addEvidence,
  } = useCaseStore();
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const c = getCase(caseId);
  const analysis = getAnalysis(caseId);
  const defense = getDefense(caseId);
  const evidences = getEvidences(caseId);
  const library = currentUser ? getUserDocs(currentUser.id).filter((d) => d.verified) : [];

  const [loading, setLoading] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [draft, setDraft] = useState(defense?.defenseText || "");
  const [scene, setScene] = useState<Scene>("strategy");

  const [ttsOn, setTtsOn] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [recording, setRecording] = useState(false);
  const [voiceTranscript, setVoiceTranscript] = useState("");
  const recognitionRef = useRef<any>(null);

  const [docOpen, setDocOpen] = useState(false);
  const [motionOpen, setMotionOpen] = useState<string | null>(null);
  const [motionText, setMotionText] = useState("");
  const [filedMotions, setFiledMotions] = useState<{ key: string; label: string; text: string; at: string }[]>([]);

  const card = {
    background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)",
    border: "1px solid rgba(99,102,241,0.15)",
    borderRadius: "16px",
  };

  const stripMd = (s: string) => s.replace(/[#*`>\-]/g, "").replace(/\n{2,}/g, "\n").trim();

  useEffect(() => {
    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SR) {
      const rec = new SR();
      rec.lang = "zh-CN";
      rec.continuous = true;
      rec.interimResults = true;
      rec.onresult = (e: any) => {
        let interim = "";
        let finalTxt = "";
        for (let i = e.resultIndex; i < e.results.length; i++) {
          if (e.results[i].isFinal) finalTxt += e.results[i][0].transcript;
          else interim += e.results[i][0].transcript;
        }
        const all = (finalTxt + interim).trim();
        if (all) setVoiceTranscript(all);
      };
      rec.onerror = () => setRecording(false);
      rec.onend = () => { if (recording) { try { rec.start(); } catch {} } };
      recognitionRef.current = rec;
    }
  }, []);

  const toggleVoice = () => {
    if (!recognitionRef.current) { alert("当前浏览器不支持语音识别，请用 Chrome/Edge。"); return; }
    if (recording) { recognitionRef.current.stop(); setRecording(false); }
    else { setRecording(true); try { recognitionRef.current.start(); } catch {} }
  };

  const toggleTTS = () => {
    if (speaking) { window.speechSynthesis.cancel(); setSpeaking(false); setTtsOn(false); return; }
    if (!defense) return;
    const text = scene === "strategy" ? stripMd(defense.strategy) : stripMd(defense.defenseText);
    const u = new SpeechSynthesisUtterance(text);
    u.lang = "zh-CN";
    u.rate = 1.0;
    u.pitch = 1;
    u.onstart = () => { setSpeaking(true); setTtsOn(true); };
    u.onend = () => { setSpeaking(false); setTtsOn(false); };
    window.speechSynthesis.speak(u);
  };

  const run = async () => {
    if (!c) return;
    setLoading(true);
    try {
      const a = analysis || (await analyzeCase(c, evidences));
      const d = await draftDefense(c, a);
      setDefense(caseId, d);
      setDraft(d.defenseText);
    } finally {
      setLoading(false);
    }
  };

  const saveEdit = () => { updateDefenseText(caseId, draft); setEditMode(false); };
  const pickToCase = (docId: string) => { linkDocToCase(docId, caseId); setDocOpen(false); };
  const fileMotion = () => {
    if (!motionOpen || !motionText.trim()) return;
    const tpl = MOTION_TEMPLATES.find((m) => m.key === motionOpen)!;
    setFiledMotions((arr) => [
      { key: motionOpen, label: tpl.label, text: motionText, at: new Date().toLocaleTimeString("zh-CN", { hour12: false }) },
      ...arr,
    ]);
    setMotionOpen(null);
    setMotionText("");
  };

  if (!c) return <div className="p-8 text-center text-slate-400">案件不存在</div>;

  const renderStrategy = () => (
    <>
      <div className="rounded-2xl border border-amber-500/25 p-5"
        style={{ background: "linear-gradient(135deg, rgba(217,119,6,0.15), rgba(217,119,6,0.06))" }}>
        <div className="flex items-center gap-2 mb-3">
          <Gavel className="w-4 h-4 text-amber-300" />
          <div className="text-xs font-semibold text-amber-300">辩护策略</div>
          <button onClick={toggleTTS}
            className="ml-auto px-2 py-1 rounded-md text-[10px] font-semibold flex items-center gap-1"
            style={{ background: ttsOn ? "rgba(16,185,129,0.2)" : "rgba(99,102,241,0.15)", color: ttsOn ? "#6ee7b7" : "#a5b4fc" }}>
            {speaking ? <CirclePause className="w-3 h-3" /> : <Volume2 className="w-3 h-3" />}
            {speaking ? "停止朗读" : "朗读策略"}
          </button>
        </div>
        <div className="prose prose-sm max-w-none text-[13px] text-slate-100 leading-relaxed whitespace-pre-wrap">
          {defense.strategy}
        </div>
      </div>

      <div style={card} className="p-5">
        <div className="flex items-center justify-between flex-wrap gap-3 mb-3">
          <div className="flex items-center gap-2">
            <FileText className="w-4 h-4 text-indigo-300" />
            <div>
              <div className="text-xs font-semibold text-slate-300">辩护词正文（可编辑）</div>
              <div className="text-[10px] text-slate-500">建议以此为基础，你可以手动修改后再导出提交</div>
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={toggleTTS}
              className="inline-flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-semibold"
              style={{ background: ttsOn ? "rgba(16,185,129,0.15)" : "rgba(99,102,241,0.12)", color: ttsOn ? "#6ee7b7" : "#a5b4fc" }}>
              {speaking ? <CirclePause className="w-3 h-3" /> : <Volume2 className="w-3 h-3" />}
              {speaking ? "停止" : "朗读"}
            </button>
            {editMode ? (
              <>
                <button onClick={saveEdit} className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600">
                  <Save className="w-3 h-3" /> 保存
                </button>
                <button onClick={() => { setDraft(defense.defenseText); setEditMode(false); }} className="px-3 py-1.5 rounded-lg text-xs font-medium text-slate-300 bg-white/5">放弃</button>
              </>
            ) : (
              <button onClick={() => setEditMode(true)} className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium text-slate-200 bg-white/5 hover:bg-white/10">
                <Edit3 className="w-3 h-3" /> 编辑
              </button>
            )}
          </div>
        </div>
        {editMode ? (
          <textarea value={draft} onChange={(e) => setDraft(e.target.value)} rows={22}
            className="w-full px-3 py-3 rounded-xl text-[13px] leading-relaxed focus:outline-none focus:ring-2 focus:ring-indigo-500/30 resize-y"
            style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.2)", color: "#e2e8f0", fontFamily: "\"Microsoft YaHei\", sans-serif" }} />
        ) : (
          <div className="text-[13px] text-slate-100 leading-relaxed whitespace-pre-wrap max-h-[520px] overflow-y-auto">
            {defense.defenseText}
          </div>
        )}
      </div>

      <div className="grid md:grid-cols-2 gap-4">
        <div style={card} className="p-5">
          <div className="flex items-center gap-2 mb-3">
            <MessageSquare className="w-4 h-4 text-rose-300" />
            <div className="text-xs font-semibold text-rose-300">法庭上对方律师/法官可能问你</div>
          </div>
          <ul className="space-y-2">
            {defense.courtQuestions.map((q, i) => (
              <li key={i} className="flex items-start gap-2 text-[12px] text-slate-100 leading-relaxed">
                <span className="w-5 h-5 rounded-full text-[10px] flex items-center justify-center shrink-0 mt-0.5 font-bold"
                  style={{ background: "rgba(244,63,94,0.2)", color: "#fda4af" }}>{i + 1}</span>
                <span>{q}</span>
              </li>
            ))}
          </ul>
          <p className="mt-3 text-[11px] text-slate-500">开庭前把答案练熟</p>
        </div>
        <div style={card} className="p-5">
          <div className="flex items-center gap-2 mb-3">
            <CheckCircle className="w-4 h-4 text-emerald-300" />
            <div className="text-xs font-semibold text-emerald-300">我可以问对方/当庭陈述</div>
          </div>
          <ul className="space-y-2">
            {defense.myQuestions.map((q, i) => (
              <li key={i} className="flex items-start gap-2 text-[12px] text-slate-100 leading-relaxed">
                <span className="w-5 h-5 rounded-full text-[10px] flex items-center justify-center shrink-0 mt-0.5 font-bold"
                  style={{ background: "rgba(16,185,129,0.2)", color: "#6ee7b7" }}>{i + 1}</span>
                <span>{q}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>

      <div style={card} className="p-5">
        <div className="flex items-center gap-2 mb-3">
          <UserRound className="w-4 h-4 text-indigo-300" />
          <div className="text-xs font-semibold text-indigo-300">证人清单</div>
        </div>
        {defense.witnesses.length === 0 ? (
          <p className="text-xs text-slate-500">暂无自动生成的证人清单</p>
        ) : (
          <div className="grid gap-2 md:grid-cols-2">
            {defense.witnesses.map((w, i) => (
              <div key={i} className="rounded-xl p-3"
                style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.12)" }}>
                <div className="text-[13px] font-bold text-white">{w.name}</div>
                <div className="text-[11px] text-slate-400 mb-1">{w.relation}</div>
                <div className="text-[12px] text-slate-200 leading-relaxed">
                  <span className="text-slate-500 text-[10px]">将作证：</span>{w.willSay}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  );

  const renderCourt = () => (
    <div className="rounded-2xl p-5"
      style={{ background: "linear-gradient(135deg,#1d2a5a,#0a1430)", border: "1px solid rgba(99,102,241,0.25)" }}>
      <div className="flex items-center justify-between flex-wrap gap-3 mb-4">
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-xl flex items-center justify-center"
            style={{ background: "linear-gradient(135deg,#f59e0b,#d4af37)" }}>
            <Gavel className="w-5 h-5 text-white" />
          </div>
          <div>
            <div className="text-white font-bold text-sm">🎙 法庭模拟 · 语音辩护</div>
            <div className="text-[11px] text-amber-200/80">像真的在法庭一样说话，系统会识别你说的话并整理成文字</div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={toggleVoice}
            className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold shadow-md transition-all ${recording ? "text-white" : "text-slate-100"}`}
            style={recording ? { background: "linear-gradient(135deg,#ef4444,#dc2626)", animation: "pulse 1.5s infinite" } : { background: "linear-gradient(135deg,#6366f1,#8b5cf6)" }}>
            {recording ? <Mic className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
            {recording ? "停止录音" : "开始语音辩护"}
          </button>
          <button onClick={toggleTTS}
            className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold"
            style={{ background: ttsOn ? "rgba(16,185,129,0.2)" : "rgba(99,102,241,0.15)", color: ttsOn ? "#6ee7b7" : "#a5b4fc" }}>
            {speaking ? <VolumeX className="w-3.5 h-3.5" /> : <Volume2 className="w-3.5 h-3.5" />}
            {speaking ? "停止" : "朗读辩护词"}
          </button>
        </div>
      </div>

      <div className="grid md:grid-cols-3 gap-2 mb-4">
        {[
          { t: "开庭陈词（30秒）", text: stripMd(defense.defenseText).slice(0, 120) + "..." },
          { t: "反驳对方观点", text: defense.myQuestions[0] || "请对方出示XXX证据" },
          { t: "补充新证据说明", text: "审判长，我方当庭提交新证据：[证据名称]，用以证明..." },
        ].map((q, i) => (
          <button key={i} onClick={() => setVoiceTranscript(q.text)}
            className="text-left p-3 rounded-xl transition-all hover:-translate-y-0.5"
            style={{ background: "rgba(99,102,241,0.08)", border: "1px solid rgba(99,102,241,0.15)" }}>
            <div className="text-[10px] text-slate-400 font-semibold mb-1">建议话术 {i + 1}</div>
            <div className="text-[12px] text-slate-100 leading-relaxed">{q.t}</div>
          </button>
        ))}
      </div>

      <div style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.15)" }} className="rounded-xl p-4">
        <div className="flex items-center justify-between mb-2">
          <span className="text-[11px] font-bold text-slate-300 uppercase tracking-widest">实时语音识别结果</span>
          <span className={`text-[10px] font-semibold ${recording ? "text-emerald-300" : "text-slate-500"}`}>
            {recording ? "录音中..." : "未录音，点上面按钮开始"}
          </span>
        </div>
        <textarea
          value={voiceTranscript}
          onChange={(e) => setVoiceTranscript(e.target.value)}
          placeholder="你说的话会实时转成文字，识别后可直接编辑或复制"
          rows={5}
          className="w-full px-3 py-2 rounded-lg text-[13px] leading-relaxed text-slate-100 resize-none focus:outline-none focus:ring-2 focus:ring-indigo-500/30"
          style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.12)", fontFamily: "\"Microsoft YaHei\", sans-serif" }}
        />
        <div className="flex items-center justify-between mt-2">
          <span className="text-[10px] text-slate-500">识别为中文普通话，可以复制作为法庭发言底稿</span>
          <button
            onClick={() => {
              if (!voiceTranscript.trim()) return;
              addEvidence(caseId, {
                name: `语音辩护理由_${new Date().toLocaleTimeString("zh-CN", { hour12: false }).replace(/:/g, "-")}.txt`,
                type: "document",
                aiSummary: "语音实时识别：" + voiceTranscript.slice(0, 120),
                aiIssues: ["语音识别内容，建议当庭再核对一次"],
              });
              alert("已保存到本案证据列表");
              setVoiceTranscript("");
            }}
            className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-white bg-gradient-to-r from-amber-500 to-amber-600 shadow-md">
            <Save className="w-3 h-3" />
            存为本案证据
          </button>
        </div>
      </div>
    </div>
  );

  const renderRequests = () => (
    <>
      <div style={card} className="p-5">
        <div className="flex items-center gap-2 mb-3">
          <FileQuestion className="w-4 h-4 text-fuchsia-300" />
          <div className="text-xs font-semibold text-fuchsia-300">向审判长提出（6 种常用申请模板）</div>
        </div>
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-2">
          {MOTION_TEMPLATES.map((m) => (
            <button key={m.key} onClick={() => { setMotionOpen(m.key); setMotionText(m.body.replace(/\[.*?\]/g, "在此处填写")); }}
              className="text-left p-3 rounded-xl transition-all hover:-translate-y-0.5"
              style={{ background: "rgba(139,92,246,0.08)", border: "1px solid rgba(139,92,246,0.2)" }}>
              <div className="flex items-center gap-2 mb-1">
                <span className="text-lg">{m.icon}</span>
                <span className="text-[12px] font-bold text-white">{m.label}</span>
              </div>
              <div className="text-[10px] text-slate-400 leading-relaxed line-clamp-2">{m.body.slice(0, 40)}...</div>
            </button>
          ))}
        </div>
      </div>

      {filedMotions.length > 0 && (
        <div style={card} className="p-5">
          <div className="flex items-center gap-2 mb-3">
            <CheckCircle className="w-4 h-4 text-emerald-300" />
            <div className="text-xs font-semibold text-emerald-300">已提出（当庭可以照着念）</div>
          </div>
          <div className="space-y-2">
            {filedMotions.map((f, i) => (
              <div key={i} className="rounded-xl p-3"
                style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.1)" }}>
                <div className="flex items-center justify-between mb-1">
                  <span className="text-[12px] font-bold text-amber-300">{f.label}</span>
                  <span className="text-[10px] text-slate-500">{f.at}</span>
                </div>
                <div className="text-[12px] text-slate-100 leading-relaxed whitespace-pre-wrap">{f.text}</div>
                <button onClick={() => { navigator.clipboard?.writeText(f.text); alert("已复制当庭朗读版"); }}
                  className="mt-2 text-[10px] text-indigo-300 hover:text-indigo-200">复制当庭朗读版</button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div style={card} className="p-5">
        <div className="flex items-center gap-2 mb-3">
          <UserCheck className="w-4 h-4 text-cyan-300" />
          <div className="text-xs font-semibold text-cyan-300">快速提示：法庭上什么时候提？</div>
        </div>
        <ul className="space-y-2 text-[12px] text-slate-200 leading-relaxed">
          <li>开庭前 - 申请法官回避 / 管辖权异议</li>
          <li>法庭调查中 - 提交新证据 / 调取证据 / 传唤证人</li>
          <li>法庭辩论中 - 申请专家辅助人 / 重新鉴定</li>
          <li>任何阶段 - 都可以口头：审判长，我申请XXX，理由如下...</li>
        </ul>
      </div>
    </>
  );

  return (
    <div className="p-6 space-y-5" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", sans-serif" }}>
      {loading && (
        <div className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm flex items-center justify-center">
          <div className="rounded-2xl shadow-2xl p-6 flex items-center gap-4"
            style={{ background: "linear-gradient(180deg,#0a1430,#070c1f)", border: "1px solid rgba(99,102,241,0.25)" }}>
            <div className="w-8 h-8 border-2 border-amber-400 border-t-transparent rounded-full animate-spin" />
            <div>
              <div className="text-sm font-semibold text-white">AI 正在起草辩护材料...</div>
              <div className="text-xs text-slate-400">策略 / 辩护词 / 法庭问答 一起生成</div>
            </div>
          </div>
        </div>
      )}

      {!defense && !loading && (
        <div style={card} className="p-10 flex flex-col items-center justify-center text-center">
          <div className="w-20 h-20 rounded-2xl flex items-center justify-center mb-4" style={{ background: "rgba(217,119,6,0.12)" }}>
            <Gavel className="w-8 h-8 text-amber-400" />
          </div>
          <p className="text-slate-300 mb-4">先生成辩护材料（建议先跑 AI 分析）</p>
          <button onClick={run}
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl font-semibold text-white bg-gradient-to-r from-amber-600 to-amber-500 hover:from-amber-500 hover:to-amber-400 shadow-md">
            <Gavel className="w-4 h-4" />
            {analysis ? "基于已有分析 生成辩护材料" : "先分析 + 再生成（一键两步）"}
          </button>
        </div>
      )}

      {defense && (
        <>
          <div style={card} className="p-3 flex items-center gap-2 flex-wrap">
            {(["strategy", "court", "requests"] as Scene[]).map((k) => (
              <button key={k} onClick={() => setScene(k)}
                className={`px-4 py-2 rounded-xl text-sm font-semibold transition-all ${scene === k ? "text-white shadow-md" : "text-slate-300 hover:bg-white/5"}`}
                style={scene === k ? { background: "linear-gradient(135deg,#6366f1,#8b5cf6)" } : {}}>
                {k === "strategy" ? "🎯 辩护策略" : k === "court" ? "🎙 法庭模拟" : "📜 向审判长提出"}
              </button>
            ))}
            <div className="ml-auto flex items-center gap-2 flex-wrap">
              <button onClick={() => setDocOpen(true)}
                className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold text-amber-300 hover:text-amber-200"
                style={{ background: "rgba(245,158,11,0.12)", border: "1px solid rgba(245,158,11,0.3)" }}>
                <FileUp className="w-3.5 h-3.5" />
                补充证据（{evidences.length} 件）
              </button>
              <button onClick={run}
                className="inline-flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium text-slate-200 bg-white/5 hover:bg-white/10">
                <RotateCcw className="w-3 h-3" /> 重新生成
              </button>
            </div>
          </div>

          {scene === "strategy" && renderStrategy()}
          {scene === "court" && renderCourt()}
          {scene === "requests" && renderRequests()}

          {docOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setDocOpen(false)}>
              <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
              <div className="relative rounded-2xl w-full max-w-4xl max-h-[86vh] flex flex-col"
                style={{ background: "linear-gradient(180deg, #0a1430 0%, #070c1f 100%)", border: "1px solid rgba(99,102,241,0.25)", boxShadow: "0 20px 60px rgba(0,0,0,0.7)" }}
                onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center justify-between px-5 py-3" style={{ borderBottom: "1px solid rgba(99,102,241,0.15)" }}>
                  <div className="flex items-center gap-2">
                    <Sparkles className="w-4 h-4 text-amber-300" />
                    <h3 className="font-bold text-white text-[15px]">补充证据：从材料库引用或新增</h3>
                  </div>
                  <button onClick={() => setDocOpen(false)} className="w-8 h-8 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 flex items-center justify-center">x</button>
                </div>
                <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4">
                  <div>
                    <div className="text-[11px] font-semibold text-slate-400 uppercase tracking-widest mb-2">1. 当庭临时新增的一类</div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                      {[
                        { label: "合同", icon: "📄", type: "document" as const, ai: "当庭提交的书面合同原件或复印件" },
                        { label: "录音", icon: "🎙", type: "audio" as const, ai: "当庭播放的录音" },
                        { label: "录像", icon: "📹", type: "video" as const, ai: "当庭播放的录像片段" },
                        { label: "图片", icon: "📷", type: "image" as const, ai: "物证/书证照片" },
                      ].map((q) => (
                        <button key={q.label}
                          onClick={() => { addEvidence(caseId, { name: `当庭${q.label}${evidences.length + 1}`, type: q.type, aiSummary: q.ai + "（当庭临时增加）" }); alert("已加入证据列表"); }}
                          className="flex flex-col items-center gap-1 p-3 rounded-xl transition-all hover:-translate-y-0.5"
                          style={{ background: "rgba(99,102,241,0.08)", border: "1px solid rgba(99,102,241,0.15)" }}>
                          <span className="text-xl">{q.icon}</span>
                          <span className="text-[11px] font-semibold text-white">{q.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                  <div>
                    <div className="text-[11px] font-semibold text-slate-400 uppercase tracking-widest mb-2">2. 从你的材料库挑一个（已实名认证，不用再传）</div>
                    {library.length === 0 ? (
                      <div className="p-5 text-center rounded-xl"
                        style={{ background: "rgba(245,158,11,0.06)", border: "1px solid rgba(245,158,11,0.2)" }}>
                        <p className="text-[12px] text-amber-200">你还没有已实名认证的材料。先去左侧"我的材料库"上传并实名。</p>
                      </div>
                    ) : (
                      <div className="grid md:grid-cols-2 gap-3">
                        {library.map((d) => {
                          const meta = DOC_CATEGORY_META[d.category as DocCategory];
                          return (
                            <div key={d.id} className="rounded-2xl p-4"
                              style={{ background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(16,185,129,0.35)" }}>
                              <div className="flex items-center gap-2.5">
                                <div className="w-10 h-10 rounded-xl flex items-center justify-center text-lg"
                                  style={{ background: `${meta.color}22`, border: `1px solid ${meta.color}33` }}>
                                  {meta.icon}
                                </div>
                                <div className="min-w-0 flex-1">
                                  <div className="text-[13px] font-bold text-white truncate">{d.name}</div>
                                  <div className="text-[10px] text-emerald-300">已实名</div>
                                </div>
                              </div>
                              <button onClick={() => pickToCase(d.id)}
                                className="mt-3 w-full py-2 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-400 hover:to-amber-500 shadow-md">
                                用到本案
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}

          {motionOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setMotionOpen(null)}>
              <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
              <div className="relative rounded-2xl w-full max-w-2xl flex flex-col"
                style={{ background: "linear-gradient(180deg, #0a1430 0%, #070c1f 100%)", border: "1px solid rgba(99,102,241,0.25)", boxShadow: "0 20px 60px rgba(0,0,0,0.7)" }}
                onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center justify-between px-5 py-3" style={{ borderBottom: "1px solid rgba(99,102,241,0.15)" }}>
                  <div className="flex items-center gap-2">
                    <FileQuestion className="w-4 h-4 text-fuchsia-300" />
                    <h3 className="font-bold text-white text-[14px]">
                      {(MOTION_TEMPLATES.find((m) => m.key === motionOpen)?.label) || ""}
                    </h3>
                  </div>
                  <button onClick={() => setMotionOpen(null)} className="w-8 h-8 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 flex items-center justify-center">x</button>
                </div>
                <div className="p-5 space-y-3">
                  <textarea value={motionText} onChange={(e) => setMotionText(e.target.value)} rows={8}
                    className="w-full px-3 py-2.5 rounded-xl text-[13px] leading-relaxed text-slate-100 focus:outline-none focus:ring-2 focus:ring-fuchsia-500/30 resize-y"
                    style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.12)", fontFamily: "\"Microsoft YaHei\", sans-serif" }} />
                  <p className="text-[10px] text-slate-500">把方括号里的内容替换成你的事实，当庭照着念</p>
                  <div className="flex gap-2">
                    <button onClick={fileMotion}
                      className="flex-1 py-2.5 rounded-xl font-bold text-white bg-gradient-to-r from-fuchsia-500 to-pink-600 shadow-md">
                      <Send className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />
                      存入已提出列表
                    </button>
                    <button onClick={() => { navigator.clipboard?.writeText(motionText); alert("已复制当庭朗读版"); }}
                      className="px-4 py-2.5 rounded-xl font-semibold text-slate-200 bg-white/5 hover:bg-white/10">
                      复制
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}
