import { useState } from "react";
import { Shield, Lock, ArrowRight, Building2, LogIn } from "lucide-react";
import { useAppStore } from "../store/appStore";

export default function AdminLoginPage({ onLogin }: { onLogin: () => void }) {
  const { loginAsAdmin } = useAppStore();
  const [adminAccount] = useState("admin@ailawyer.cn");
  const [pwd, setPwd] = useState("admin123");
  const [err, setErr] = useState("");

  const doLogin = () => {
    const v = pwd.trim() || (document.querySelector('input') as HTMLInputElement)?.value?.trim() || "";
    if (!v) { setErr("请输入密码"); return; }
    const r = loginAsAdmin(v);
    if (!r.ok) { setErr(r.msg || "登录失败"); return; }
    onLogin();
  };

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center px-6 py-10 overflow-hidden" style={{ background: "linear-gradient(160deg, #0a0e1e 0%, #12204a 55%, #0f2a5f 100%)" }}>
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage:
            "radial-gradient(ellipse at 15% 5%, rgba(212,175,55,0.15) 0%, transparent 40%), radial-gradient(ellipse at 90% 90%, rgba(95,130,200,0.18) 0%, transparent 50%)",
        }}
      />
      <div
        className="absolute inset-0 pointer-events-none opacity-40"
        style={{
          backgroundImage:
            "linear-gradient(rgba(255,255,255,0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px)",
          backgroundSize: "44px 44px",
        }}
      />

      <div className="relative z-10 w-full max-w-md">
        <div className="flex flex-col items-center mb-6">
          <div
            className="w-20 h-20 rounded-2xl flex items-center justify-center mb-4 shadow-2xl border-2"
            style={{
              background: "linear-gradient(135deg,#1a2d5a,#2d4e8f)",
              borderColor: "rgba(212,175,55,0.4)",
              boxShadow: "0 10px 40px rgba(212,175,55,0.15)",
            }}
          >
            <Shield className="w-9 h-9 text-gold-400" />
          </div>
          <h1 className="text-2xl font-extrabold text-white tracking-tight">
            AI 律师<span className="text-gradient-gold"> 后台管理</span>系统
          </h1>
          <p className="text-[12px] text-white/55 mt-1">仅超级管理员可访问，用于配置与授权</p>
        </div>

        <div
          className="rounded-2xl p-7 shadow-2xl border border-white/10"
          style={{ background: "rgba(15,28,60,0.78)", backdropFilter: "blur(18px)" }}
        >
          <form
            className="space-y-5"
            onKeyDown={(e) => {
              if (e.key === "Enter") { e.preventDefault(); doLogin(); }
            }}
          >
            <div>
              <label className="text-[11px] font-semibold text-white/70 uppercase tracking-widest">管理员账号</label>
              <div className="relative mt-2">
                <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/40" />
                <input
                  value={adminAccount}
                  readOnly
                  className="w-full pl-10 pr-3 py-3 rounded-xl text-sm text-white/80 border border-white/10 bg-white/5 focus:outline-none"
                />
              </div>
            </div>

            <div>
              <label className="text-[11px] font-semibold text-white/70 uppercase tracking-widest">管理员密码</label>
              <div className="relative mt-2">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/40" />
                <input
                  type="password"
                  value={pwd}
                  onChange={(e) => { setPwd(e.target.value); setErr(""); }}
                  placeholder="请输入管理员密码"
                  className="w-full pl-10 pr-3 py-3 rounded-xl text-sm text-white placeholder-white/30 border border-white/10 bg-white/5 focus:outline-none focus:ring-2 focus:ring-gold-500/40 focus:border-gold-500 transition-all"
                  autoFocus
                />
              </div>
              {err && <p className="mt-2 text-[11px] text-red-400">{err}</p>}
            </div>

            <button
              type="button"
              onClick={doLogin}
              className="w-full py-3.5 rounded-xl font-bold text-primary-950 flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transition-all transform hover:-translate-y-0.5 active:translate-y-0"
              style={{ background: "linear-gradient(135deg,#f5e4a6 0%,#d4af37 60%,#b8922f 100%)" }}
            >
              <LogIn className="w-4 h-4" />
              进入后台
              <ArrowRight className="w-4 h-4" />
            </button>
          </form>

          <div className="mt-4 pt-4 border-t border-white/10">
            <p className="text-[10px] text-white/45 text-center leading-relaxed">
              忘记密码？请联系系统创建者重置
            </p>
          </div>
        </div>

        <div className="mt-5 text-center">
          <a
            href="#/"
            onClick={(e) => { e.preventDefault(); window.location.hash = "#/"; }}
            className="inline-flex items-center gap-1.5 text-[11px] text-white/60 hover:text-gold-300 transition-colors"
          >
            <Building2 className="w-3.5 h-3.5" />
            ← 返回用户端登录
          </a>
        </div>
      </div>
    </div>
  );
}
