import { useEffect, useState } from "react";
import MainLayout from "./components/MainLayout";
import MissingMaterialsBubble from "./components/MissingMaterialsBubble";
import Sidebar from "./components/Sidebar";
import ChatPage from "./pages/ChatPage";
import CasesPage from "./pages/CasesPage";
import CaseDetailPage from "./pages/CaseDetailPage";
import LawsPage from "./pages/LawsPage";
import KnowledgePage from "./pages/KnowledgePage";
import LoginPage from "./pages/LoginPage";
import UserDocsPage from "./pages/UserDocsPage";
import EvidencePage from "./pages/EvidencePage";
import DefensePage from "./pages/DefensePage";
import FlowGuidePage from "./pages/FlowGuidePage";
import AnalysisPage from "./pages/AnalysisPage";
import { useAppStore } from "./store/appStore";

const pageConfig: Record<string, { title: string }> = {
  chat: { title: "AI 对话" },
  cases: { title: "我的案件" },
  guide: { title: "流程指导" },
  analysis: { title: "AI 分析" },
  evidence: { title: "证据管理" },
  defense: { title: "辩护中心" },
  laws: { title: "法条搜索" },
  knowledge: { title: "知识库" },
  help: { title: "帮助中心" },
  admin: { title: "权限配置" },
};

function Placeholder({ name }: { name: string }) {
  return (
    <div className="flex flex-col items-center justify-center h-full p-8">
      <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-primary-800 to-primary-950 flex items-center justify-center mb-5 shadow-lg shadow-primary-900/30">
        <span className="text-3xl">⚖️</span>
      </div>
      <h2 className="text-xl font-bold text-slate-900 mb-2">{name}</h2>
      <p className="text-slate-500 text-sm">此模块正在开发中，敬请期待</p>
    </div>
  );
}

function getHashPath() {
  const raw = window.location.hash.replace(/^#/, "") || "/";
  const path = raw.split("?")[0];
  return path || "/";
}

function parseQuery() {
  const q = new URLSearchParams(window.location.hash.split("?")[1] || "");
  return {
    tab: q.get("tab") || "chat",
    caseId: q.get("caseId"),
  };
}

function setHash({ tab, caseId }: { tab?: string; caseId?: string }) {
  const q = new URLSearchParams();
  if (tab) q.set("tab", tab);
  if (caseId) q.set("caseId", caseId);
  window.location.hash = `#/?${q.toString()}`;
}

export default function App() {
  const { getCurrentUser, logout } = useAppStore();
  const [path, setPath] = useState(getHashPath());
  const [q, setQ] = useState(parseQuery());

  useEffect(() => {
    const handler = () => {
      setPath(getHashPath());
      setQ(parseQuery());
    };
    window.addEventListener("hashchange", handler);
    return () => window.removeEventListener("hashchange", handler);
  }, []);

  if (path.startsWith("/admin")) {
    return null;
  }

  const currentUser = getCurrentUser();
  if (!currentUser) {
    return <LoginPage onLogin={() => { setHash({ tab: "chat" }); }} />;
  }

  if (currentUser.role === "super_admin") {
    logout();
    return <LoginPage onLogin={() => { setHash({ tab: "chat" }); }} />;
  }

  const cfg = pageConfig[q.tab] || pageConfig.chat;

  const changeTab = (t: string) => {
    setHash({ tab: t, caseId: undefined });
  };

  const openCase = (caseId: string) => {
    setHash({ tab: "cases", caseId });
  };

  const renderContent = () => {
    switch (q.tab) {
      case "docs":
        return <UserDocsPage />;
      case "chat":
        return <ChatPage caseId={q.caseId} onChooseCase={() => q.caseId && setHash({ tab: "cases", caseId: q.caseId })} />;
      case "cases":
        if (q.caseId) {
          return <CaseDetailPage caseId={q.caseId} onBack={() => setHash({ tab: "cases" })} />;
        }
        return <CasesPage onOpenCase={openCase} />;
      case "guide":
        return <FlowGuidePage />;
      case "analysis":
        return <AnalysisPage />;
      case "evidence":
        return <EvidencePage initialCaseId={q.caseId || undefined} />;
      case "defense":
        return <DefensePage />;
      case "laws":
        return <LawsPage />;
      case "knowledge":
        return <KnowledgePage />;
      case "help":
      case "admin":
      default:
        return <Placeholder name={cfg.title} />;
    }
  };

  return (
    <div className="flex h-screen w-full">
      <Sidebar activeItem={q.tab} onItemChange={changeTab} />
      <div className="flex-1 flex flex-col min-w-0">
        <MainLayout
          activeItem={q.tab}
          activeLabel={q.caseId ? `${cfg.title} · 案件详情` : cfg.title}
          onItemChange={changeTab}
          onLogout={() => { logout(); setHash({ tab: "chat" }); }}
        >
          {renderContent()}
        </MainLayout>
        <MissingMaterialsBubble activeTab={q.tab} />
      </div>
    </div>
  );
}
