import { useState } from "react";
import { Scale, Shield, Sparkles, ArrowRight, UserRound, Building2 } from "lucide-react";
import { useAppStore } from "../store/appStore";

const FEATURES = [
  { icon: Scale, title: "智能案件分析", desc: "AI 深度拆解案情" },
  { icon: Shield, title: "证据链管理", desc: "自动梳理证据关系" },
  { icon: Sparkles, title: "法庭辩护策略", desc: "生成辩护代理词" },
];

export default function LoginPage({ onLogin }: { onLogin: () => void }) {
  const { users, loginAsUser } = useAppStore();
  const [identifier, setIdentifier] = useState("");
  const [pwd, setPwd] = useState("");
  const [err, setErr] = useState("");
  const submitRef = useState({ go: false })[0];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!identifier || !pwd) { setErr("请输入账号和密码"); return; }
    const r = loginAsUser(identifier.trim(), pwd);
    if (!r.ok) { setErr(r.msg || "登录失败"); return; }
    onLogin();
  };

  const quickLogin = (u: typeof users[number]) => {
    const r = loginAsUser(u.email || u.phone || u.id, u.password || "123456");
    if (r.ok) onLogin();
    else setErr(r.msg || "登录失败");
  };

  const quickUsers = users
    .filter((u) => u.role !== "super_admin")
    .map((u) => ({ id: u.id, label: `${u.name}（${u.role === "vip" ? "VIP" : "普通"}）`, hint: u.email }));

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center overflow-hidden px-4" style={{ background: "linear-gradient(160deg, #0c1528 0%, #1a2d5a 45%, #2a4a8a 100%)" }}>
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage:
            "radial-gradient(ellipse at 20% 10%, rgba(212,175,55,0.18) 0%, transparent 40%), radial-gradient(ellipse at 85% 85%, rgba(95,130,200,0.22) 0%, transparent 45%)",
        }}
      />
      <div
        className="absolute inset-0 pointer-events-none opacity-40"
        style={{
          backgroundImage:
            "linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px)",
          backgroundSize: "48px 48px",
        }}
      />

      <div className="relative z-10 flex flex-col lg:flex-row items-stretch w-full max-w-[1080px] min-h-[620px] rounded-3xl overflow-hidden shadow-[0_30px_100px_rgba(0,0,0,0.6)] border border-white/10"
        style={{ background: "rgba(12,20,50,0.55)", backdropFilter: "blur(20px)" }}>

        <div className="flex-1 flex items-center justify-center px-8 py-10 lg:border-r lg:border-white/10"
          style={{ background: "linear-gradient(160deg, rgba(12,20,50,0.9) 0%, rgba(26,45,90,0.85) 100%)" }}>
          <div className="max-w-md w-full text-center text-white">
            <div className="mb-7 text-center">
              <div
                className="inline-block text-[24px] lg:text-[30px] font-black tracking-[0.12em]"
                style={{
                  background: "linear-gradient(90deg,#8a641b 0%,#f5e4a6 18%,#fff7c2 35%,#d4af37 52%,#fff2a8 68%,#b8860b 100%)",
                  backgroundSize: "220% 100%",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                  filter: "drop-shadow(0 0 10px rgba(212,175,55,0.9)) drop-shadow(0 0 24px rgba(245,228,166,0.45))",
                  animation: "goldShine 2.8s ease-in-out infinite",
                }}
              >
                法律守护者，正义的化身
              </div>
              <style>{`@keyframes goldShine { 0% { background-position: 0% 50%; filter: drop-shadow(0 0 8px rgba(212,175,55,0.55)); } 50% { background-position: 100% 50%; filter: drop-shadow(0 0 16px rgba(245,228,166,0.95)) drop-shadow(0 0 32px rgba(212,175,55,0.55)); } 100% { background-position: 0% 50%; filter: drop-shadow(0 0 8px rgba(212,175,55,0.55)); } }`}</style>
            </div>

            <div className="inline-flex items-center justify-center w-20 h-20 rounded-2xl mb-7 shadow-2xl" style={{ background: "linear-gradient(135deg, #d4af37, #f5e4a6, #d4af37)" }}>
              <Scale className="w-10 h-10 text-primary-950" />
            </div>
            <h1 className="text-[36px] lg:text-[44px] font-extrabold leading-[1.1] tracking-tight">
              地表最强<span style={{ background: "linear-gradient(90deg,#f5e4a6,#d4af37,#f5e4a6)", WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent" }}> 人工智能</span>律师
            </h1>
            <p className="mt-5 text-white/70 text-[14px] leading-relaxed">
              让每个当事人都能拥有专属的 AI 辩护律师
              <br className="hidden lg:block" />
              从案件分析、证据整理到法庭辩护，一站式为你维权
            </p>

            <div className="mt-10 grid grid-cols-3 gap-3">
              {FEATURES.map((f) => {
                const Icon = f.icon;
                return (
                  <div key={f.title} className="rounded-2xl p-4 border border-white/10" style={{ background: "rgba(255,255,255,0.06)" }}>
                    <div className="w-9 h-9 rounded-lg flex items-center justify-center mb-2" style={{ background: "rgba(212,175,55,0.22)" }}>
                      <Icon className="w-4.5 h-4.5" style={{ color: "#f5e4a6" }} />
                    </div>
                    <div className="text-sm font-semibold text-white">{f.title}</div>
                    <div className="text-[11px] text-white/60 mt-1">{f.desc}</div>
                  </div>
                );
              })}
            </div>
            <div className="mt-8 flex items-center justify-center gap-5 text-[11px] text-white/55">
              <span>100,233 位当事人使用</span>
              <span>·</span>
              <span>95% 胜诉率</span>
            </div>
          </div>
        </div>

        <div className="flex-1 flex items-center justify-center px-8 py-10">
          <div className="w-full max-w-sm">
            <div className="flex justify-center mb-5">
              <div className="relative">
                <div className="absolute inset-0 rounded-full blur-xl opacity-60" style={{ background: "linear-gradient(135deg,#d4af37,#f5e4a6)" }} />
                <div
                  className="relative w-24 h-24 rounded-full flex items-center justify-center text-3xl font-bold shadow-2xl border-4"
                  style={{
                    background: "linear-gradient(135deg,#f5e4a6 0%,#d4af37 100%)",
                    borderColor: "rgba(255,255,255,0.35)",
                    color: "#0c1528",
                  }}
                >
                  ⚖️
                </div>
                <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 px-3 py-0.5 rounded-full text-[10px] font-semibold whitespace-nowrap shadow" style={{ background: "#f5e4a6", color: "#0c1528" }}>
                  AI 专享律师
                </div>
              </div>
            </div>

            <h2 className="text-center text-xl font-bold text-white">欢迎回来</h2>
            <p className="text-center text-xs text-white/55 mt-1">登录进入你的智能法律助手</p>

            <form onSubmit={handleSubmit} className="mt-6 space-y-3">
              <div>
                <label className="text-[11px] font-semibold text-white/60 uppercase tracking-widest">账号 / 手机号 / 邮箱</label>
                <input
                  value={identifier}
                  onChange={(e) => { setIdentifier(e.target.value); setErr(""); }}
                  placeholder="输入你的账号"
                  className="mt-1 w-full px-4 py-3 rounded-xl text-sm text-white placeholder-white/30 border border-white/10 bg-white/5 focus:outline-none focus:ring-2 focus:ring-gold-500/40 focus:border-gold-500 transition-all"
                />
              </div>
              <div>
                <label className="text-[11px] font-semibold text-white/60 uppercase tracking-widest">密码</label>
                <input
                  type="password"
                  value={pwd}
                  onChange={(e) => { setPwd(e.target.value); setErr(""); }}
                  placeholder="输入密码"
                  className="mt-1 w-full px-4 py-3 rounded-xl text-sm text-white placeholder-white/30 border border-white/10 bg-white/5 focus:outline-none focus:ring-2 focus:ring-gold-500/40 focus:border-gold-500 transition-all"
                />
              </div>
              {err && <p className="text-[11px] text-red-400 text-center">{err}</p>}
              <button
                type="submit"
                className="w-full py-3.5 rounded-xl font-bold text-primary-950 flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transition-all transform hover:-translate-y-0.5 active:translate-y-0"
                style={{ background: "linear-gradient(135deg,#f5e4a6 0%,#d4af37 60%,#b8922f 100%)" }}
              >
                <UserRound className="w-4 h-4" />
                登录
                <ArrowRight className="w-4 h-4" />
              </button>
            </form>

            <div className="mt-4 pt-4 border-t border-white/10">
              <div className="text-[10px] text-white/45 mb-2 text-center">演示账号（请联系管理员开通正式账号）</div>
              <div className="grid grid-cols-2 gap-2">
                {quickUsers.slice(0, 4).map((u) => {
                  const uu = users.find((x) => x.id === u.id)!;
                  return (
                    <button
                      key={u.id}
                      type="button"
                      onClick={() => quickLogin(uu)}
                      className="text-[11px] px-2 py-1.5 rounded-md border border-white/10 bg-white/5 text-white/70 hover:bg-white/10 hover:text-white hover:border-white/20 transition-all truncate"
                    >
                      {u.label}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="mt-4 text-center">
              <a
                href="#/admin"
                onClick={(e) => { e.preventDefault(); window.location.hash = "#/admin"; }}
                className="inline-flex items-center gap-1.5 text-[11px] text-white/60 hover:text-gold-300 transition-colors"
              >
                <Building2 className="w-3.5 h-3.5" />
                进入后台管理系统 →
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
