import { useEffect, useRef, useState } from "react";

export function useTypewriter(text: string, enabled: boolean = true, speedMin = 4, speedMax = 16) {
  const [display, setDisplay] = useState("");
  const [done, setDone] = useState(false);
  const idxRef = useRef(0);
  const cancelled = useRef(false);

  useEffect(() => {
    idxRef.current = 0;
    setDisplay("");
    setDone(false);
    cancelled.current = false;
    if (!text || !enabled) {
      setDisplay(text || "");
      setDone(true);
      return;
    }
    const step = () => {
      if (cancelled.current) return;
      if (idxRef.current >= text.length) {
        setDone(true);
        return;
      }
      idxRef.current += 1;
      setDisplay(text.slice(0, idxRef.current));
      const speed = speedMin + Math.floor(Math.random() * (speedMax - speedMin + 1));
      setTimeout(step, speed);
    };
    const handle = setTimeout(step, 80);
    return () => {
      cancelled.current = true;
      clearTimeout(handle);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, enabled]);

  const skip = () => {
    cancelled.current = true;
    setDisplay(text);
    setDone(true);
  };

  return { display, done, skip };
}
