interface Tab {
  key: string;
  label: string;
  icon?: React.ReactNode;
  content: React.ReactNode;
}

interface Props {
  tabs: Tab[];
  activeKey: string;
  onChange: (key: string) => void;
}

export default function TabPanel({ tabs, activeKey, onChange }: Props) {
  return (
    <div className="h-full flex flex-col">
      <div className="flex gap-1.5 px-3 py-2 shrink-0 overflow-x-auto" style={{ background: "rgba(8,12,32,0.8)", borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
        {tabs.map((t) => {
          const active = t.key === activeKey;
          return (
            <button
              key={t.key}
              onClick={() => onChange(t.key)}
              className={`shrink-0 flex items-center gap-2 px-4 py-2 rounded-lg font-bold text-[13px] transition-all ${
                active
                  ? "text-white shadow-md"
                  : "text-white/55 hover:text-white hover:bg-white/5"
              }`}
              style={active ? {
                background: "linear-gradient(135deg, #3d64b0 0%, #5f82c8 40%, #d4af37 120%)",
                boxShadow: "0 3px 14px rgba(61,100,176,0.5)",
                fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
              } : { fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}
            >
              {t.icon}
              {t.label}
            </button>
          );
        })}
      </div>
      <div className="flex-1 overflow-y-auto">{tabs.find((t) => t.key === activeKey)?.content}</div>
    </div>
  );
}
