export function getSimilarCases(type: string, count = 3): SimilarCase[] {
  const list = (templateSimilarCases as any)[type] || templateSimilarCases["其他"];
  return list.slice(0, count);
}

export function formatDate(d: Date): string {
  const y = d.getFullYear();
  const m = (d.getMonth() + 1).toString().padStart(2, "0");
  const day = d.getDate().toString().padStart(2, "0");
  return `${y}-${m}-${day}`;
}

export function formatNow(): string {
  return formatDate(new Date());
}

export function nextCaseId(): string {
  return `CASE-${Date.now().toString(36).toUpperCase()}`;
}

export function nextEvidenceId(): string {
  return `E-${Date.now().toString(36).toUpperCase()}`;
}

export function nextChatMsgId(): string {
  return `CM-${Date.now().toString(36)}`;
}

export function nowHHMM(): string {
  const d = new Date();
  return `${d.getHours().toString().padStart(2, "0")}:${d.getMinutes().toString().padStart(2, "0")}`;
}
