import { FileText, Search, Plus, Filter, CheckCircle, Gavel, AlertTriangle, Trash2, Scale as ScaleIcon, TrendingUp, ShieldAlert, Swords, HelpCircle } from "lucide-react";
import { useState, useMemo } from "react";
import { useCaseStore } from "../store/caseStore";
import { useAppStore } from "../store/appStore";
import Modal from "../components/Modal";
import { caseTypes } from "../lib/templates";

function getStatusIcon(s: string) {
  switch (s) {
    case "ready": return <CheckCircle className="w-4 h-4 text-emerald-400" />;
    case "analyzing": return <div className="w-4 h-4 border-2 border-gold-400 border-t-transparent rounded-full animate-spin" />;
    case "defending": return <Gavel className="w-4 h-4 text-rose-400" />;
    case "closed": return <CheckCircle className="w-4 h-4 text-white/40" />;
    default: return <AlertTriangle className="w-4 h-4 text-white/40" />;
  }
}

function getStatusLabel(s: string) {
  switch (s) {
    case "draft": return "草稿";
    case "analyzing": return "AI 分析中";
    case "ready": return "准备辩护";
    case "defending": return "辩护中";
    case "closed": return "已结案";
    default: return s;
  }
}

function getStatusStyle(s: string) {
  switch (s) {
    case "ready": return { bg: "rgba(16,185,129,0.18)", color: "#86efac", border: "rgba(16,185,129,0.3)" };
    case "analyzing": return { bg: "rgba(212,175,55,0.18)", color: "#fde68a", border: "rgba(212,175,55,0.3)" };
    case "defending": return { bg: "rgba(244,63,94,0.18)", color: "#fda4af", border: "rgba(244,63,94,0.3)" };
    case "closed": return { bg: "rgba(148,163,184,0.15)", color: "#cbd5e1", border: "rgba(148,163,184,0.2)" };
    default: return { bg: "rgba(148,163,184,0.1)", color: "#cbd5e1", border: "rgba(148,163,184,0.2)" };
  }
}

function getTypeStyle(type: string) {
  const map: Record<string, { bg: string; color: string; accent: string }> = {
    "劳动争议": { bg: "rgba(59,130,246,0.18)", color: "#93c5fd", accent: "#3b82f6" },
    "交通事故": { bg: "rgba(239,68,68,0.18)", color: "#fca5a5", accent: "#ef4444" },
    "房屋买卖": { bg: "rgba(16,185,129,0.18)", color: "#86efac", accent: "#10b981" },
    "房屋租赁": { bg: "rgba(59,130,246,0.18)", color: "#93c5fd", accent: "#3b82f6" },
    "民间借贷": { bg: "rgba(212,175,55,0.18)", color: "#fde68a", accent: "#d4af37" },
    "婚姻离婚": { bg: "rgba(236,72,153,0.18)", color: "#f9a8d4", accent: "#ec4899" },
    "抚养权": { bg: "rgba(236,72,153,0.18)", color: "#f9a8d4", accent: "#ec4899" },
    "遗产继承": { bg: "rgba(168,85,247,0.18)", color: "#d8b4fe", accent: "#a855f7" },
    "消费者权益": { bg: "rgba(251,146,60,0.18)", color: "#fdba74", accent: "#fb923c" },
    "医疗纠纷": { bg: "rgba(14,165,233,0.18)", color: "#7dd3fc", accent: "#0ea5e9" },
    "故意伤害": { bg: "rgba(220,38,38,0.18)", color: "#fca5a5", accent: "#dc2626" },
    "名誉侵权": { bg: "rgba(139,92,246,0.18)", color: "#c4b5fd", accent: "#8b5cf6" },
    "合同纠纷": { bg: "rgba(34,197,94,0.18)", color: "#86efac", accent: "#22c55e" },
    "工伤赔偿": { bg: "rgba(249,115,22,0.18)", color: "#fdba74", accent: "#f97316" },
    "物业纠纷": { bg: "rgba(100,116,139,0.18)", color: "#cbd5e1", accent: "#64748b" },
    "公司股权": { bg: "rgba(212,175,55,0.18)", color: "#fde68a", accent: "#d4af37" },
    "保险理赔": { bg: "rgba(6,182,212,0.18)", color: "#67e8f9", accent: "#06b6d4" },
    "行政诉讼": { bg: "rgba(239,68,68,0.18)", color: "#fca5a5", accent: "#ef4444" },
    "知识产权": { bg: "rgba(139,92,246,0.18)", color: "#c4b5fd", accent: "#8b5cf6" },
    "其他": { bg: "rgba(148,163,184,0.18)", color: "#cbd5e1", accent: "#64748b" },
  };
  return map[type] || map["其他"];
}

export default function CasesPage({ onOpenCase }: { onOpenCase: (caseId: string) => void }) {
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const { getCasesByUser, createCase, deleteCase } = useCaseStore();
  const [filter, setFilter] = useState<string>("all");
  const [q, setQ] = useState("");
  const [createOpen, setCreateOpen] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<{ id: string; title: string } | null>(null);

  const defaultParties = currentUser ? `${currentUser.name}（${currentUser.role === "vip" ? "VIP" : currentUser.role === "user" ? "当事人" : ""}）` : "您";
  const [form, setForm] = useState({ title: "", type: "劳动争议", parties: defaultParties, facts: "" });

  const userId = currentUser?.id || "user-001";
  const allCases = useMemo(() => getCasesByUser(userId), [getCasesByUser, userId]);

  const filtered = useMemo(() => {
    let r = allCases;
    if (filter !== "all") r = r.filter((c) => c.status === filter);
    if (q.trim()) {
      const k = q.trim().toLowerCase();
      r = r.filter(
        (c) =>
          c.title.toLowerCase().includes(k) ||
          c.type.toLowerCase().includes(k) ||
          c.parties.toLowerCase().includes(k) ||
          c.facts.toLowerCase().includes(k)
      );
    }
    return [...r].sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
  }, [allCases, filter, q]);

  const onCreate = () => {
    if (!form.title.trim() || !form.facts.trim()) return;
    createCase({ ...form, userId });
    setForm({ title: "", type: "劳动争议", parties: defaultParties, facts: "" });
    setCreateOpen(false);
  };

  const doDelete = () => {
    if (!confirmDelete) return;
    deleteCase(confirmDelete.id);
    setConfirmDelete(null);
  };

  const pageBg = { background: "linear-gradient(180deg, #080c20 0%, #0a1230 100%)" };
  const inputCls = "w-64 pl-10 pr-4 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-white placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/60 transition-all";
  const panelCls = "flex items-center gap-2 px-3 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-white/80";

  return (
    <div className="p-6 h-full overflow-y-auto" style={pageBg}>
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center gap-3 flex-wrap">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/40" />
            <input
              value={q}
              onChange={(e) => setQ(e.target.value)}
              type="text"
              placeholder="🔍 搜索案件..."
              className={inputCls}
            />
          </div>
          <div className={panelCls}>
            <Filter className="w-4 h-4 text-white/40" />
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              className="bg-transparent outline-none text-white/90 cursor-pointer"
            >
              <option value="all" className="bg-slate-900">全部状态</option>
              <option value="draft" className="bg-slate-900">草稿</option>
              <option value="analyzing" className="bg-slate-900">AI分析中</option>
              <option value="ready" className="bg-slate-900">准备辩护</option>
              <option value="defending" className="bg-slate-900">辩护中</option>
              <option value="closed" className="bg-slate-900">已结案</option>
            </select>
          </div>
          <span className="text-xs text-white/50 px-1">共 {allCases.length} 个案件</span>
        </div>
        <button
          onClick={() => setCreateOpen(true)}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-white text-sm shadow-md transition-all"
          style={{
            background: "linear-gradient(135deg, #3d64b0 0%, #5f82c8 40%, #d4af37 120%)",
            boxShadow: "0 4px 20px rgba(61,100,176,0.5)",
            fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
          }}
        >
          <Plus className="w-4 h-4" />
          新建案件
        </button>
      </div>

      <div className="grid gap-3">
        {filtered.map((c) => {
          const isReady = c.status === "ready" || c.status === "defending" || c.status === "analyzing";
          const st = getStatusStyle(c.status);
          const tp = getTypeStyle(c.type);
          return (
            <div
              key={c.id}
              className="p-4 rounded-2xl border transition-all group"
              style={{
                background: "linear-gradient(135deg, rgba(61,100,176,0.08) 0%, rgba(15,20,45,0.95) 100%)",
                borderColor: "rgba(99,102,241,0.18)",
                boxShadow: "0 4px 16px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.04)",
              }}
            >
              <div className="flex items-start gap-4">
                <button
                  onClick={() => onOpenCase(c.id)}
                  className="w-12 h-12 rounded-xl flex items-center justify-center shrink-0 transition-transform group-hover:scale-105"
                  style={{
                    background: `linear-gradient(135deg, ${tp.accent}60 0%, ${tp.accent}30 100%)`,
                    boxShadow: `0 4px 14px ${tp.accent}40, inset 0 1px 0 rgba(255,255,255,0.2)`,
                    border: `1px solid ${tp.accent}50`,
                  }}
                >
                  <FileText className="w-5 h-5 text-white" />
                </button>
                <div className="flex-1 min-w-0 cursor-pointer" onClick={() => onOpenCase(c.id)}>
                  <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                    <span className="text-[15px] font-bold text-white group-hover:text-gold-300 transition-colors truncate" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>{c.title}</span>
                    <span className="px-2 py-0.5 rounded-full text-[10px] font-bold border" style={{ background: st.bg, color: st.color, borderColor: st.border }}>
                      {getStatusLabel(c.status)}
                    </span>
                  </div>
                  <div className="flex items-center gap-2.5 text-[11px] text-white/60 mb-2.5 flex-wrap">
                    <span className="px-2 py-0.5 rounded-md font-bold border" style={{ background: tp.bg, color: tp.color, borderColor: tp.border }}>{c.type}</span>
                    <span className="text-white/25">·</span>
                    <span className="text-white/85">{c.parties || "未填写当事人"}</span>
                    <span className="text-white/25">·</span>
                    <span>{c.updatedAt}</span>
                  </div>
                  {c.facts && (
                    <p className="text-[12px] text-white/55 mb-2 line-clamp-2 leading-relaxed">
                      {c.facts.slice(0, 140)}{c.facts.length > 140 ? "..." : ""}
                    </p>
                  )}
                  <div className="flex items-center gap-3">
                    <div className="flex-1 h-1.5 rounded-full bg-white/10 overflow-hidden">
                      <div
                        className="h-full rounded-full transition-all duration-500"
                        style={{
                          width: `${c.progress}%`,
                          background: c.progress === 100
                            ? "linear-gradient(90deg, #10b981, #34d399)"
                            : c.progress >= 60
                            ? "linear-gradient(90deg, #3d64b0, #5f82c8)"
                            : "linear-gradient(90deg, #f59e0b, #fbbf24)",
                        }}
                      />
                    </div>
                    <span className="text-xs font-bold text-white/80 w-10 text-right">{c.progress}%</span>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-1">
                  <div className="w-11 h-11 rounded-xl flex items-center justify-center" style={{ background: st.bg, border: `1px solid ${st.border}` }}>
                    {getStatusIcon(c.status)}
                  </div>
                  {c.id.startsWith("CASE-") && (
                    <button
                      onClick={(e) => { e.stopPropagation(); setConfirmDelete({ id: c.id, title: c.title }); }}
                      className="p-1.5 rounded-lg text-white/30 hover:text-rose-400 hover:bg-rose-500/10 opacity-0 group-hover:opacity-100 transition-all"
                      title="删除案件"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
              </div>
              {isReady && (
                <div className="mt-3 pt-3 border-t border-white/5 flex gap-2">
                  <button
                    onClick={() => onOpenCase(c.id)}
                    className="text-xs font-bold text-white px-3 py-1.5 rounded-lg transition-colors"
                    style={{ background: "rgba(212,175,55,0.18)", border: "1px solid rgba(212,175,55,0.35)", color: "#fde68a" }}
                  >
                    进入案件详情 →
                  </button>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {filtered.length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 text-center">
          <div className="w-20 h-20 rounded-2xl bg-white/5 flex items-center justify-center mb-4 border border-white/10">
            <FileText className="w-8 h-8 text-white/30" />
          </div>
          <p className="text-white/60 mb-4">
            {allCases.length === 0 ? "暂无案件，创建您的第一个案件开始吧" : "没有匹配的案件"}
          </p>
          {allCases.length === 0 && (
            <button
              onClick={() => setCreateOpen(true)}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-white text-sm shadow-md transition-all"
              style={{
                background: "linear-gradient(135deg, #3d64b0 0%, #5f82c8 40%, #d4af37 120%)",
                boxShadow: "0 4px 20px rgba(61,100,176,0.5)",
                fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
              }}
            >
              <Plus className="w-4 h-4" />
              创建第一个案件
            </button>
          )}
        </div>
      )}

      <Modal
        open={createOpen}
        onClose={() => setCreateOpen(false)}
        title="⚖️ 新建案件"
        widthClass="max-w-2xl"
        footer={
          <>
            <button onClick={() => setCreateOpen(false)} className="px-4 py-2 rounded-xl text-sm font-medium text-white/70 hover:bg-white/10 transition-all">取消</button>
            <button
              onClick={onCreate}
              disabled={!form.title.trim() || !form.facts.trim()}
              className="px-5 py-2 rounded-xl text-sm font-bold text-white shadow-md disabled:opacity-40 disabled:cursor-not-allowed transition-all"
              style={{
                background: "linear-gradient(135deg, #3d64b0 0%, #d4af37 120%)",
                boxShadow: "0 4px 20px rgba(61,100,176,0.5)",
                fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif",
              }}
            >
              ✨ 创建案件
            </button>
          </>
        }
      >
        <div className="space-y-4">
          <div>
            <label className="text-xs font-bold text-white/70 block mb-1.5" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>📝 案件标题 *</label>
            <input
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
              placeholder="如：劳动合同纠纷"
              className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/60"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-white/70 block mb-1.5" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>🏷️ 案由类型 *</label>
            <select
              value={form.type}
              onChange={(e) => setForm({ ...form, type: e.target.value })}
              className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/60"
            >
              {caseTypes.map((t) => (
                <option key={t.value} value={t.value} className="bg-slate-900">{t.label}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-xs font-bold text-white/70 block mb-1.5" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>👤 当事人（默认是您本人，可修改）</label>
            <input
              value={form.parties}
              onChange={(e) => setForm({ ...form, parties: e.target.value })}
              placeholder="如：您 vs 某科技有限公司"
              className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/60"
              style={defaultParties && form.parties === defaultParties ? { background: "linear-gradient(135deg, rgba(212,175,55,0.15), rgba(61,100,176,0.1))", borderColor: "rgba(212,175,55,0.35)" } : {}}
            />
          </div>
          <div>
            <label className="text-xs font-bold text-white/70 block mb-1.5" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>💬 案情描述 *（越具体 AI 分析越准）</label>
            <textarea
              value={form.facts}
              onChange={(e) => setForm({ ...form, facts: e.target.value })}
              placeholder="什么时候发生了什么事？您手上有哪些证据？对方是什么反应？把关键时间、金额、地点写清楚，越详细 AI 越能给出精准方案。"
              rows={6}
              className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/60 resize-none"
            />
          </div>
        </div>
      </Modal>

      <Modal
        open={!!confirmDelete}
        onClose={() => setConfirmDelete(null)}
        title="🗑️ 删除案件"
        widthClass="max-w-md"
        footer={
          <>
            <button onClick={() => setConfirmDelete(null)} className="px-4 py-2 rounded-xl text-sm font-medium text-white/70 hover:bg-white/10 transition-all">取消</button>
            <button onClick={doDelete} className="px-4 py-2 rounded-xl text-sm font-bold text-white bg-rose-500 hover:bg-rose-600 transition-all shadow-md">确认删除</button>
          </>
        }
      >
        <p className="text-white/90 text-sm leading-relaxed">
          确定删除案件 <span className="font-bold text-white">「{confirmDelete?.title}」</span>？
          <br />案件下的证据、AI 分析结果、辩护材料将一起删除。此操作不可恢复。
        </p>
      </Modal>
    </div>
  );
}
