import { useMemo, useState } from "react";
import { AlertTriangle, CheckCircle, FileText, Gavel, RefreshCw, Scale, Search, Sparkles, TrendingUp } from "lucide-react";
import AnalysisTab from "./tabs/AnalysisTab";
import { useAppStore } from "../store/appStore";
import { useCaseStore } from "../store/caseStore";
import { getMissingMaterials } from "../lib/materialGuide";

function statusLabel(status: string) {
  switch (status) {
    case "draft": return "草稿";
    case "analyzing": return "AI 分析中";
    case "ready": return "已分析";
    case "defending": return "辩护中";
    case "closed": return "已结案";
    default: return status;
  }
}

export default function AnalysisPage() {
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const { getCasesByUser, getAnalysis, getEvidences } = useCaseStore();
  const userId = currentUser?.id || "user-001";
  const cases = getCasesByUser(userId).sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
  const [selectedCaseId, setSelectedCaseId] = useState(cases[0]?.id || "");
  const [query, setQuery] = useState("");

  const selectedCase = cases.find((c) => c.id === selectedCaseId) || cases[0];
  const activeCaseId = selectedCase?.id || "";
  const evidences = activeCaseId ? getEvidences(activeCaseId) : [];
  const analysis = activeCaseId ? getAnalysis(activeCaseId) : undefined;
  const missingMaterials = useMemo(() => getMissingMaterials(selectedCase, evidences), [selectedCase, evidences]);

  const filteredCases = useMemo(() => {
    const k = query.trim().toLowerCase();
    if (!k) return cases;
    return cases.filter((c) => c.title.toLowerCase().includes(k) || c.type.toLowerCase().includes(k) || c.parties.toLowerCase().includes(k));
  }, [cases, query]);

  const goEvidence = () => {
    if (!activeCaseId) return;
    window.location.hash = `#/?tab=evidence&caseId=${activeCaseId}&showMissing=1`;
  };

  return (
    <div className="h-full flex" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <aside className="w-[340px] shrink-0 h-full border-r border-indigo-500/15 flex flex-col" style={{ background: "linear-gradient(180deg,#080c20,#0a1230)" }}>
        <div className="p-4 border-b border-white/5">
          <div className="flex items-center gap-2 mb-3">
            <TrendingUp className="w-5 h-5 text-emerald-300" />
            <div>
              <h2 className="text-white font-bold text-[16px]">AI 分析</h2>
              <p className="text-[11px] text-slate-400">左侧选案件，右侧直接分析出结论</p>
            </div>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/35" />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="搜索案件..." className="w-full pl-9 pr-3 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-white placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-emerald-500/30" />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-2">
          {filteredCases.map((c) => {
            const active = c.id === activeCaseId;
            const cAnalysis = getAnalysis(c.id);
            const evidenceCount = getEvidences(c.id).length;
            const missingCount = getMissingMaterials(c, getEvidences(c.id)).length;
            return (
              <button key={c.id} onClick={() => setSelectedCaseId(c.id)} className="w-full text-left rounded-2xl p-3 transition-all" style={{ background: active ? "linear-gradient(135deg, rgba(16,185,129,0.18), rgba(61,100,176,0.16))" : "rgba(255,255,255,0.04)", border: active ? "1px solid rgba(16,185,129,0.45)" : "1px solid rgba(255,255,255,0.08)" }}>
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 rounded-xl flex items-center justify-center bg-gradient-to-br from-emerald-500 to-teal-600 text-white shrink-0">
                    <Scale className="w-4 h-4" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="text-[13px] font-bold text-white truncate">{c.title}</div>
                    <div className="text-[10px] text-slate-400 mt-0.5 truncate">{c.type} · {c.parties}</div>
                    <div className="mt-2 flex items-center gap-1.5 flex-wrap text-[10px]">
                      <span className="px-2 py-0.5 rounded-full bg-white/5 text-slate-300 border border-white/10">{statusLabel(c.status)}</span>
                      <span className="px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-200 border border-amber-500/25">证据 {evidenceCount}</span>
                      {missingCount > 0 && <span className="px-2 py-0.5 rounded-full bg-rose-500/15 text-rose-200 border border-rose-500/25">缺 {missingCount}</span>}
                      {cAnalysis && <span className="px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-200 border border-emerald-500/25">已有结论</span>}
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
          {filteredCases.length === 0 && <div className="text-center text-slate-500 text-sm py-10">没有匹配案件</div>}
        </div>
      </aside>

      <main className="flex-1 min-w-0 h-full overflow-y-auto">
        {!selectedCase ? (
          <div className="h-full flex items-center justify-center text-slate-400">暂无案件，请先创建案件</div>
        ) : (
          <div className="min-h-full">
            <div className="px-6 py-4 border-b border-indigo-500/15 flex items-center justify-between gap-4 flex-wrap" style={{ background: "linear-gradient(180deg,#0a1430,#0a0f24)" }}>
              <div>
                <h1 className="text-xl font-bold text-white flex items-center gap-2"><Scale className="w-5 h-5 text-emerald-300" />{selectedCase.title}</h1>
                <p className="text-[12px] text-slate-400 mt-1">{selectedCase.type} · {selectedCase.parties}</p>
              </div>
              <div className="flex items-center gap-2 text-[11px] text-slate-300 flex-wrap">
                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-amber-500/10 text-amber-200 border border-amber-500/25"><FileText className="w-3 h-3" /> 证据 {evidences.length}</span>
                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-indigo-500/10 text-indigo-200 border border-indigo-500/25"><Sparkles className="w-3 h-3" /> {analysis ? "已有完整结论" : "可直接分析"}</span>
                <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-emerald-500/10 text-emerald-200 border border-emerald-500/25"><CheckCircle className="w-3 h-3" /> {statusLabel(selectedCase.status)}</span>
              </div>
            </div>

            {missingMaterials.length > 0 && (
              <div className="mx-6 mt-5 rounded-2xl p-4" style={{ background: "rgba(245,158,11,0.08)", border: "1px solid rgba(245,158,11,0.28)" }}>
                <div className="flex items-start justify-between gap-4 flex-wrap">
                  <div>
                    <div className="text-sm font-bold text-amber-100 flex items-center gap-2"><AlertTriangle className="w-4 h-4 text-amber-300" /> 分析前建议补充材料</div>
                    <p className="text-[11px] text-amber-100/70 mt-1">材料缺失不阻止 AI 分析，但会影响结论准确性。建议先补齐后重新分析。</p>
                    <div className="mt-2 flex flex-wrap gap-1.5">{missingMaterials.map((m) => <span key={m} className="px-2 py-1 rounded-lg text-[10px] text-amber-100 bg-amber-500/12 border border-amber-500/22">{m}</span>)}</div>
                  </div>
                  <button onClick={goEvidence} className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-amber-600 to-orange-600 hover:from-amber-500 hover:to-orange-500 transition-all">
                    去补充证据
                  </button>
                </div>
              </div>
            )}

            <AnalysisTab caseId={activeCaseId} />

            {analysis && (
              <div className="mx-6 mb-6 rounded-2xl p-4" style={{ background: "rgba(16,185,129,0.08)", border: "1px solid rgba(16,185,129,0.22)" }}>
                <div className="flex items-center gap-2 text-emerald-100 font-bold text-sm"><Gavel className="w-4 h-4" /> 分析结论已在当前页面完成</div>
                <p className="text-[12px] text-emerald-100/75 mt-1">你可以继续在本页重新分析，或进入辩护中心生成策略与文稿。</p>
                <button onClick={() => { window.location.hash = `#/?tab=defense&caseId=${activeCaseId}`; }} className="mt-3 inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-rose-600 to-red-600">
                  进入辩护中心
                </button>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}
