import { useState } from "react";
import { BookUp, FileUp, CheckCircle, XCircle, Plus, Trash2, CreditCard, Camera, Search, Filter } from "lucide-react";
import { useCaseStore, DOC_CATEGORY_META, DocCategory } from "../store/caseStore";
import { useAppStore } from "../store/appStore";

interface PresetUpload {
  category: DocCategory;
  name: string;
  fileName: string;
  type: "document" | "image" | "audio" | "video";
  summary: string;
  info?: { label: string; value: string }[];
}

const PRESETS: Record<DocCategory, PresetUpload[]> = {
  id_front: [{ category: "id_front", name: "身份证正面", fileName: "身份证正面.jpg", type: "image", summary: "身份证人像面，已做实名认证，可直接用于所有案件。",
    info: [{ label: "姓名", value: "实名认证提取" }, { label: "性别", value: "实名认证提取" }, { label: "身份证号", value: "实名认证提取" }] }],
  id_back: [{ category: "id_back", name: "身份证反面", fileName: "身份证反面.jpg", type: "image", summary: "身份证国徽面，有效期内。",
    info: [{ label: "住址", value: "实名认证提取" }, { label: "签发机关", value: "实名认证提取" }] }],
  business_license: [{ category: "business_license", name: "营业执照", fileName: "营业执照.pdf", type: "document", summary: "营业执照正本扫描件，统一社会信用代码完整。",
    info: [{ label: "企业名称", value: "营业执照提取" }, { label: "统一社会信用代码", value: "营业执照提取" }, { label: "法定代表人", value: "营业执照提取" }] }],
  property: [{ category: "property", name: "不动产权证", fileName: "不动产权证.pdf", type: "document", summary: "不动产权证，房屋面积、坐落、权利人清晰。",
    info: [{ label: "权利人", value: "房产证提取" }, { label: "坐落", value: "房产证提取" }, { label: "面积", value: "房产证提取" }] }],
  death_cert: [{ category: "death_cert", name: "死亡证明", fileName: "死亡证明.pdf", type: "document", summary: "医院或公安出具的死亡证明。",
    info: [{ label: "死者姓名", value: "死亡证明提取" }, { label: "死亡日期", value: "死亡证明提取" }] }],
  transfer: [{ category: "transfer", name: "过户协议", fileName: "过户协议.pdf", type: "document", summary: "车辆/股权/房产过户协议。" }],
  will: [{ category: "will", name: "公证遗嘱", fileName: "公证遗嘱.pdf", type: "document", summary: "公证处出具的遗嘱公证书，效力最高。" }],
  marriage: [{ category: "marriage", name: "结婚证", fileName: "结婚证.pdf", type: "document", summary: "夫妻关系证明。" }],
  divorce: [{ category: "divorce", name: "离婚证/判决书", fileName: "离婚证.pdf", type: "document", summary: "离婚证明或法院判决书。" }],
  contract: [{ category: "contract", name: "合同原件", fileName: "合同.pdf", type: "document", summary: "各类书面合同原件。" }],
  bank_statement: [{ category: "bank_statement", name: "银行流水", fileName: "银行流水.pdf", type: "document", summary: "银行盖章流水，可用于主张工资、收入、转账。" }],
  medical: [
    { category: "medical", name: "住院病历", fileName: "住院病历.pdf", type: "document", summary: "医院住院病历，包含诊断、治疗、出院医嘱。" },
    { category: "medical", name: "医药发票", fileName: "医药费发票.pdf", type: "document", summary: "门诊/住院医药费发票原件。" },
  ],
  other: [{ category: "other", name: "其他材料", fileName: "材料.pdf", type: "document", summary: "其他与案件相关的文件。" }],
};

const CATEGORY_ORDER: DocCategory[] = [
  "id_front", "id_back", "business_license", "property",
  "marriage", "divorce", "bank_statement", "contract",
  "medical", "death_cert", "will", "transfer", "other",
];

const card = {
  background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)",
  border: "1px solid rgba(99,102,241,0.15)",
  borderRadius: "16px",
};

export default function UserDocsPage({ onPickForCase, caseId }: { onPickForCase?: (docId: string) => void; caseId?: string }) {
  const { getCurrentUser } = useAppStore();
  const user = getCurrentUser();
  const { getUserDocs, addUserDoc, removeUserDoc, verifyDoc, getIdentity, setIdentity, getUserDocById, linkDocToCase } = useCaseStore();
  const docs = user ? getUserDocs(user.id) : [];
  const identity = user ? getIdentity(user.id) : undefined;

  const [open, setOpen] = useState(false);
  const [tab, setTab] = useState<"verify" | "upload">("verify");
  const [reName, setReName] = useState("");
  const [reId, setReId] = useState("");
  const [filter, setFilter] = useState<"all" | "verified" | "pending">("all");

  const filteredDocs = docs.filter((d) =>
    filter === "all" ? true : filter === "verified" ? d.verified : !d.verified
  );

  const quickUpload = (cat: DocCategory) => {
    if (!user) return;
    const presets = PRESETS[cat];
    const pick = presets[Math.floor(Math.random() * presets.length)];
    const d = addUserDoc({
      userId: user.id,
      category: cat,
      name: pick.name,
      fileName: pick.fileName,
      type: pick.type,
      verified: false,
      summary: pick.summary + "（已上传，等待实名认证后即可用于案件）",
      info: pick.info,
    });
    setTimeout(() => {
      verifyDoc(d.id, pick.info);
    }, 600);
  };

  const doVerify = () => {
    if (!user) return;
    if (!reName || !reId) { alert("请输入真实姓名和身份证号"); return; }
    setIdentity(user.id, { realName: reName, idNumber: reId, verified: true });
    const idDocs = getUserDocs(user.id).filter((d) => d.category === "id_front" || d.category === "id_back");
    idDocs.forEach((d) => verifyDoc(d.id, d.info));
    alert("实名认证成功！你上传的身份证将自动被系统信任，所有案件都可直接使用。");
    setTab("upload");
  };

  const pickToCase = (docId: string) => {
    if (!caseId) return;
    linkDocToCase(docId, caseId);
    alert("已将材料关联到当前案件的证据列表，可直接使用，无需再次上传。");
  };

  return (
    <div className="p-6 space-y-5" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", sans-serif", minHeight: "100%" }}>
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl flex items-center justify-center" style={{ background: "linear-gradient(135deg,#6366f1,#8b5cf6)", boxShadow: "0 4px 14px rgba(99,102,241,0.3)" }}>
            <BookUp className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-white">我的材料库</h2>
            <p className="text-[11px] text-slate-400">一次上传，全案件复用，实名认证后自动信任</p>
          </div>
        </div>
        <button onClick={() => setOpen(true)}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 shadow-md">
          <Plus className="w-4 h-4" /> 上传新材料
        </button>
      </div>

      {!identity?.verified && (
        <div style={card} className="p-5">
          <div className="flex items-center gap-2 mb-3">
            <CreditCard className="w-4 h-4 text-amber-400" />
            <span className="text-xs font-semibold text-amber-300">你还没有实名认证</span>
          </div>
          <p className="text-[12px] text-slate-300 leading-relaxed mb-3">
            实名认证后，你上传的身份证、营业执照、房产证等证件会自动被系统信任，所有案件都可直接引用，不用重复上传。
          </p>
          <button onClick={() => { setOpen(true); setTab("verify"); }}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-400 hover:to-amber-500 shadow-md">
            <CheckCircle className="w-4 h-4" /> 立即实名认证
          </button>
        </div>
      )}

      <div className="flex items-center gap-2 flex-wrap">
        {(["all", "verified", "pending"] as const).map((k) => (
          <button key={k} onClick={() => setFilter(k)}
            className={`px-3 py-1.5 rounded-lg text-[11px] font-semibold transition-all ${filter === k ? "text-white shadow-sm" : "text-slate-400 bg-white/5 hover:bg-white/10"}`}
            style={filter === k ? { background: "linear-gradient(90deg,#6366f1,#8b5cf6)" } : {}}>
            {k === "all" ? "全部" : k === "verified" ? "已实名" : "待实名"}
            <span className="ml-1 opacity-70">
              ({k === "all" ? docs.length : k === "verified" ? docs.filter((d) => d.verified).length : docs.filter((d) => !d.verified).length})
            </span>
          </button>
        ))}
      </div>

      {filteredDocs.length === 0 ? (
        <div style={card} className="p-10 flex flex-col items-center justify-center text-center">
          <div className="w-14 h-14 rounded-2xl flex items-center justify-center mb-3" style={{ background: "rgba(99,102,241,0.1)" }}>
            <FileUp className="w-6 h-6 text-slate-500" />
          </div>
          <p className="text-slate-300 mb-2">还没有上传任何材料</p>
          <p className="text-[11px] text-slate-500 max-w-md mb-4">先上传身份证正反面、营业执照、房产证等，实名后一次上传，所有案件直接引用，不用重复传。</p>
          <button onClick={() => setOpen(true)}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600 shadow-md">
            <Plus className="w-4 h-4" /> 开始上传
          </button>
        </div>
      ) : (
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredDocs.map((d) => {
            const meta = DOC_CATEGORY_META[d.category];
            return (
              <div key={d.id} className="rounded-2xl p-4"
                style={{
                  background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)",
                  border: `1px solid ${d.verified ? "rgba(16,185,129,0.35)" : "rgba(99,102,241,0.15)"}`,
                }}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2.5">
                    <div className="w-10 h-10 rounded-xl flex items-center justify-center text-lg"
                      style={{ background: `${meta.color}22`, border: `1px solid ${meta.color}33` }}>
                      {meta.icon}
                    </div>
                    <div className="min-w-0">
                      <div className="text-[13px] font-bold text-white truncate">{d.name}</div>
                      <div className="text-[10px] text-slate-400 truncate">{d.fileName}</div>
                    </div>
                  </div>
                  {d.verified ? (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-bold text-emerald-300"
                      style={{ background: "rgba(16,185,129,0.15)" }}>
                      <CheckCircle className="w-3 h-3" /> 已实名
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-bold text-amber-300"
                      style={{ background: "rgba(245,158,11,0.15)" }}>
                      <XCircle className="w-3 h-3" /> 待实名
                    </span>
                  )}
                </div>
                {d.info && d.info.length > 0 && (
                  <div className="mt-3 grid grid-cols-2 gap-1.5">
                    {d.info.map((inf, i) => (
                      <div key={i} className="text-[10px] leading-relaxed rounded-md px-2 py-1"
                        style={{ background: "rgba(99,102,241,0.05)", border: "1px solid rgba(99,102,241,0.1)" }}>
                        <span className="text-slate-400">{inf.label}：</span>
                        <span className="text-slate-100 font-medium">{inf.value}</span>
                      </div>
                    ))}
                  </div>
                )}
                <div className="mt-3 flex items-center justify-between gap-2">
                  <span className="text-[10px] text-slate-500">{d.uploadedAt}</span>
                  <div className="flex items-center gap-1.5">
                    {caseId && (
                      <button onClick={() => pickToCase(d.id)} disabled={!d.verified}
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-[10px] font-semibold text-white"
                        style={d.verified ? { background: "linear-gradient(90deg,#10b981,#059669)" } : { background: "rgba(100,116,139,0.3)", color: "rgba(255,255,255,0.4)", cursor: "not-allowed" }}>
                        <Plus className="w-3 h-3" /> 用到此案
                      </button>
                    )}
                    <button onClick={() => { if (confirm(`删除材料 ${d.name} ?`)) removeUserDoc(d.id); }}
                      className="p-1.5 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-500/10 transition-colors"
                      title="删除">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setOpen(false)}>
          <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
          <div className="relative rounded-2xl w-full max-w-3xl max-h-[88vh] flex flex-col"
            style={{ background: "linear-gradient(180deg, #0a1430 0%, #070c1f 100%)", border: "1px solid rgba(99,102,241,0.25)", boxShadow: "0 20px 60px rgba(0,0,0,0.7)" }}
            onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between px-5 py-3" style={{ borderBottom: "1px solid rgba(99,102,241,0.15)" }}>
              <h3 className="font-bold text-white text-[15px]">
                {tab === "verify" ? "实名认证" : "上传材料到材料库"}
              </h3>
              <button onClick={() => setOpen(false)} className="w-8 h-8 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 flex items-center justify-center">x</button>
            </div>

            <div className="flex items-center gap-1 px-5 py-2" style={{ borderBottom: "1px solid rgba(99,102,241,0.1)" }}>
              <button onClick={() => setTab("verify")}
                className={`px-3 py-1 rounded-md text-xs font-semibold transition-all ${tab === "verify" ? "text-white" : "text-slate-400 hover:text-white/80"}`}
                style={tab === "verify" ? { background: "linear-gradient(90deg,#f59e0b,#d97706)" } : {}}>
                <CreditCard className="w-3.5 h-3.5 inline mr-1 -mt-0.5" /> 实名认证
              </button>
              <button onClick={() => setTab("upload")}
                className={`px-3 py-1 rounded-md text-xs font-semibold transition-all ${tab === "upload" ? "text-white" : "text-slate-400 hover:text-white/80"}`}
                style={tab === "upload" ? { background: "linear-gradient(90deg,#6366f1,#8b5cf6)" } : {}}>
                <FileUp className="w-3.5 h-3.5 inline mr-1 -mt-0.5" /> 上传材料
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4">
              {tab === "verify" ? (
                <div className="space-y-3">
                  <p className="text-[12px] text-slate-300 leading-relaxed">
                    实名认证一次完成。实名认证后，你所有上传的证件会被系统信任，全案件自动可用。
                    输入的身份证号会自动脱敏存储，仅留后 4 位供核对。
                  </p>
                  <div>
                    <label className="text-[11px] font-semibold text-slate-400 uppercase tracking-widest">真实姓名</label>
                    <input value={reName} onChange={(e) => setReName(e.target.value)} placeholder="身份证上的姓名"
                      className="mt-1 w-full px-3 py-2.5 rounded-xl text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-amber-500/30"
                      style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.2)" }} />
                  </div>
                  <div>
                    <label className="text-[11px] font-semibold text-slate-400 uppercase tracking-widest">身份证号</label>
                    <input value={reId} onChange={(e) => setReId(e.target.value)} placeholder="18 位身份证号码" maxLength={18}
                      className="mt-1 w-full px-3 py-2.5 rounded-xl text-sm text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-amber-500/30"
                      style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.2)" }} />
                  </div>
                  <button onClick={doVerify}
                    className="w-full py-3 rounded-xl font-bold text-white bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-400 hover:to-amber-500 shadow-md">
                    <CheckCircle className="w-4 h-4 inline mr-1 -mt-0.5" />
                    提交实名认证（仅演示，不联网）
                  </button>
                  {identity?.verified && (
                    <p className="text-[11px] text-emerald-300 text-center mt-1">当前已是实名状态</p>
                  )}
                </div>
              ) : (
                <div>
                  <p className="text-[12px] text-slate-300 leading-relaxed mb-3">
                    选一种材料类型上传。模拟上传，真实版本支持拍照 / 相册 / 文件选择 + OCR 识别。
                  </p>
                  <div className="grid md:grid-cols-3 gap-2">
                    {CATEGORY_ORDER.map((cat) => {
                      const meta = DOC_CATEGORY_META[cat];
                      return (
                        <button key={cat} onClick={() => quickUpload(cat)}
                          className="flex flex-col items-start gap-1 px-3 py-3 rounded-xl text-left transition-all hover:-translate-y-0.5"
                          style={{ background: "rgba(99,102,241,0.06)", border: `1px solid ${meta.color}22` }}>
                          <div className="flex items-center gap-2">
                            <span className="text-lg">{meta.icon}</span>
                            <div className="text-[12px] font-semibold text-white">{meta.label}</div>
                          </div>
                          <div className="text-[10px] text-slate-400">{meta.hint}</div>
                          <div className="flex items-center gap-1 text-[10px]" style={{ color: meta.color }}>
                            <Camera className="w-3 h-3" /> 模拟上传
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
