import { useRef, useState } from "react";
import { CheckCircle, Database, FileSearch, FileText, FileUp, Headphones, Image, Plus, RefreshCw, Trash2, Video } from "lucide-react";
import { useCaseStore, DOC_CATEGORY_META, DocCategory, EvidenceItem } from "../../store/caseStore";
import { useAppStore } from "../../store/appStore";

type Filter = EvidenceItem["type"] | "all";

const typeLabel: Record<EvidenceItem["type"], string> = {
  image: "图片",
  document: "文档",
  audio: "录音",
  video: "录像",
};

const typeColors: Record<EvidenceItem["type"], string> = {
  image: "from-emerald-400 to-teal-500",
  document: "from-amber-400 to-orange-500",
  audio: "from-sky-400 to-blue-500",
  video: "from-rose-400 to-red-500",
};

function typeIcon(t: EvidenceItem["type"]) {
  if (t === "image") return <Image className="w-3.5 h-3.5" />;
  if (t === "audio") return <Headphones className="w-3.5 h-3.5" />;
  if (t === "video") return <Video className="w-3.5 h-3.5" />;
  return <FileText className="w-3.5 h-3.5" />;
}

function buildEvidenceFromFile(file: File): Omit<EvidenceItem, "id" | "caseId" | "uploadedAt"> {
  const ext = file.name.toLowerCase();
  const type: EvidenceItem["type"] = ext.match(/\.(jpg|jpeg|png|gif|webp)$/) ? "image" : ext.match(/\.(mp3|wav|m4a)$/) ? "audio" : ext.match(/\.(mp4|mov|avi)$/) ? "video" : "document";
  return {
    name: file.name,
    type,
    aiSummary: `用户上传的${typeLabel[type]}材料，文件名：${file.name}。`,
    aiIssues: ["请核对原件真实性、来源合法性和与本案争议焦点的关联性"],
  };
}

export default function EvidenceTab({ caseId }: { caseId: string }) {
  const getEvidences = useCaseStore((s) => s.getEvidences);
  const addEvidence = useCaseStore((s) => s.addEvidence);
  const removeEvidence = useCaseStore((s) => s.removeEvidence);
  const getUserDocs = useCaseStore((s) => s.getUserDocs);
  const getUserDocById = useCaseStore((s) => s.getUserDocById);
  const linkDocToCase = useCaseStore((s) => s.linkDocToCase);
  const currentUser = useAppStore((s) => s.getCurrentUser());

  const evidence = getEvidences(caseId);
  const library = currentUser ? getUserDocs(currentUser.id).filter((d) => d.verified) : [];

  const [filter, setFilter] = useState<Filter>("all");
  const [docOpen, setDocOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const onFilesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    Array.from(e.target.files || []).forEach((file) => addEvidence(caseId, buildEvidenceFromFile(file)));
    e.target.value = "";
  };

  const addQuick = (type: EvidenceItem["type"]) => {
    addEvidence(caseId, {
      name: `${typeLabel[type]}证据 ${evidence.length + 1}`,
      type,
      aiSummary: `新增${typeLabel[type]}证据，待补充具体证明内容。`,
      aiIssues: ["请补充证明目的、取得来源和形成时间"],
    });
  };

  const pickFromLibrary = (docId: string) => {
    const doc = getUserDocById(docId);
    if (!doc) return;
    linkDocToCase(docId, caseId);
    setDocOpen(false);
  };

  const filters: { key: Filter; label: string }[] = [
    { key: "all", label: "全部" },
    { key: "document", label: "文档" },
    { key: "image", label: "图片" },
    { key: "audio", label: "录音" },
    { key: "video", label: "录像" },
  ];
  const filtered = filter === "all" ? evidence : evidence.filter((e) => e.type === filter);

  return (
    <div className="p-6 space-y-5" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <input type="file" ref={fileInputRef} onChange={onFilesChange} multiple accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png,.mp3,.mp4,.wav,.mov" hidden />

      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-lg font-bold text-white">证据管理</h2>
          <p className="text-[11px] text-slate-400 mt-1">支持图片 / 文档 / 录音 / 录像，按证据类型整理当前案件材料。</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <button onClick={() => setDocOpen(true)} disabled={library.length === 0} className="inline-flex items-center gap-2 px-3.5 py-2 rounded-xl text-sm font-semibold transition-all shadow-md disabled:opacity-40 disabled:cursor-not-allowed" style={{ background: "linear-gradient(135deg,#f59e0b,#eab308)", color: "#1c1917" }}>
            <Database className="w-4 h-4" /> 从材料库引用
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600 shadow-md">
            <FileUp className="w-3.5 h-3.5" /> 上传
          </button>
          <button onClick={() => addQuick("document")} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-amber-500 to-orange-600 shadow-md">
            <FileText className="w-3.5 h-3.5" /> 文档
          </button>
          <button onClick={() => addQuick("image")} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-emerald-500 to-teal-600 shadow-md">
            <Image className="w-3.5 h-3.5" /> 图片
          </button>
          <button onClick={() => addQuick("audio")} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-sky-500 to-blue-600 shadow-md">
            <Headphones className="w-3.5 h-3.5" /> 录音
          </button>
          <button onClick={() => addQuick("video")} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-rose-500 to-red-600 shadow-md">
            <Video className="w-3.5 h-3.5" /> 录像
          </button>
        </div>
      </div>

      {library.length === 0 && (
        <div className="rounded-xl p-4 flex items-center gap-3" style={{ background: "rgba(245,158,11,0.08)", border: "1px solid rgba(245,158,11,0.25)" }}>
          <Database className="w-5 h-5 text-amber-300 shrink-0" />
          <p className="text-[12px] text-amber-200/90 leading-relaxed">你还没有「已实名认证」的材料。请先到左侧「我的材料库」上传并完成实名，之后可在此一键引用。</p>
        </div>
      )}

      <div className="flex items-center gap-2 flex-wrap">
        {filters.map((f) => (
          <button key={f.key} onClick={() => setFilter(f.key)} className={`px-3 py-1.5 rounded-lg text-[11px] font-semibold transition-all ${filter === f.key ? "text-white bg-indigo-600" : "text-slate-400 bg-white/5 hover:bg-white/10"}`}>
            {f.label}<span className="ml-1 opacity-70">({f.key === "all" ? evidence.length : evidence.filter((e) => e.type === f.key).length})</span>
          </button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <div className="rounded-2xl p-10 flex flex-col items-center justify-center text-center" style={{ background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(99,102,241,0.15)" }}>
          <FileSearch className="w-8 h-8 text-slate-500 mb-3" />
          <p className="text-slate-300">还没有证据</p>
          <p className="text-[11px] text-slate-500 mt-2 max-w-md">点击上传、快捷新增或从材料库引用，开始整理此案证据链。</p>
        </div>
      ) : (
        <div className="grid lg:grid-cols-2 gap-4">
          {filtered.map((e, idx) => (
            <div key={e.id} className="rounded-2xl p-4 transition-all" style={{ background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(99,102,241,0.15)" }}>
              <div className="flex items-start justify-between gap-3 mb-3">
                <div className="flex items-start gap-2.5 min-w-0">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white bg-gradient-to-br ${typeColors[e.type]}`}>{typeIcon(e.type)}</div>
                  <div className="min-w-0">
                    <div className="text-[13px] font-bold text-white truncate max-w-[260px]">{e.name}</div>
                    <div className="text-[10px] text-slate-400 flex items-center gap-1.5 mt-0.5"><span>{typeLabel[e.type]}</span><span>#{idx + 1}</span><span>{e.uploadedAt}</span></div>
                  </div>
                </div>
                <button onClick={() => { if (confirm(`删除「${e.name}」？`)) removeEvidence(e.id); }} className="p-1.5 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-500/10 transition-colors" title="删除">
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>

              {e.aiSummary && <div className="rounded-xl px-3 py-2 mb-2" style={{ background: "rgba(99,102,241,0.08)", border: "1px solid rgba(99,102,241,0.15)" }}><div className="flex items-center gap-1.5 text-[10px] font-bold text-indigo-300 mb-1"><FileSearch className="w-3 h-3" /> AI 摘要</div><p className="text-[12px] text-slate-200 leading-relaxed">{e.aiSummary}</p></div>}

              {e.aiIssues.length > 0 && (
                <div className="rounded-xl px-3 py-2" style={{ background: "rgba(244,63,94,0.06)", border: "1px solid rgba(244,63,94,0.15)" }}>
                  <div className="flex items-center gap-1.5 text-[10px] font-bold text-rose-300 mb-1.5"><RefreshCw className="w-3 h-3" /> AI 风险问题</div>
                  <ul className="space-y-1.5">{e.aiIssues.map((issue, ii) => <li key={ii} className="text-[11.5px] text-slate-200/90 flex items-start gap-1.5 leading-relaxed"><span className="w-1 h-1 rounded-full bg-rose-400 mt-1.5 shrink-0" /><span>{issue}</span></li>)}</ul>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {docOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setDocOpen(false)}>
          <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
          <div className="relative rounded-2xl w-full max-w-4xl max-h-[86vh] flex flex-col" style={{ background: "linear-gradient(180deg, #0a1430 0%, #070c1f 100%)", border: "1px solid rgba(99,102,241,0.25)", boxShadow: "0 20px 60px rgba(0,0,0,0.7)" }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between px-5 py-3" style={{ borderBottom: "1px solid rgba(99,102,241,0.15)" }}>
              <div className="flex items-center gap-2"><Database className="w-4 h-4 text-amber-300" /><h3 className="font-bold text-white text-[15px]">从材料库引用到此案</h3></div>
              <button onClick={() => setDocOpen(false)} className="w-8 h-8 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 flex items-center justify-center">×</button>
            </div>
            <div className="flex-1 overflow-y-auto px-5 py-4">
              {library.length === 0 ? <div className="p-10 text-center text-slate-400">暂无已实名认证材料</div> : (
                <div className="grid md:grid-cols-2 gap-3">
                  {library.map((d) => {
                    const meta = DOC_CATEGORY_META[d.category as DocCategory];
                    return (
                      <div key={d.id} className="rounded-2xl p-4" style={{ background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(16,185,129,0.35)" }}>
                        <div className="flex items-center gap-2.5"><div className="w-10 h-10 rounded-xl flex items-center justify-center text-lg" style={{ background: `${meta.color}22`, border: `1px solid ${meta.color}33` }}>{meta.icon}</div><div className="min-w-0 flex-1"><div className="text-[13px] font-bold text-white truncate">{d.name}</div><div className="text-[10px] text-emerald-300 flex items-center gap-1"><CheckCircle className="w-3 h-3" /> 已实名 · {d.uploadedAt}</div></div></div>
                        <p className="mt-2 text-[11.5px] text-slate-300 leading-relaxed">{d.summary}</p>
                        <button onClick={() => pickFromLibrary(d.id)} className="mt-3 w-full py-2 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-amber-500 to-amber-600"><Plus className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />引用到本案证据</button>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
