export function searchLaws(keyword: string): LawItem[] {
  if (!keyword.trim()) return lawLibrary;
  const k = keyword.trim().toLowerCase();
  return lawLibrary.filter(
    (l) =>
      l.title.toLowerCase().includes(k) ||
      l.fullName.toLowerCase().includes(k) ||
      l.summary.toLowerCase().includes(k) ||
      l.content.toLowerCase().includes(k) ||
      l.article.toLowerCase().includes(k)
  );
}
