import { ArrowRight, CheckCircle, Upload, Calendar, FileText, Gavel, AlertTriangle, PlayCircle } from "lucide-react";
import { useCaseStore } from "../../store/caseStore";
import { analyzeCase } from "../../lib/aiSimulator";

interface Props { caseId: string; onSelectTab: (t: string) => void }

export default function OverviewTab({ caseId, onSelectTab }: Props) {
  const { getCase, getEvidences, setAnalysis, updateCase, getAnalysis } = useCaseStore();
  const c = getCase(caseId);
  const evidences = getEvidences(caseId);
  const analysis = getAnalysis(caseId);

  if (!c) return <div className="p-8 text-center text-slate-400">案件不存在</div>;

  const running = analysis === undefined && c.status === "analyzing";

  const runAnalysis = async () => {
    updateCase(caseId, { status: "analyzing", progress: Math.max(c.progress, 20) });
    const a = await analyzeCase(c, evidences);
    setAnalysis(caseId, a);
    onSelectTab("analysis");
  };

  const timeline = [
    { label: "创建案件", done: c.progress >= 10, date: c.createdAt },
    { label: "上传证据", done: evidences.length > 0, date: evidences.length ? evidences[evidences.length - 1].uploadedAt : "" },
    { label: "AI 分析", done: !!analysis, date: analysis?.updatedAt || "" },
    { label: "辩护策略", done: c.progress >= 85, date: c.progress >= 85 ? c.updatedAt : "" },
    { label: "结案归档", done: c.status === "closed", date: c.status === "closed" ? c.updatedAt : "" },
  ];

  const cardStyle = {
    background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)",
    border: "1px solid rgba(99,102,241,0.15)",
    borderRadius: "16px",
  };

  return (
    <div className="p-6 space-y-5" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <div style={cardStyle}>
        <div className="flex items-start justify-between gap-4 flex-wrap p-5">
          <div>
            <h2 className="text-xl font-bold text-white mb-1">{c.title}</h2>
            <div className="flex items-center gap-3 text-xs text-slate-400 flex-wrap">
              <span className="px-2 py-0.5 rounded-md font-medium"
                style={{ background: "linear-gradient(135deg,#6366f1,#8b5cf6)", color: "white" }}>{c.type}</span>
              <span>·</span>
              <span className="text-slate-300">{c.parties || "未填写当事人"}</span>
              <span>·</span>
              <span>创建 {c.createdAt}</span>
              <span>·</span>
              <span>更新 {c.updatedAt}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <div className="text-right">
              <div className="text-xs text-slate-400">完成度</div>
              <div className="text-lg font-bold text-white">{c.progress}%</div>
            </div>
            <div className="w-20 h-20">
              <svg viewBox="0 0 36 36" className="w-full h-full -rotate-90">
                <circle cx="18" cy="18" r="15.9" fill="none" stroke="#1e2a52" strokeWidth="3" />
                <circle cx="18" cy="18" r="15.9" fill="none" stroke={c.progress === 100 ? "#10b981" : "#6366f1"} strokeWidth="3" strokeDasharray={`${(c.progress / 100) * 100} 100`} strokeLinecap="round" />
              </svg>
            </div>
          </div>
        </div>

        {c.facts && (
          <div className="mx-5 pt-4" style={{ borderTop: "1px solid rgba(99,102,241,0.15)" }}>
            <div className="text-xs font-semibold text-slate-300 mb-2">案情描述</div>
            <p className="text-sm text-slate-200 leading-relaxed whitespace-pre-wrap">{c.facts}</p>
          </div>
        )}

        <div className="p-5 pt-4 flex gap-3 flex-wrap">
          <button
            onClick={runAnalysis}
            disabled={running}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 disabled:opacity-60 transition-all shadow-md text-sm"
          >
            {running ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                AI 分析中...
              </>
            ) : (
              <>
                <PlayCircle className="w-4 h-4" />
                {analysis ? "重新运行 AI 分析" : "运行 AI 分析"}
              </>
            )}
          </button>
          <button
            onClick={() => onSelectTab("evidence")}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-medium text-slate-200 bg-white/5 hover:bg-white/10 transition-all text-sm"
            style={{ border: "1px solid rgba(99,102,241,0.2)" }}
          >
            <Upload className="w-4 h-4" />
            管理证据（{evidences.length}）
          </button>
          {analysis && (
            <button
              onClick={() => onSelectTab("defense")}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-medium text-white bg-gradient-to-r from-amber-600 to-amber-500 hover:from-amber-500 hover:to-amber-400 transition-all text-sm shadow-md"
            >
              <Gavel className="w-4 h-4" />
              进入辩护中心
            </button>
          )}
        </div>
      </div>

      <div style={cardStyle} className="p-5">
        <div className="text-xs font-semibold text-slate-300 mb-4">案件时间线</div>
        <div className="relative pl-6">
          <div className="absolute left-[6px] top-2 bottom-2 w-[2px]" style={{ background: "linear-gradient(180deg,#6366f1,#1e2a52)" }} />
          {timeline.map((t, i) => (
            <div key={i} className="relative flex items-center gap-4 mb-5 last:mb-0">
              <div className={`absolute -left-6 top-1 w-3 h-3 rounded-full border-2 ${
                t.done ? "bg-emerald-500 border-emerald-500" : "bg-transparent border-slate-500"
              }`} />
              <div className="flex items-center gap-2">
                {t.done ? (
                  <CheckCircle className="w-4 h-4 text-emerald-400" />
                ) : (
                  <AlertTriangle className="w-4 h-4 text-slate-500" />
                )}
                <span className={`text-sm font-medium ${t.done ? "text-white" : "text-slate-400"}`}>{t.label}</span>
              </div>
              {t.date && (
                <span className="text-xs text-slate-500 flex items-center gap-1">
                  <Calendar className="w-3 h-3" /> {t.date}
                </span>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
