import { useState } from "react";
import { RotateCcw, AlertTriangle, Scale, Gavel, CheckCircle, Sparkles, ArrowRight } from "lucide-react";
import { useCaseStore } from "../../store/caseStore";
import { analyzeCase } from "../../lib/aiSimulator";

interface Props { caseId: string; onSelectTab?: (t: string) => void }

const STEPS = [
  { text: "读取案件事实与证据", ms: 180 },
  { text: "识别争议焦点与法律关系", ms: 220 },
  { text: "匹配适用法条与相似判例", ms: 250 },
  { text: "评估风险点与胜诉概率", ms: 220 },
  { text: "生成下一步行动建议", ms: 160 },
];

function WinRing({ p }: { p: number }) {
  const color = p >= 70 ? "#10b981" : p >= 50 ? "#6366f1" : p >= 30 ? "#f59e0b" : "#ef4444";
  return (
    <div className="relative inline-flex items-center justify-center">
      <svg viewBox="0 0 120 120" className="w-36 h-36 -rotate-90">
        <circle cx="60" cy="60" r="50" fill="none" stroke="#1e2a52" strokeWidth="12" />
        <circle cx="60" cy="60" r="50" fill="none" stroke={color} strokeWidth="12" strokeDasharray={`${(p / 100) * 314} 314`} strokeLinecap="round" />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <div className="text-3xl font-bold" style={{ color }}>{p}</div>
        <div className="text-[10px] text-slate-400 font-semibold">胜诉概率</div>
      </div>
    </div>
  );
}

export default function AnalysisTab({ caseId, onSelectTab }: Props) {
  const { getCase, getAnalysis, setAnalysis, getEvidences, updateCase } = useCaseStore();
  const c = getCase(caseId);
  const analysis = getAnalysis(caseId);
  const evidences = getEvidences(caseId);

  const [loading, setLoading] = useState(false);
  const [stepIdx, setStepIdx] = useState(0);
  const [stepText, setStepText] = useState("");

  if (!c) return <div className="p-8 text-center text-slate-400">案件不存在</div>;

  const run = async () => {
    setLoading(true);
    setStepIdx(0);
    setStepText(STEPS[0].text);
    updateCase(caseId, { status: "analyzing", progress: Math.max(c.progress, 20) });

    for (let i = 0; i < STEPS.length; i++) {
      setStepIdx(i);
      setStepText(STEPS[i].text);
      await new Promise((r) => setTimeout(r, STEPS[i].ms));
    }

    const a = await analyzeCase(c, evidences);
    setAnalysis(caseId, a);
    setLoading(false);
  };

  const cardStyle = {
    background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)",
    border: "1px solid rgba(99,102,241,0.15)",
    borderRadius: "16px",
  };

  if (loading) {
    return (
      <div className="p-10 flex flex-col items-center justify-center text-center" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif", minHeight: "100%" }}>
        <div className="relative w-24 h-24 mb-5">
          <div className="absolute inset-0 rounded-full" style={{ border: "3px solid rgba(99,102,241,0.15)" }} />
          <div className="absolute inset-0 rounded-full animate-spin" style={{ border: "3px solid transparent", borderTopColor: "#6366f1", borderRightColor: "#8b5cf6" }} />
          <div className="absolute inset-0 flex items-center justify-center">
            <Sparkles className="w-6 h-6 text-indigo-300" />
          </div>
        </div>
        <p className="text-white font-bold text-[15px] mb-1">AI 正在分析你的案件...</p>
        <p className="text-slate-400 text-[12px] mb-4">{stepText}</p>
        <div className="flex items-center gap-2 flex-wrap justify-center max-w-md">
          {STEPS.map((s, i) => (
            <div key={i} className="flex items-center gap-1.5">
              <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold ${
                i < stepIdx ? "bg-emerald-500/20 text-emerald-300"
                  : i === stepIdx ? "bg-gradient-to-br from-indigo-500 to-violet-500 text-white"
                  : "bg-white/5 text-slate-500"
              }`}>
                {i < stepIdx ? "✓" : i + 1}
              </div>
              <span className={`text-[10px] ${i <= stepIdx ? "text-slate-200" : "text-slate-500"}`}>{s.text.slice(0, 8)}</span>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (!analysis) {
    return (
      <div className="p-10 flex flex-col items-center justify-center text-center" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif", minHeight: "100%" }}>
        <div className="w-20 h-20 rounded-2xl flex items-center justify-center mb-4" style={{ background: "rgba(99,102,241,0.1)" }}>
          <Scale className="w-8 h-8 text-slate-500" />
        </div>
        <p className="text-slate-300 mb-1">还没有 AI 分析结果</p>
        <p className="text-xs text-slate-500 mb-4">点一下右边按钮，约 1-2 秒就能出结果</p>
        <button
          onClick={run}
          className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 transition-all shadow-md"
        >
          <Scale className="w-4 h-4" />
          运行 AI 分析
        </button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-5" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <div style={cardStyle} className="p-5">
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div>
            <div className="text-xs font-semibold text-slate-400">AI 综合评估</div>
            <h3 className="text-lg font-bold text-white mt-1">{c.title}</h3>
            <p className="text-xs text-slate-400 mt-0.5">分析于 {analysis.updatedAt}</p>
          </div>
          <div className="flex items-center gap-4">
            <WinRing p={analysis.winProbability} />
            <div className="max-w-[280px]">
              <p className="text-xs text-slate-300 leading-relaxed">{analysis.winProbabilityReason}</p>
            </div>
          </div>
        </div>
      </div>

      <div style={cardStyle} className="p-5">
        <div className="flex items-center justify-between mb-3">
          <div className="text-xs font-semibold text-slate-300">风险点清单</div>
          <button onClick={run} className="inline-flex items-center gap-1 px-3 py-1 rounded-lg text-xs font-medium text-slate-200 bg-white/5 hover:bg-white/10 transition-colors">
            <RotateCcw className="w-3 h-3" />
            重新分析
          </button>
        </div>
        <div className="space-y-2">
          {analysis.risks.map((r, i) => {
            const color = r.level === "high" ? { bg: "rgba(239,68,68,0.12)", border: "rgba(239,68,68,0.25)", text: "#fca5a5" } : r.level === "mid" ? { bg: "rgba(245,158,11,0.12)", border: "rgba(245,158,11,0.25)", text: "#fcd34d" } : { bg: "rgba(16,185,129,0.12)", border: "rgba(16,185,129,0.25)", text: "#6ee7b7" };
            const Icon = AlertTriangle;
            return (
              <div key={i} className="flex items-start gap-3 px-3 py-2.5 rounded-xl border" style={{ background: color.bg, borderColor: color.border }}>
                <Icon className="w-4 h-4 mt-0.5 shrink-0" style={{ color: color.text }} />
                <p className="text-[13px] leading-relaxed text-slate-100">{r.text}</p>
              </div>
            );
          })}
        </div>
      </div>

      <div style={cardStyle} className="p-5">
        <div className="text-xs font-semibold text-slate-300 mb-3">适用法条（{analysis.applicableLaws.length} 条）</div>
        <div className="grid gap-2">
          {analysis.applicableLaws.map((l, i) => (
            <div key={i} className="rounded-xl p-3 transition-colors"
              style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.12)" }}>
              <div className="flex items-start justify-between gap-2 flex-wrap">
                <div className="min-w-0">
                  <div className="text-[13px] font-bold text-white">{l.law}</div>
                  <div className="text-[11px] text-slate-400 mt-0.5">{l.summary}</div>
                </div>
                <span className="px-2 py-0.5 rounded-md text-[10px] font-medium shrink-0"
                  style={{ background: "rgba(99,102,241,0.2)", color: "#a5b4fc" }}>适用</span>
              </div>
              <div className="text-[11px] text-slate-300 mt-2 leading-relaxed">
                <span className="text-slate-500">为什么适用：</span>{l.reason}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={cardStyle} className="p-5">
        <div className="text-xs font-semibold text-slate-300 mb-3">相似案例</div>
        <div className="space-y-2">
          {analysis.similarCases.map((s, i) => (
            <div key={i} className="rounded-xl p-3"
              style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.12)" }}>
              <div className="text-[13px] font-bold text-white mb-0.5">{s.title}</div>
              <div className="text-[11px] text-slate-400">{s.court} · {s.year} · {s.caseNo}</div>
              <div className="mt-1.5 flex items-center gap-2 flex-wrap">
                <span className={`px-2 py-0.5 rounded-md text-[10px] font-semibold ${
                  s.result.includes("胜诉") ? "bg-emerald-500/20 text-emerald-300" : "bg-amber-500/20 text-amber-300"
                }`}>
                  {s.result}
                </span>
                {s.amount && <span className="text-[11px] text-slate-400">{s.amount}</span>}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="rounded-2xl p-5"
        style={{ background: "linear-gradient(135deg, rgba(99,102,241,0.15) 0%, rgba(139,92,246,0.12) 100%)", border: "1px solid rgba(99,102,241,0.25)" }}>
        <div className="flex items-center gap-2 mb-3">
          <CheckCircle className="w-4 h-4 text-indigo-300" />
          <div className="text-xs font-semibold text-indigo-200">AI 建议下一步</div>
        </div>
        <ul className="space-y-2">
          {analysis.recommendations.map((r, i) => (
            <li key={i} className="flex items-start gap-2 text-[13px] text-slate-100 leading-relaxed">
              <span className="w-5 h-5 rounded-full bg-indigo-500 text-white text-[10px] flex items-center justify-center shrink-0 mt-0.5 font-bold">{i + 1}</span>
              <span>{r}</span>
            </li>
          ))}
        </ul>
        {onSelectTab && (
          <div className="mt-4 flex gap-2 flex-wrap">
            <button onClick={() => onSelectTab("defense")} className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-amber-600 to-amber-500 hover:from-amber-500 hover:to-amber-400 transition-all shadow-md">
              <Gavel className="w-4 h-4" />
              下一步：辩护策略
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
            <button onClick={() => onSelectTab("evidence")} className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium text-slate-100 bg-white/5 hover:bg-white/10 transition-all"
              style={{ border: "1px solid rgba(99,102,241,0.2)" }}>
              整理/补充证据
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
