import { useMemo, useState } from "react";
import { AlertTriangle, BookOpen, CheckCircle, FileText, Gavel, MessageSquare, Scale, Search, ShieldAlert, Sparkles, Users } from "lucide-react";
import { Case, useCaseStore } from "../store/caseStore";
import { useAppStore } from "../store/appStore";

type GuideStep = {
  title: string;
  desc: string;
  done: boolean;
  current: boolean;
  actions: string[];
};

type GuidePack = {
  materials: string[];
  departments: string[];
  stamped: string[];
  speakAllowed: string[];
  speakAvoid: string[];
};

function statusLabel(status: string) {
  switch (status) {
    case "draft": return "草稿";
    case "analyzing": return "AI 分析中";
    case "ready": return "准备处理";
    case "defending": return "辩护/应对中";
    case "closed": return "已结案";
    default: return status;
  }
}

function caseGuidePack(c?: Case): GuidePack {
  const type = `${c?.type || ""}${c?.title || ""}${c?.facts || ""}`;
  if (/劳动|工资|辞退|解除|工伤|社保|仲裁/.test(type)) {
    return {
      materials: ["劳动合同、入职登记表、岗位说明或任命文件", "工资银行流水、工资条、奖金/绩效发放记录", "社保缴纳记录、个税记录、考勤记录、请假记录", "解除/辞退通知、聊天记录、录音、邮件、会议纪要", "工牌、工服、工作群、OA 截图等能证明劳动关系的材料"],
      departments: ["劳动人事争议仲裁委员会：提交仲裁申请", "人社局/劳动监察：投诉欠薪、违法用工线索", "社保中心：打印社保缴费记录", "银行：打印并盖章工资流水", "税务 App/办税大厅：取得个税申报记录"],
      stamped: ["银行流水建议加盖银行业务章", "社保缴费证明建议下载官方电子章版本", "仲裁申请书、证据目录、证据复印件按被申请人人数准备副本"],
      speakAllowed: ["我实际工作的时间、岗位、工资构成是……", "公司如何通知解除、何时通知、是否给书面材料", "我有哪些原始证据，哪些还需要向银行/社保部门补充"],
      speakAvoid: ["不要说‘没有证据也可以找人补一个’", "不要夸大工资、工龄或加班事实", "不要在无依据时承认自愿离职或主动放弃补偿"],
    };
  }
  if (/交通|事故|车祸|保险|交警|伤残|医疗/.test(type)) {
    return {
      materials: ["道路交通事故认定书", "门诊/住院病历、诊断证明、出院小结", "医疗费发票、费用清单、用药清单", "误工证明、收入证明、银行流水或纳税记录", "护理费、营养费、交通费、伤残鉴定、保险信息"],
      departments: ["交警部门：取得事故认定书、调解记录", "医院：补齐病历、诊断证明、发票和清单", "司法鉴定机构：伤残等级、三期鉴定", "保险公司：查询交强险/商业险理赔信息", "人民法院：协商不成时起诉索赔"],
      stamped: ["医疗票据保留原件", "误工证明建议单位盖章并配合工资流水", "鉴定意见书需由有资质机构出具"],
      speakAllowed: ["事故发生的时间、地点、行驶路线和交警认定情况", "实际治疗过程、误工期限、护理情况", "已经支付和仍未赔付的具体金额"],
      speakAvoid: ["不要随意承认自己有责任，责任以事故认定书为基础", "不要隐瞒既往伤病或重复报销情况", "不要口头同意一次性低额了结后又无证据反悔"],
    };
  }
  if (/房屋|买卖|开发商|合同|定金|违约|退款|租赁/.test(type)) {
    return {
      materials: ["合同原件及补充协议、附件、签收单", "付款凭证、转账记录、收据、发票", "催告函、解除通知、对方回复记录", "交付、验收、质量问题、逾期违约证据", "主体信息：对方营业执照、身份信息、房屋/项目资料"],
      departments: ["不动产登记中心：查询房屋权属或备案情况", "住建部门/房管部门：查询项目、网签、交付信息", "市场监管部门：查询企业登记信息", "公证处/邮政 EMS：固定送达证据", "人民法院或仲裁机构：按合同约定选择争议解决渠道"],
      stamped: ["银行流水、付款凭证建议取得官方盖章或电子回单", "企业主体信息可打印国家企业信用信息公示系统页面", "催告函建议用 EMS 并保存回执"],
      speakAllowed: ["合同约定是什么、对方实际履行到哪一步", "我何时付款、付款金额、对方何时违约", "我已经做过哪些催告或协商"],
      speakAvoid: ["不要随意承认自己也违约或放弃权利", "不要无证据指控对方诈骗，先围绕违约事实表达", "不要把口头承诺当成确定事实，需说明来源和证据"],
    };
  }
  if (/消费|购物|商家|平台|欺诈|退款|商品/.test(type)) {
    return {
      materials: ["订单截图、支付凭证、发票或收据", "商品宣传页面、直播/广告截图", "实物照片、开箱视频、检测报告", "与商家、平台客服的完整沟通记录", "退货物流、签收、拒收、售后处理记录"],
      departments: ["电商平台客服/争议处理通道", "12315 平台、市场监督管理部门", "消费者协会", "鉴定/检测机构：固定商品质量问题", "人民法院：小额或网络购物合同纠纷"],
      stamped: ["检测报告需确认机构资质", "物流记录建议下载官方页面或申请证明", "重要网页证据可做可信时间戳或公证"],
      speakAllowed: ["商家宣传了什么，实际收到的商品是什么", "我何时付款、何时发现问题、如何联系商家", "我的诉求是退款、赔偿、退一赔三或修理更换"],
      speakAvoid: ["不要故意损坏商品后主张质量问题", "不要扩大不存在的损失", "不要威胁、辱骂商家，沟通记录会成为证据"],
    };
  }
  return {
    materials: ["身份证明、主体资格材料", "合同、聊天记录、录音、照片、视频、付款凭证", "时间线说明：何时发生、谁参与、做了什么", "对方身份信息、联系方式、地址或企业登记信息", "损失计算依据、票据、发票、银行流水"],
    departments: ["公安/派出所：涉及人身、财产安全或违法线索", "市场监管/住建/人社等主管部门：按案由投诉或查询", "银行、医院、学校、单位：补充证明材料", "公证处/可信时间戳平台：固定关键证据", "人民法院/仲裁机构：正式启动争议解决"],
    stamped: ["银行流水、收入证明、单位证明尽量盖章", "电子证据保留原始载体和完整截图", "提交材料按证据目录编号并准备副本"],
    speakAllowed: ["只陈述自己亲历或有证据支持的事实", "不确定的地方可以说‘我需要核实’", "明确自己的诉求、依据和证据来源"],
    speakAvoid: ["不要编造、补做、篡改证据", "不要指导证人说假话或统一口径", "不要承诺、威胁或私下签署不理解的放弃权利文件"],
  };
}

function buildGuideSteps(c: Case | undefined, evidenceCount: number, hasAnalysis: boolean, hasDefense: boolean): GuideStep[] {
  const hasFacts = !!c?.facts?.trim();
  const hasEvidence = evidenceCount > 0;
  const closed = c?.status === "closed";
  const items = [
    {
      title: "1. 案情固定",
      desc: "把时间线、人物、地点、金额、关键行为讲清楚，先固定事实基础。",
      done: hasFacts,
      actions: ["按时间顺序整理事实", "标出争议焦点和核心诉求", "不要先下结论，先讲事实和证据"],
    },
    {
      title: "2. 主体与身份材料",
      desc: "确认当事人身份、对方主体信息、管辖或主管部门。",
      done: hasFacts,
      actions: ["准备身份证/营业执照/授权材料", "查询对方身份或企业登记", "确认找哪个部门或法院/仲裁委"],
    },
    {
      title: "3. 证据收集与补强",
      desc: "围绕证明目的收集原件、盖章件、电子证据原始载体。",
      done: hasEvidence,
      actions: ["上传合同、聊天、付款、照片、录音等", "银行流水/社保/病历等尽量获取盖章件", "制作证据目录并编号"],
    },
    {
      title: "4. 法律分析与风险判断",
      desc: "根据事实和证据判断请求基础、法律依据、风险和胜算。",
      done: hasAnalysis,
      actions: ["运行 AI 分析", "核对法条和争议焦点", "识别证据缺口和对方可能抗辩"],
    },
    {
      title: "5. 协商/投诉/立案路径",
      desc: "选择调解、投诉、仲裁、诉讼等路径，并准备申请材料。",
      done: hasAnalysis,
      actions: ["先发书面催告或投诉", "准备申请书/起诉状/证据副本", "注意期限、管辖和送达地址"],
    },
    {
      title: "6. 庭前与表达准备",
      desc: "形成策略、质证意见、发问提纲和庭审陈述。",
      done: hasDefense,
      actions: ["生成辩护/应对材料", "准备可讲与不可讲清单", "模拟对方提问和法官追问"],
    },
    {
      title: "7. 执行与结案归档",
      desc: "取得裁判/调解结果后，跟进履行、执行和材料归档。",
      done: closed,
      actions: ["保存裁判文书/调解书", "对方不履行时申请执行", "归档证据和关键经验"],
    },
  ];
  const currentIndex = items.findIndex((s) => !s.done);
  return items.map((s, i) => ({ ...s, current: i === (currentIndex === -1 ? items.length - 1 : currentIndex) }));
}

export default function FlowGuidePage() {
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const { getCasesByUser, getEvidences, getAnalysis, getDefense } = useCaseStore();
  const userId = currentUser?.id || "user-001";
  const cases = getCasesByUser(userId).sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
  const [selectedCaseId, setSelectedCaseId] = useState(cases[0]?.id || "");
  const [query, setQuery] = useState("");

  const selectedCase = cases.find((c) => c.id === selectedCaseId) || cases[0];
  const activeCaseId = selectedCase?.id || "";
  const evidences = activeCaseId ? getEvidences(activeCaseId) : [];
  const analysis = activeCaseId ? getAnalysis(activeCaseId) : undefined;
  const defense = activeCaseId ? getDefense(activeCaseId) : undefined;
  const guidePack = useMemo(() => caseGuidePack(selectedCase), [selectedCase]);
  const steps = useMemo(() => buildGuideSteps(selectedCase, evidences.length, !!analysis, !!defense), [selectedCase, evidences.length, analysis, defense]);
  const currentStep = steps.find((s) => s.current) || steps[0];

  const filteredCases = useMemo(() => {
    const k = query.trim().toLowerCase();
    if (!k) return cases;
    return cases.filter((c) => c.title.toLowerCase().includes(k) || c.type.toLowerCase().includes(k) || c.parties.toLowerCase().includes(k));
  }, [cases, query]);

  const cardStyle = { background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(99,102,241,0.15)" };

  return (
    <div className="h-full flex" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <aside className="w-[340px] shrink-0 h-full border-r border-indigo-500/15 flex flex-col" style={{ background: "linear-gradient(180deg,#080c20,#0a1230)" }}>
        <div className="p-4 border-b border-white/5">
          <div className="flex items-center gap-2 mb-3">
            <BookOpen className="w-5 h-5 text-cyan-300" />
            <div>
              <h2 className="text-white font-bold text-[16px]">流程指导</h2>
              <p className="text-[11px] text-slate-400">左侧选案件，右侧给出全过程指引</p>
            </div>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/35" />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="搜索案件..." className="w-full pl-9 pr-3 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-white placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-cyan-500/30" />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-2">
          {filteredCases.map((c) => {
            const active = c.id === activeCaseId;
            const evidenceCount = getEvidences(c.id).length;
            const hasAnalysis = !!getAnalysis(c.id);
            const hasDefense = !!getDefense(c.id);
            return (
              <button key={c.id} onClick={() => setSelectedCaseId(c.id)} className="w-full text-left rounded-2xl p-3 transition-all" style={{ background: active ? "linear-gradient(135deg, rgba(6,182,212,0.18), rgba(61,100,176,0.16))" : "rgba(255,255,255,0.04)", border: active ? "1px solid rgba(6,182,212,0.45)" : "1px solid rgba(255,255,255,0.08)" }}>
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 rounded-xl flex items-center justify-center bg-gradient-to-br from-cyan-500 to-blue-600 text-white shrink-0">
                    <FileText className="w-4 h-4" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="text-[13px] font-bold text-white truncate">{c.title}</div>
                    <div className="text-[10px] text-slate-400 mt-0.5 truncate">{c.type} · {c.parties}</div>
                    <div className="mt-2 flex items-center gap-1.5 flex-wrap text-[10px]">
                      <span className="px-2 py-0.5 rounded-full bg-white/5 text-slate-300 border border-white/10">{statusLabel(c.status)}</span>
                      <span className="px-2 py-0.5 rounded-full bg-cyan-500/15 text-cyan-200 border border-cyan-500/25">证据 {evidenceCount}</span>
                      {hasAnalysis && <span className="px-2 py-0.5 rounded-full bg-indigo-500/15 text-indigo-200 border border-indigo-500/25">已分析</span>}
                      {hasDefense && <span className="px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-200 border border-emerald-500/25">已成稿</span>}
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
          {filteredCases.length === 0 && <div className="text-center text-slate-500 text-sm py-10">没有匹配案件</div>}
        </div>
      </aside>

      <main className="flex-1 min-w-0 h-full overflow-y-auto p-6">
        {!selectedCase ? (
          <div className="h-full flex items-center justify-center text-slate-400">暂无案件，请先创建案件</div>
        ) : (
          <div className="space-y-5">
            <section className="rounded-2xl p-5" style={{ background: "linear-gradient(135deg,#0a1430,#101a3f)", border: "1px solid rgba(6,182,212,0.22)" }}>
              <div className="flex items-start justify-between gap-4 flex-wrap">
                <div>
                  <h1 className="text-xl font-bold text-white flex items-center gap-2"><BookOpen className="w-5 h-5 text-cyan-300" />{selectedCase.title} · 流程指导</h1>
                  <p className="text-[12px] text-slate-400 mt-1">{selectedCase.type} · {selectedCase.parties}</p>
                  <p className="text-[12px] text-slate-300/90 mt-3 max-w-3xl leading-relaxed">本模块按“事实固定 → 材料补强 → 法律分析 → 路径选择 → 庭前准备 → 执行归档”给出办案全过程指引。请始终坚持实事求是，不伪造证据、不虚假陈述、不诱导证人作假。</p>
                </div>
                <div className="rounded-2xl px-4 py-3 text-right" style={{ background: "rgba(6,182,212,0.08)", border: "1px solid rgba(6,182,212,0.25)" }}>
                  <div className="text-[10px] text-cyan-200/70">当前阶段</div>
                  <div className="text-white font-bold mt-1">{currentStep?.title}</div>
                  <div className="text-[11px] text-slate-400 mt-1">案件进度 {selectedCase.progress}%</div>
                </div>
              </div>
            </section>

            <section className="grid xl:grid-cols-7 gap-4">
              <div className="xl:col-span-4 rounded-2xl p-5" style={cardStyle}>
                <div className="flex items-center gap-2 mb-4 text-white font-bold"><Scale className="w-4 h-4 text-cyan-300" />案件全过程步骤</div>
                <div className="space-y-3">
                  {steps.map((s, i) => (
                    <div key={s.title} className="rounded-2xl p-4" style={{ background: s.current ? "rgba(6,182,212,0.10)" : s.done ? "rgba(16,185,129,0.06)" : "rgba(255,255,255,0.035)", border: s.current ? "1px solid rgba(6,182,212,0.45)" : s.done ? "1px solid rgba(16,185,129,0.25)" : "1px solid rgba(255,255,255,0.08)" }}>
                      <div className="flex items-start gap-3">
                        <div className="w-8 h-8 rounded-xl flex items-center justify-center shrink-0" style={{ background: s.done ? "rgba(16,185,129,0.18)" : s.current ? "rgba(6,182,212,0.18)" : "rgba(148,163,184,0.12)", color: s.done ? "#6ee7b7" : s.current ? "#67e8f9" : "#94a3b8" }}>
                          {s.done ? <CheckCircle className="w-4 h-4" /> : <span className="text-xs font-bold">{i + 1}</span>}
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2 flex-wrap">
                            <h3 className="text-white font-bold text-sm">{s.title}</h3>
                            {s.current && <span className="px-2 py-0.5 rounded-full text-[10px] bg-cyan-500/15 text-cyan-200 border border-cyan-500/25">当前应重点处理</span>}
                            {s.done && <span className="px-2 py-0.5 rounded-full text-[10px] bg-emerald-500/15 text-emerald-200 border border-emerald-500/25">已具备基础</span>}
                          </div>
                          <p className="text-[12px] text-slate-300 mt-1 leading-relaxed">{s.desc}</p>
                          <ul className="mt-2 grid md:grid-cols-3 gap-2">
                            {s.actions.map((a) => <li key={a} className="text-[11px] text-slate-300/90 flex gap-1.5"><span className="w-1 h-1 rounded-full bg-cyan-300 mt-1.5 shrink-0" />{a}</li>)}
                          </ul>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="xl:col-span-3 space-y-4">
                <section className="rounded-2xl p-5" style={cardStyle}>
                  <div className="flex items-center gap-2 mb-3 text-white font-bold"><Sparkles className="w-4 h-4 text-amber-300" />下一步该做什么</div>
                  <p className="text-[12px] text-slate-300 leading-relaxed mb-3">当前重点：{currentStep?.desc}</p>
                  <ul className="space-y-2">{currentStep?.actions.map((a) => <li key={a} className="rounded-xl px-3 py-2 text-[12px] text-slate-200 flex gap-2" style={{ background: "rgba(6,182,212,0.07)", border: "1px solid rgba(6,182,212,0.16)" }}><CheckCircle className="w-3.5 h-3.5 text-cyan-300 shrink-0 mt-0.5" />{a}</li>)}</ul>
                </section>

                <section className="rounded-2xl p-5" style={cardStyle}>
                  <div className="flex items-center gap-2 mb-3 text-white font-bold"><ShieldAlert className="w-4 h-4 text-rose-300" />法律底线提醒</div>
                  <ul className="space-y-2 text-[12px] text-slate-300 leading-relaxed">
                    <li>所有陈述必须以真实事实为基础；不确定就说“需要核实”。</li>
                    <li>不得伪造、变造、补做证据，不得诱导证人作假。</li>
                    <li>不要在微信、电话、调解中随意承认放弃权利或扩大责任。</li>
                    <li>重大复杂案件建议委托执业律师正式代理。</li>
                  </ul>
                </section>
              </div>
            </section>

            <section className="grid lg:grid-cols-3 gap-4">
              <GuideCard title="需要补充的材料" icon={<FileText className="w-4 h-4 text-amber-300" />} items={guidePack.materials} />
              <GuideCard title="可联系的部门/机构" icon={<Gavel className="w-4 h-4 text-indigo-300" />} items={guidePack.departments} />
              <GuideCard title="建议盖章或固定的材料" icon={<CheckCircle className="w-4 h-4 text-emerald-300" />} items={guidePack.stamped} />
            </section>

            <section className="grid lg:grid-cols-2 gap-4">
              <GuideCard title="可以这样讲" icon={<MessageSquare className="w-4 h-4 text-emerald-300" />} items={guidePack.speakAllowed} tone="green" />
              <GuideCard title="不要这样讲" icon={<AlertTriangle className="w-4 h-4 text-rose-300" />} items={guidePack.speakAvoid} tone="red" />
            </section>

            <section className="rounded-2xl p-5" style={{ background: "rgba(245,158,11,0.08)", border: "1px solid rgba(245,158,11,0.22)" }}>
              <div className="flex items-start gap-3">
                <Users className="w-5 h-5 text-amber-300 shrink-0 mt-0.5" />
                <div>
                  <div className="text-sm font-bold text-amber-100">专业提示</div>
                  <p className="text-[12px] text-amber-100/85 leading-relaxed mt-1">本流程指导用于帮助当事人理解案件推进路径和材料准备方向，仅供参考，不构成正式法律意见。实际案件需结合证据原件、时效、管辖、当地裁判规则和律师阅卷/会见情况判断。</p>
                </div>
              </div>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

function GuideCard({ title, icon, items, tone = "blue" }: { title: string; icon: React.ReactNode; items: string[]; tone?: "blue" | "green" | "red" }) {
  const color = tone === "green" ? "rgba(16,185,129,0.14)" : tone === "red" ? "rgba(244,63,94,0.12)" : "rgba(99,102,241,0.10)";
  const border = tone === "green" ? "rgba(16,185,129,0.28)" : tone === "red" ? "rgba(244,63,94,0.28)" : "rgba(99,102,241,0.18)";
  return (
    <section className="rounded-2xl p-5" style={{ background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(99,102,241,0.15)" }}>
      <div className="flex items-center gap-2 mb-3 text-white font-bold">{icon}{title}</div>
      <ul className="space-y-2">
        {items.map((item) => (
          <li key={item} className="rounded-xl px-3 py-2 text-[12px] text-slate-200 leading-relaxed flex gap-2" style={{ background: color, border: `1px solid ${border}` }}>
            <span className="w-1.5 h-1.5 rounded-full bg-current mt-1.5 shrink-0 opacity-70" />
            <span>{item}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}
