import { create } from "zustand";

export type Role = "super_admin" | "vip" | "user";

export interface UserPermissions {
  chat?: boolean;
  cases?: boolean;
  guide?: boolean;
  analysis?: boolean;
  evidence?: boolean;
  defense?: boolean;
  laws?: boolean;
  knowledge?: boolean;
  help?: boolean;
  admin?: boolean;
}

export interface SysUser {
  id: string;
  name: string;
  email: string;
  role: Role;
  avatar: string;
  phone?: string;
  password?: string;
  expireAt?: string;
  dailyLimit?: number;
  permissions: UserPermissions;
}

export const TEMPLATES: Record<Role, UserPermissions> = {
  super_admin: {
    chat: true,
    cases: true,
    guide: true,
    analysis: true,
    evidence: true,
    defense: true,
    laws: true,
    knowledge: true,
    help: true,
    admin: true,
  },
  vip: {
    chat: true,
    cases: true,
    guide: true,
    analysis: true,
    evidence: true,
    defense: true,
    laws: true,
    help: true,
  },
  user: {
    chat: true,
    cases: true,
    guide: true,
    analysis: true,
    evidence: true,
  },
};

