const allUsers: SysUser[] = [superAdmin, vipUser, normalUser, normalUser2];

function loadFromStorage(key: string, fallback: SysUser | SysUser[]) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch {
    return fallback;
  }
}

interface AppState {
  users: SysUser[];
  currentUserId: string | null;
  currentUser: SysUser | null;
  loginAsUser: (identifier: string, password: string) => { ok: boolean; msg?: string };
  loginAsAdmin: (password: string) => { ok: boolean; msg?: string };
  logout: () => void;
  getCurrentUser: () => SysUser | null;
  applyTemplate: (userId: string, role: Role) => void;
  togglePerm: (userId: string, key: keyof UserPermissions) => void;
  updateUserField: (userId: string, field: "expireAt" | "dailyLimit" | "password" | "email" | "name", value: string | number) => void;
  addUser: (u: Omit<SysUser, "id" | "permissions"> & { role: Role; permissions?: UserPermissions }) => void;
  removeUser: (userId: string) => void;
  resetToDefaults: () => void;
}

const STORAGE_USERS = "ailawyer_users_v1";
const STORAGE_CURRENT = "ailawyer_current_v1";

export const useAppStore = create<AppState>((set, get) => {
  const persistedUsers = (loadFromStorage(STORAGE_USERS, allUsers) as SysUser[]).map((u) => ({
    ...u,
    permissions: { ...TEMPLATES[u.role], ...u.permissions },
  }));
  const persistedCurrent = loadFromStorage(STORAGE_CURRENT, null) as string | null;

  const persistUsers = (users: SysUser[]) => {
    try { localStorage.setItem(STORAGE_USERS, JSON.stringify(users)); } catch {}
  };
  const persistCurrent = (id: string | null) => {
    try { if (id) localStorage.setItem(STORAGE_CURRENT, id); else localStorage.removeItem(STORAGE_CURRENT); } catch {}
  };

  const computeCurrentUser = (users: SysUser[], id: string | null): SysUser | null => {
    if (!id) return null;
    return users.find((u) => u.id === id) || null;
  };

  return {
    users: persistedUsers,
    currentUserId: persistedCurrent,
    currentUser: computeCurrentUser(persistedUsers, persistedCurrent),

    loginAsUser: (identifier, password) => {
      const users = get().users;
      const u = users.find(
        (x) => (x.email === identifier || x.phone === identifier || x.id === identifier) && x.password === password
      );
      if (!u) return { ok: false, msg: "账号或密码错误" };
      if (u.role === "super_admin") return { ok: false, msg: "超级管理员请在后台管理系统登录" };
      set({ currentUserId: u.id, currentUser: u });
      persistCurrent(u.id);
      return { ok: true };
    },

    loginAsAdmin: (password) => {
      const users = get().users;
      const u = users.find((x) => x.role === "super_admin");
      if (!u) return { ok: false, msg: "系统未初始化" };
      if (u.password !== password) return { ok: false, msg: "管理员密码错误" };
      set({ currentUserId: u.id, currentUser: u });
      persistCurrent(u.id);
      return { ok: true };
    },

    logout: () => {
      set({ currentUserId: null, currentUser: null });
      persistCurrent(null);
    },

    getCurrentUser: () => get().currentUser,

    applyTemplate: (userId, role) => {
      const template = TEMPLATES[role];
      set((s) => {
        const users = s.users.map((u) =>
          u.id === userId ? { ...u, role, permissions: { ...template } } : u
        );
        persistUsers(users);
        return { users };
      });
    },

    togglePerm: (userId, key) => {
      set((s) => {
        const users = s.users.map((u) =>
          u.id === userId ? { ...u, permissions: { ...u.permissions, [key]: !u.permissions[key] } } : u
        );
        persistUsers(users);
        return { users };
      });
    },

    updateUserField: (userId, field, value) => {
      set((s) => {
        const users = s.users.map((u) => (u.id === userId ? { ...u, [field]: value } : u));
        persistUsers(users);
        return { users };
      });
    },

    addUser: (u) => {
      const id = `user-${Date.now()}`;
      const avatar = (u.name || "U").slice(-1);
      set((s) => {
        const user: SysUser = {
          id,
          name: u.name,
          email: u.email,
          role: u.role,
          avatar,
          phone: u.phone,
          password: u.password || "123456",
          expireAt: u.expireAt,
          dailyLimit: u.dailyLimit,
          permissions: u.permissions ? { ...u.permissions } : { ...TEMPLATES[u.role] },
        };
        const users = [...s.users, user];
        persistUsers(users);
        return { users };
      });
    },

    removeUser: (userId) => {
      if (userId === "admin-001") return;
      set((s) => {
        const users = s.users.filter((u) => u.id !== userId);
        persistUsers(users);
        return { users };
      });
    },

    resetToDefaults: () => {
      set({ users: allUsers });
      persistUsers(allUsers);
    },
  };
});
