import { useMemo, useRef, useState } from "react";
import { BookOpen, CheckCircle, Database, Edit3, FileSearch, FileText, FileUp, Headphones, Image, Plus, Save, Search, ShieldAlert, Trash2, Video, X } from "lucide-react";
import Modal from "../components/Modal";
import { EvidenceItem, useCaseStore, DOC_CATEGORY_META, DocCategory } from "../store/caseStore";
import { getMissingMaterials } from "../lib/materialGuide";
import { useAppStore } from "../store/appStore";

type EvidenceType = EvidenceItem["type"];

const TYPE_META: Record<EvidenceType, { label: string; icon: React.ReactNode; color: string }> = {
  document: { label: "文档", icon: <FileText className="w-4 h-4" />, color: "from-amber-500 to-orange-600" },
  image: { label: "图片", icon: <Image className="w-4 h-4" />, color: "from-emerald-500 to-teal-600" },
  audio: { label: "录音", icon: <Headphones className="w-4 h-4" />, color: "from-sky-500 to-blue-600" },
  video: { label: "录像", icon: <Video className="w-4 h-4" />, color: "from-rose-500 to-red-600" },
};

const TYPE_ORDER: EvidenceType[] = ["document", "image", "audio", "video"];

function buildEvidenceFromFile(file: File): Omit<EvidenceItem, "id" | "caseId" | "uploadedAt"> {
  const ext = file.name.toLowerCase();
  const type: EvidenceType = ext.match(/\.(jpg|jpeg|png|gif|webp)$/) ? "image" : ext.match(/\.(mp3|wav|m4a)$/) ? "audio" : ext.match(/\.(mp4|mov|avi)$/) ? "video" : "document";
  return {
    name: file.name,
    type,
    aiSummary: `用户上传的${TYPE_META[type].label}材料，文件名：${file.name}。`,
    aiIssues: ["请核对原件真实性、来源合法性和与本案争议焦点的关联性"],
  };
}

export default function EvidencePage({ initialCaseId }: { initialCaseId?: string }) {
  const currentUser = useAppStore((s) => s.getCurrentUser());
  const {
    getCasesByUser,
    getEvidences,
    addEvidence,
    updateEvidence,
    removeEvidence,
    getUserDocs,
    getUserDocById,
    linkDocToCase,
  } = useCaseStore();

  const userId = currentUser?.id || "user-001";
  const cases = getCasesByUser(userId).sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
  const [selectedCaseId, setSelectedCaseId] = useState(initialCaseId || cases[0]?.id || "");
  const selectedCase = cases.find((c) => c.id === selectedCaseId) || cases[0];
  const activeCaseId = selectedCase?.id || "";
  const evidences = activeCaseId ? getEvidences(activeCaseId) : [];
  const library = currentUser ? getUserDocs(currentUser.id).filter((d) => d.verified) : [];

  const [query, setQuery] = useState("");
  const [docOpen, setDocOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [editing, setEditing] = useState<EvidenceItem | null>(null);
  const [form, setForm] = useState({ name: "", type: "document" as EvidenceType, aiSummary: "", aiIssues: "" });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCases = useMemo(() => {
    const k = query.trim().toLowerCase();
    if (!k) return cases;
    return cases.filter((c) => c.title.toLowerCase().includes(k) || c.type.toLowerCase().includes(k) || c.parties.toLowerCase().includes(k));
  }, [cases, query]);

  const grouped = useMemo(() => {
    return TYPE_ORDER.map((type) => ({ type, items: evidences.filter((e) => e.type === type) })).filter((g) => g.items.length > 0);
  }, [evidences]);

  const missingMaterials = useMemo(() => getMissingMaterials(selectedCase, evidences), [selectedCase, evidences]);

  const openMissingMaterial = (name: string) => {
    setEditing(null);
    setForm({
      name,
      type: "document",
      aiSummary: `补充${name}，用于完善当前案件证据链。`,
      aiIssues: "请上传原件扫描件、官方盖章件或完整电子证据原始记录",
    });
    setEditOpen(true);
  };

  const openEdit = (item?: EvidenceItem) => {
    if (item) {
      setEditing(item);
      setForm({ name: item.name, type: item.type, aiSummary: item.aiSummary || "", aiIssues: (item.aiIssues || []).join("\n") });
    } else {
      setEditing(null);
      setForm({ name: "", type: "document", aiSummary: "", aiIssues: "" });
    }
    setEditOpen(true);
  };

  const submitEvidence = () => {
    if (!activeCaseId || !form.name.trim()) return;
    const patch = {
      name: form.name.trim(),
      type: form.type,
      aiSummary: form.aiSummary.trim(),
      aiIssues: form.aiIssues.split("\n").map((s) => s.trim()).filter(Boolean),
    };
    if (editing) updateEvidence(editing.id, patch);
    else addEvidence(activeCaseId, patch);
    setEditOpen(false);
    setEditing(null);
    setForm({ name: "", type: "document", aiSummary: "", aiIssues: "" });
  };

  const onFilesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!activeCaseId) return;
    Array.from(e.target.files || []).forEach((file) => addEvidence(activeCaseId, buildEvidenceFromFile(file)));
    e.target.value = "";
  };

  const addQuick = (type: EvidenceType) => {
    if (!activeCaseId) return;
    addEvidence(activeCaseId, {
      name: `${TYPE_META[type].label}证据 ${evidences.length + 1}`,
      type,
      aiSummary: `新增${TYPE_META[type].label}证据，待补充具体证明内容。`,
      aiIssues: ["请补充证明目的、取得来源和形成时间"],
    });
  };

  const pickFromLibrary = (docId: string) => {
    if (!activeCaseId) return;
    const doc = getUserDocById(docId);
    if (!doc) return;
    linkDocToCase(docId, activeCaseId);
    setDocOpen(false);
  };

  const cardStyle = { background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(99,102,241,0.15)" };

  return (
    <div className="h-full flex" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <input ref={fileInputRef} type="file" multiple hidden accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png,.mp3,.mp4,.wav,.mov" onChange={onFilesChange} />

      <aside className="w-[340px] shrink-0 h-full border-r border-indigo-500/15 flex flex-col" style={{ background: "linear-gradient(180deg,#080c20,#0a1230)" }}>
        <div className="p-4 border-b border-white/5">
          <div className="flex items-center gap-2 mb-3">
            <ShieldAlert className="w-5 h-5 text-amber-300" />
            <div>
              <h2 className="text-white font-bold text-[16px]">证据管理</h2>
              <p className="text-[11px] text-slate-400">左侧选案件，右侧直接维护证据</p>
            </div>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/35" />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="搜索案件..." className="w-full pl-9 pr-3 py-2 rounded-xl bg-white/5 border border-white/10 text-sm text-white placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-indigo-500/30" />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-2">
          {filteredCases.map((c) => {
            const active = c.id === activeCaseId;
            const count = getEvidences(c.id).length;
            return (
              <button key={c.id} onClick={() => setSelectedCaseId(c.id)} className="w-full text-left rounded-2xl p-3 transition-all" style={{ background: active ? "linear-gradient(135deg, rgba(212,175,55,0.2), rgba(61,100,176,0.16))" : "rgba(255,255,255,0.04)", border: active ? "1px solid rgba(212,175,55,0.45)" : "1px solid rgba(255,255,255,0.08)" }}>
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 rounded-xl flex items-center justify-center bg-gradient-to-br from-amber-500 to-orange-600 text-white shrink-0">
                    <FileText className="w-4 h-4" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="text-[13px] font-bold text-white truncate">{c.title}</div>
                    <div className="text-[10px] text-slate-400 mt-0.5 truncate">{c.type} · {c.parties}</div>
                    <div className="mt-2 flex items-center justify-between text-[10px]">
                      <span className="text-slate-500">{c.updatedAt}</span>
                      <span className="px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-200 border border-amber-500/25">{count} 份证据</span>
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
          {filteredCases.length === 0 && <div className="text-center text-slate-500 text-sm py-10">没有匹配案件</div>}
        </div>
      </aside>

      <main className="flex-1 min-w-0 h-full overflow-y-auto p-6">
        {!selectedCase ? (
          <div className="h-full flex items-center justify-center text-slate-400">暂无案件，请先创建案件</div>
        ) : (
          <div className="space-y-5">
            <div className="flex items-start justify-between gap-4 flex-wrap">
              <div>
                <h1 className="text-xl font-bold text-white">{selectedCase.title}</h1>
                <p className="text-[12px] text-slate-400 mt-1">{selectedCase.type} · {selectedCase.parties}</p>
                <p className="text-[11px] text-slate-500 mt-1">证据按类型分类展示，可在右侧直接编辑、提交或删除。</p>
              </div>
              <div className="flex items-center gap-2 flex-wrap">
                <button onClick={() => setDocOpen(true)} disabled={library.length === 0} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold disabled:opacity-40 disabled:cursor-not-allowed" style={{ background: "linear-gradient(135deg,#f59e0b,#eab308)", color: "#1c1917" }}>
                  <Database className="w-4 h-4" /> 从材料库引用
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-indigo-600 to-violet-600">
                  <FileUp className="w-4 h-4" /> 上传证据
                </button>
                <button onClick={() => openEdit()} className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-emerald-600 to-teal-600">
                  <Plus className="w-4 h-4" /> 手动新增
                </button>
              </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {TYPE_ORDER.map((type) => (
                <button key={type} onClick={() => addQuick(type)} className={`rounded-2xl p-4 text-left bg-gradient-to-br ${TYPE_META[type].color} text-white shadow-md hover:-translate-y-0.5 transition-all`}>
                  <div className="flex items-center gap-2 text-sm font-bold">{TYPE_META[type].icon}{TYPE_META[type].label}</div>
                  <div className="text-[11px] opacity-80 mt-1">快速新增一份{TYPE_META[type].label}证据</div>
                </button>
              ))}
            </div>

            {missingMaterials.length > 0 && (
              <section className="rounded-2xl p-4" style={{ background: "rgba(245,158,11,0.08)", border: "1px solid rgba(245,158,11,0.28)" }}>
                <div className="flex items-start justify-between gap-3 flex-wrap">
                  <div>
                    <div className="text-sm font-bold text-amber-100 flex items-center gap-2"><ShieldAlert className="w-4 h-4 text-amber-300" /> 当前案件还缺少关键材料</div>
                    <p className="text-[11px] text-amber-100/70 mt-1">点击下方材料名称，可直接进入新增/上传说明界面。</p>
                  </div>
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  {missingMaterials.map((m) => (
                    <button key={m} onClick={() => openMissingMaterial(m)} className="px-3 py-1.5 rounded-xl text-[12px] font-semibold text-amber-100 bg-amber-500/12 hover:bg-amber-500/20 border border-amber-500/25 transition-all">
                      + {m}
                    </button>
                  ))}
                </div>
              </section>
            )}

            {evidences.length === 0 ? (
              <div className="rounded-2xl p-12 flex flex-col items-center text-center" style={cardStyle}>
                <FileSearch className="w-10 h-10 text-slate-500 mb-3" />
                <p className="text-slate-300 font-semibold">当前案件还没有证据</p>
                <p className="text-[12px] text-slate-500 mt-2">可上传文件、从材料库引用，或手动新增证据。</p>
              </div>
            ) : (
              <div className="space-y-5">
                {grouped.map((group) => (
                  <section key={group.type} className="rounded-2xl p-4" style={cardStyle}>
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2 text-white font-bold text-sm">
                        <span className={`w-9 h-9 rounded-xl flex items-center justify-center text-white bg-gradient-to-br ${TYPE_META[group.type].color}`}>{TYPE_META[group.type].icon}</span>
                        {TYPE_META[group.type].label}证据
                        <span className="text-[11px] text-slate-500 font-normal">{group.items.length} 份</span>
                      </div>
                    </div>
                    <div className="space-y-3">
                      {group.items.map((e) => (
                        <div key={e.id} className="rounded-xl p-4" style={{ background: "#0a0f24", border: "1px solid rgba(99,102,241,0.12)" }}>
                          <div className="flex items-start justify-between gap-3">
                            <div className="min-w-0 flex-1">
                              <div className="flex items-center gap-2 mb-1">
                                <span className="text-white font-bold text-[14px] truncate">{e.name}</span>
                                <span className="text-[10px] text-slate-500">{e.uploadedAt}</span>
                              </div>
                              {e.aiSummary && <p className="text-[12px] text-slate-300 leading-relaxed">{e.aiSummary}</p>}
                              {e.aiIssues?.length > 0 && (
                                <ul className="mt-2 space-y-1">
                                  {e.aiIssues.map((issue, i) => <li key={i} className="text-[11px] text-rose-200/90 flex gap-1.5"><span className="mt-1.5 w-1 h-1 rounded-full bg-rose-300 shrink-0" />{issue}</li>)}
                                </ul>
                              )}
                            </div>
                            <div className="flex items-center gap-2 shrink-0">
                              <button onClick={() => openEdit(e)} className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-indigo-200 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20">
                                <Edit3 className="w-3 h-3" /> 编辑
                              </button>
                              <button onClick={() => { if (confirm(`删除证据「${e.name}」？`)) removeEvidence(e.id); }} className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-rose-200 bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/20">
                                <Trash2 className="w-3 h-3" /> 删除
                              </button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </section>
                ))}
              </div>
            )}
          </div>
        )}
      </main>

      <Modal open={editOpen} onClose={() => { setEditOpen(false); setEditing(null); setForm({ name: "", type: "document", aiSummary: "", aiIssues: "" }); }} title={editing ? "修改证据" : "新增证据"} widthClass="max-w-2xl" footer={
        <>
          {editing && <button onClick={() => { if (confirm(`删除证据「${editing.name}」？`)) { removeEvidence(editing.id); setEditOpen(false); setEditing(null); setForm({ name: "", type: "document", aiSummary: "", aiIssues: "" }); } }} className="mr-auto inline-flex items-center gap-1 px-4 py-2 rounded-xl text-sm font-bold text-rose-200 bg-rose-500/10 hover:bg-rose-500/20"><Trash2 className="w-4 h-4" /> 删除</button>}
          <button onClick={() => { setEditOpen(false); setEditing(null); setForm({ name: "", type: "document", aiSummary: "", aiIssues: "" }); }} className="px-4 py-2 rounded-xl text-sm font-medium text-white/70 hover:bg-white/10">取消</button>
          <button onClick={submitEvidence} disabled={!form.name.trim()} className="inline-flex items-center gap-1 px-5 py-2 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-indigo-600 to-violet-600 disabled:opacity-40"><Save className="w-4 h-4" /> 提交</button>
        </>
      }>
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-white/70 mb-1.5">证据名称</label>
            <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-bold text-white/70 mb-1.5">证据分类</label>
            <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value as EvidenceType })} className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none">
              {TYPE_ORDER.map((t) => <option key={t} value={t} className="bg-slate-900">{TYPE_META[t].label}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs font-bold text-white/70 mb-1.5">证据摘要 / 证明目的</label>
            <textarea value={form.aiSummary} onChange={(e) => setForm({ ...form, aiSummary: e.target.value })} rows={4} className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none resize-y" />
          </div>
          <div>
            <label className="block text-xs font-bold text-white/70 mb-1.5">风险问题（一行一个）</label>
            <textarea value={form.aiIssues} onChange={(e) => setForm({ ...form, aiIssues: e.target.value })} rows={4} className="w-full px-3 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm focus:outline-none resize-y" />
          </div>
        </div>
      </Modal>

      {docOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setDocOpen(false)}>
          <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
          <div className="relative rounded-2xl w-full max-w-4xl max-h-[86vh] flex flex-col" style={{ background: "linear-gradient(180deg, #0a1430 0%, #070c1f 100%)", border: "1px solid rgba(99,102,241,0.25)" }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between px-5 py-3 border-b border-indigo-500/15">
              <div className="flex items-center gap-2"><Database className="w-4 h-4 text-amber-300" /><h3 className="font-bold text-white text-[15px]">从材料库引用到当前案件</h3></div>
              <button onClick={() => setDocOpen(false)} className="w-8 h-8 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 flex items-center justify-center"><X className="w-4 h-4" /></button>
            </div>
            <div className="flex-1 overflow-y-auto px-5 py-4">
              {library.length === 0 ? <div className="p-10 text-center text-slate-400">暂无已实名认证材料</div> : (
                <div className="grid md:grid-cols-2 gap-3">
                  {library.map((d) => {
                    const meta = DOC_CATEGORY_META[d.category as DocCategory];
                    return (
                      <div key={d.id} className="rounded-2xl p-4" style={{ background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)", border: "1px solid rgba(16,185,129,0.35)" }}>
                        <div className="flex items-center gap-2.5">
                          <div className="w-10 h-10 rounded-xl flex items-center justify-center text-lg" style={{ background: `${meta.color}22`, border: `1px solid ${meta.color}33` }}>{meta.icon}</div>
                          <div className="min-w-0 flex-1"><div className="text-[13px] font-bold text-white truncate">{d.name}</div><div className="text-[10px] text-emerald-300 flex items-center gap-1"><CheckCircle className="w-3 h-3" /> 已实名 · {d.uploadedAt}</div></div>
                        </div>
                        <p className="mt-2 text-[11.5px] text-slate-300 leading-relaxed">{d.summary}</p>
                        <button onClick={() => pickFromLibrary(d.id)} className="mt-3 w-full py-2 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-amber-500 to-amber-600"><Plus className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />引用到本案证据</button>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
