import type { Case, EvidenceItem } from "../store/caseStore";

export function getRequiredMaterials(caseObj?: Case): string[] {
  const text = `${caseObj?.type || ""}${caseObj?.title || ""}${caseObj?.facts || ""}`;

  if (/劳动|工资|辞退|解除|工伤|社保|仲裁/.test(text)) {
    return ["劳动合同", "工资银行流水", "解除/辞退通知或聊天记录", "社保缴费记录", "考勤或工作证明"];
  }
  if (/交通|事故|车祸|保险|交警|伤残|医疗|骨折/.test(text)) {
    return ["事故认定书", "病历/诊断证明", "医疗费发票", "误工证明", "保险信息"];
  }
  if (/房屋|买卖|开发商|合同|定金|违约|退款|租赁/.test(text)) {
    return ["合同原件", "付款凭证", "催告/解除通知", "对方主体信息", "违约事实证明"];
  }
  if (/消费|购物|商家|平台|欺诈|退款|商品|假货/.test(text)) {
    return ["订单截图", "支付凭证", "商品宣传页面", "商品问题照片/视频", "客服沟通记录"];
  }

  return ["身份证明", "合同或书面材料", "付款/损失凭证", "聊天记录", "对方身份或主体信息"];
}

export function getMissingMaterials(caseObj: Case | undefined, evidences: EvidenceItem[]): string[] {
  const required = getRequiredMaterials(caseObj);
  const names = evidences.map((e) => `${e.name}${e.aiSummary || ""}`).join(" ");

  return required.filter((item) => {
    const keys = item.split(/[\/、或和 ]/).filter(Boolean);
    return !keys.some((k) => names.includes(k));
  });
}
