import { useEffect } from "react";

interface Props {
  open: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
  widthClass?: string;
  footer?: React.ReactNode;
  hideClose?: boolean;
}

export default function Modal({ open, onClose, title, children, widthClass = "max-w-lg", footer, hideClose }: Props) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={onClose} />
      <div className={`relative rounded-2xl shadow-2xl w-full ${widthClass} max-h-[90vh] flex flex-col animate-fade-in`}
        style={{
          background: "linear-gradient(180deg, #0a1430 0%, #070c1f 100%)",
          border: "1px solid rgba(99,102,241,0.25)",
          boxShadow: "0 20px 60px rgba(0,0,0,0.7), 0 0 40px rgba(61,100,176,0.15)",
        }}
      >
        {title && (
          <div className="flex items-center justify-between px-6 py-4 shrink-0" style={{ borderBottom: "1px solid rgba(99,102,241,0.15)" }}>
            <h3 className="font-bold text-white text-[15px]" style={{ fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>{title}</h3>
            {!hideClose && (
              <button
                onClick={onClose}
                className="w-8 h-8 rounded-lg transition-colors text-slate-400 hover:text-white hover:bg-white/5"
              >
                ✕
              </button>
            )}
          </div>
        )}
        <div className="px-6 py-5 overflow-y-auto flex-1 text-slate-100">{children}</div>
        {footer && <div className="px-6 py-4 shrink-0 flex justify-end gap-2" style={{ borderTop: "1px solid rgba(99,102,241,0.15)" }}>{footer}</div>}
      </div>
    </div>
  );
}
