import { Scale, Search, ChevronDown } from "lucide-react";
import { useState } from "react";
import { useCaseStore } from "../../store/caseStore";
import { lawLibrary, searchLaws } from "../../lib/lawLibrary";
import { mdToHtml } from "../../lib/md";

interface Props { caseId?: string; standalone?: boolean }

export default function CitationTab({ caseId, standalone }: Props) {
  const { getAnalysis } = useCaseStore();
  const analysis = caseId ? getAnalysis(caseId) : undefined;
  const [expanded, setExpanded] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const filtered = search ? searchLaws(search) : lawLibrary;

  const cardStyle = {
    background: "linear-gradient(180deg, #111a3c 0%, #0e1532 100%)",
    border: "1px solid rgba(99,102,241,0.15)",
    borderRadius: "16px",
  };

  if (!standalone && caseId) {
    if (!analysis || analysis.applicableLaws.length === 0) {
      return (
        <div className="p-10 flex flex-col items-center justify-center text-center" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
          <div className="w-16 h-16 rounded-2xl flex items-center justify-center mb-3"
            style={{ background: "rgba(99,102,241,0.1)" }}>
            <Scale className="w-7 h-7 text-slate-500" />
          </div>
          <p className="text-slate-300 mb-1">案件尚未 AI 分析</p>
          <p className="text-xs text-slate-500">先运行 AI 分析，自动会匹配适用法条</p>
        </div>
      );
    }
    return (
      <div className="p-6 space-y-4" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
        <div className="text-xs font-semibold text-slate-300 px-1">本案适用法条（来自 AI 分析）</div>
        {analysis.applicableLaws.map((l, i) => {
          const lib = lawLibrary.find((x) => x.id === l.lawId);
          return (
            <div key={i} className="rounded-2xl overflow-hidden"
              style={{ background: "#0e1532", border: "1px solid rgba(99,102,241,0.15)" }}>
              <button
                onClick={() => setExpanded(expanded === l.lawId ? null : l.lawId)}
                className="w-full flex items-start gap-3 p-4 text-left transition-colors hover:bg-white/5"
              >
                <div className="flex-1 min-w-0">
                  <div className="text-[13px] font-bold text-white">{l.law}</div>
                  <div className="text-[11px] text-slate-400 mt-0.5">{l.summary}</div>
                  <div className="text-[11px] mt-0.5" style={{ color: "#a5b4fc" }}>AI 判断理由：{l.reason}</div>
                </div>
                <ChevronDown className={`w-4 h-4 text-slate-400 shrink-0 mt-0.5 transition-transform ${expanded === l.lawId ? "rotate-180" : ""}`} />
              </button>
              {expanded === l.lawId && lib && (
                <div className="px-4 pb-4" style={{ borderTop: "1px solid rgba(99,102,241,0.15)" }}>
                  <div className="mt-3 text-[11px] text-slate-500 mb-1">{lib.fullName}</div>
                  <div
                    className="prose prose-sm max-w-none text-[13px] text-slate-100 leading-relaxed"
                    dangerouslySetInnerHTML={{ __html: mdToHtml(lib.content) }}
                  />
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  return (
    <div className="p-6 space-y-4" style={{ background: "#0a0f24", fontFamily: "\"Microsoft YaHei\", \"微软雅黑\", sans-serif" }}>
      <div className="flex items-center gap-3">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="搜索法条名称、条文、关键词..."
            className="w-full pl-10 pr-4 py-2 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500/30 transition-all"
            style={{ background: "#0e1532", border: "1px solid rgba(99,102,241,0.2)", color: "#e2e8f0" }}
          />
        </div>
        <span className="text-xs text-slate-400">共 {filtered.length} 条 · 本 DEMO 精选了 {lawLibrary.length} 条常用法条</span>
      </div>

      {filtered.length === 0 ? (
        <div className="text-center text-slate-400 py-16 text-sm">没有匹配的法条，换个关键词试试</div>
      ) : (
        <div className="grid gap-2 md:grid-cols-2">
          {filtered.map((l) => (
            <button
              key={l.id}
              onClick={() => setExpanded(expanded === l.id ? null : l.id)}
              className={`text-left rounded-xl p-3 transition-all ${
                expanded === l.id ? "shadow-md" : ""
              }`}
              style={{
                background: expanded === l.id ? "#0f1a3a" : "#0e1532",
                border: expanded === l.id ? "1px solid rgba(99,102,241,0.4)" : "1px solid rgba(99,102,241,0.15)",
              }}
            >
              <div className="flex items-start gap-2">
                <div className={`w-1.5 h-6 rounded-full shrink-0 ${
                  l.category === "civil" ? "bg-emerald-500" :
                  l.category === "criminal" ? "bg-rose-500" :
                  l.category === "litigation" ? "bg-blue-500" :
                  l.category === "administrative" ? "bg-amber-500" :
                  l.category === "commercial" ? "bg-violet-500" : "bg-slate-500"
                }`} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-[13px] font-bold text-white">{l.title} {l.article}</span>
                    <span className="text-[10px] text-slate-500">{l.categoryLabel}</span>
                  </div>
                  <div className="text-[11px] text-slate-400 mt-0.5 line-clamp-2">{l.summary}</div>
                </div>
                <ChevronDown className={`w-4 h-4 text-slate-400 shrink-0 transition-transform ${expanded === l.id ? "rotate-180" : ""}`} />
              </div>
              {expanded === l.id && (
                <div className="mt-3 pt-3" style={{ borderTop: "1px solid rgba(99,102,241,0.15)" }}>
                  <div className="text-[10px] text-slate-500 mb-1">{l.fullName}</div>
                  <div
                    className="prose prose-sm max-w-none text-[13px] text-slate-100 leading-relaxed"
                    dangerouslySetInnerHTML={{ __html: mdToHtml(l.content) }}
                  />
                </div>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
